/* css/tokens.css */
/* ============================================================================
   CX Timeline — Design tokens
   ----------------------------------------------------------------------------
   The single source of truth for every visual value in the application.
   Nothing else in the codebase may use a raw hex colour: if a value you need
   does not exist here, add a token in the right category and use var(--name).

   Structure
   ---------
   1. INVARIANTS  — brand, shape, motion, spacing, typography. Identical in
                    every theme; these are what make the app feel like part of
                    the CX Portal suite regardless of palette.
   2. PALETTES    — the raw colour scales (warm neutral ink + cool slate),
                    lifted verbatim from cx-portal/styles.css so the two apps
                    share literally the same colours.
   3. THEMES      — semantic surface/text/status assignments per theme.
                    Selected with <html data-theme="dark|light|engineering|
                    blueprint|presentation">. Dark is the default.
   ========================================================================= */

/* No webfont is fetched. The faces below name Archivo and Roboto Mono first and
   fall back to the platform's own, which is what actually renders on a machine
   that does not have them installed.

   There used to be an `@import` from Google's font CDN here. It was removed for
   two reasons: the shipped Content-Security-Policy sets `style-src 'self'`, so a
   deployed build blocked it and silently used the fallbacks anyway; and it put a
   request to a third party on every page load, which is not something a plan
   this sensitive should do for the sake of a typeface. To use the real faces,
   self-host the `.woff2` files and declare them with `@font-face` — `font-src`
   already allows `'self'`. */

:root {
  /* ── 1. INVARIANTS ─────────────────────────────────────────────────────── */

  /* The look-ahead's own two greys, the ones BART's 4WLA workbook paints and
     the Excel export writes: a weekend column, and a section band. The same in
     every theme on purpose — they are the sheet's shading, not the
     interface's, and a weekend that changed shade with the theme would stop
     reading as the weekend on the sheet it came from. Writing on them is dark
     whatever the theme. */
  --la-weekend: #7f7f7f;
  --la-weekend-ink: #111111;
  --la-band: #d9d9d9;
  --la-band-ink: #111111;

  /* The cancellation log's fills, one per answer to "whose was it" — BART is
     the legend's own cancellation red, painted inline like any legend colour.
     Fixed in every theme for the same reason as the greys: the Excel export
     writes these exact fills, and the calendar on screen is that sheet. */
  --la-cancel-hitachi: #0070c0;
  --la-cancel-hitachi-ink: #ffffff;
  --la-cancel-other: #ffc000;
  --la-cancel-other-ink: #111111;
  --la-cancel-open: #e4d7f5;
  --la-cancel-open-ink: #111111;

  /* Brand — Hitachi red (shared with cx-portal) */
  --hitachi-red: #e60012;
  --hitachi-red-hover: #b80010;
  --primary: #e60012;
  --primary-hover: #b80010;

  /* Warm neutral ink scale */
  --black: #0a0a0c;
  --near-black: #131316;
  --charcoal: #1d1e22;
  --gray-900: #2a2c31;
  --gray-800: #3a3c43;
  --gray-700: #54575f;
  --gray-600: #74777f;
  --gray-500: #9a9da4;
  --gray-400: #c2c5cb;
  --gray-300: #dfe1e5;
  --gray-200: #ececef;
  --gray-100: #f4f4f6;
  --gray-50: #fafaf8;
  --white: #ffffff;

  /* Slate (cool gray) scale — dark chrome */
  --slate-950: #0b0f1a;
  --slate-900: #111827;
  --slate-850: #151d2e;
  --slate-800: #1f2937;
  --slate-750: #26313f;
  --slate-700: #374151;
  --slate-600: #4b5563;
  --slate-500: #6b7280;
  --slate-400: #9ca3af;
  --slate-300: #d1d5db;
  --slate-200: #e5e7eb;
  --slate-100: #f3f4f6;
  --slate-50: #f9fafb;

  /* Typography */
  --f-display: 'Archivo', system-ui, -apple-system, 'Segoe UI', sans-serif;
  --f-ui: 'Archivo', system-ui, -apple-system, 'Segoe UI', sans-serif;
  --f-mono: 'Roboto Mono', ui-monospace, 'SF Mono', Menlo, Consolas, monospace;
  --f-body: 'Inter', system-ui, -apple-system, 'Segoe UI', sans-serif;
  --fs-micro: 10px;
  --fs-tiny: 11px;
  --fs-small: 12px;
  --fs-base: 13px;
  --fs-body: 14px;
  --fs-lg: 16px;
  --fs-xl: 20px;
  --fs-display: 26px;

  /* Elevation / shape / motion */
  --radius-xs: 4px;
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 14px;
  --radius-xl: 20px;
  --easing: cubic-bezier(0.16, 1, 0.3, 1);
  --dur-fast: 140ms;
  --dur: 220ms;
  --dur-slow: 380ms;

  /* Spacing scale */
  --space-1: 4px;
  --space-2: 8px;
  --space-3: 12px;
  --space-4: 16px;
  --space-5: 24px;
  --space-6: 32px;

  /* Chrome geometry */
  --sidenav-w: 208px;
  --toolbar-h: 52px;
  --statusbar-h: 26px;
  --ruler-h: 58px;
  --lane-gutter-w: 190px;

  /* Focus ring — the ONE focus style in the app */
  --focus-ring: 2px solid rgba(230, 0, 18, 0.5);
  --focus-ring-offset: 2px;
  --ring: 0 0 0 3px rgba(230, 0, 18, 0.14);

  /* Object type accents — stable across themes so the legend reads the same */
  --type-activity: #3a76e8;
  --type-milestone: #9333d9;
  --type-release: #2563eb;
  --type-campaign: #0d9488;
  --type-risk: #e0900b;
  --type-issue: #e51b22;
  --type-note: #eab308;
  --type-decision: #6366f1;
  --type-document: #64748b;
  --type-freeze: #0ea5e9;
  --type-outage: #f97316;
  --type-container: #6b7280;

  /* Subsystem accents — rail signalling disciplines */
  --sys-ats: #3a76e8;
  --sys-ixl: #9333d9;
  --sys-scada: #0d9488;
  --sys-comms: #0ea5e9;
  --sys-wayside: #e0900b;
  --sys-vehicle: #e51b22;
  --sys-civil: #78716c;
  --sys-power: #f97316;
}

/* ── 3. THEMES ─────────────────────────────────────────────────────────────
   Every theme must define the same semantic contract. Anything consuming
   colour uses these names only.
   ------------------------------------------------------------------------ */

/* ── DARK (default) — derives from cx-portal's slate sidenav chrome ─────── */
:root,
:root[data-theme='dark'] {
  color-scheme: dark;

  --app-bg: #0b0f1a;
  --canvas-bg: #0d1220;
  --surface: #111827;
  --surface-2: #172033;
  --surface-3: #1f2937;
  --surface-raised: #1c2740;
  --card-bg: #131c2e;
  --chrome-bg: #0e1523;

  --text: #e9edf5;
  --text-main: #f4f6fa;
  --text-muted: #9aa5b8;
  --text-subtle: #6d798e;
  --text-inverse: #0b0f1a;

  --border: rgba(255, 255, 255, 0.08);
  --border-strong: rgba(255, 255, 255, 0.16);
  --line-soft: rgba(255, 255, 255, 0.06);
  --line-strong: rgba(255, 255, 255, 0.2);

  /* Status — the ink is cx-portal's "mid-dot" scale, which is tuned to read
     on dark backgrounds; the -light pair becomes a translucent tint. */
  --good: #16a571;
  --good-light: rgba(22, 165, 113, 0.16);
  --good-border: rgba(22, 165, 113, 0.4);
  --warn: #e0900b;
  --warn-light: rgba(224, 144, 11, 0.16);
  --warn-border: rgba(224, 144, 11, 0.4);
  --bad: #f2555b;
  --bad-light: rgba(229, 27, 34, 0.18);
  --bad-border: rgba(229, 27, 34, 0.45);
  --info: #5b93f5;
  --info-light: rgba(58, 118, 232, 0.18);
  --info-border: rgba(58, 118, 232, 0.42);
  --pending: #a855f7;
  --pending-light: rgba(147, 51, 217, 0.18);
  --pending-border: rgba(147, 51, 217, 0.42);
  --neutral: #94a3b8;
  --neutral-light: rgba(148, 163, 184, 0.14);
  --neutral-border: rgba(148, 163, 184, 0.34);

  --accent-blue: #5b93f5;
  --accent-indigo: #818cf8;
  --accent-amber: #fbbf24;
  --accent-orange: #fb923c;
  --accent-teal: #2dd4bf;
  --accent-lime: #a3e635;
  --accent-slate: #7c93ad;

  /* The PTO calendar's two answers. Leave is one colour wherever it was written
     down — booked, or only on the 4WLA — and a day spent off the project but at
     work is another. Named for what they mean rather than reused from an accent
     at the call site, so a theme can move either without moving the other. */
  --rc-pto: #8b5cf6;
  --rc-offproject: #2dd4bf;

  --shadow-sm: 0 1px 2px rgba(0, 0, 0, 0.4);
  --shadow-md: 0 2px 4px rgba(0, 0, 0, 0.3), 0 8px 20px -8px rgba(0, 0, 0, 0.55);
  --shadow-lg: 0 4px 10px rgba(0, 0, 0, 0.35), 0 32px 64px -24px rgba(0, 0, 0, 0.7);

  --grid-line: rgba(255, 255, 255, 0.045);
  --grid-line-major: rgba(255, 255, 255, 0.1);
  --grid-weekend: rgba(255, 255, 255, 0.03);
  --today-line: #ff2233;
  --selection: rgba(91, 147, 245, 0.9);
  --selection-fill: rgba(91, 147, 245, 0.12);
  --connector: #7d8aa3;
  /* What the selection is waiting on. Deliberately not the selection blue —
     the two have to be told apart at a glance — and not the violation red,
     which means something is wrong rather than something comes first. */
  --upstream: #fbbf24;
  --upstream-glow: rgba(251, 191, 36, 0.45);
  --scroll-track: rgba(255, 255, 255, 0.04);
  --scroll-thumb: rgba(255, 255, 255, 0.16);
}

/* ── LIGHT — cx-portal's production palette, value for value ─────────────── */
:root[data-theme='light'] {
  color-scheme: light;

  --app-bg: #f6f7f9;
  --canvas-bg: #fbfbfc;
  --surface: #ffffff;
  --surface-2: #f9fafb;
  --surface-3: #f3f4f6;
  --surface-raised: #ffffff;
  --card-bg: #ffffff;
  --chrome-bg: #ffffff;

  --text: #1a1a1a;
  --text-main: #131316;
  --text-muted: #6e7179;
  --text-subtle: #697280;
  --text-inverse: #ffffff;

  --border: #ebebeb;
  --border-strong: #d8d8d8;
  --line-soft: #e4e7ec;
  --line-strong: #cfd5df;

  --good: #0d7a4f;
  --good-light: #e8f4ee;
  --good-border: rgba(13, 122, 79, 0.28);
  --warn: #a8550a;
  --warn-light: #fbf0e1;
  --warn-border: rgba(168, 85, 10, 0.3);
  --bad: #c01017;
  --bad-light: #fdeaeb;
  --bad-border: rgba(192, 16, 23, 0.26);
  --info: #1d4eaf;
  --info-light: #e8efff;
  --info-border: rgba(29, 78, 175, 0.26);
  --pending: #6b21a8;
  --pending-light: #f1eaf9;
  --pending-border: rgba(107, 33, 168, 0.26);
  --neutral: #6b7280;
  --neutral-light: #f3f4f6;
  --neutral-border: rgba(107, 114, 128, 0.28);

  --accent-blue: #2563eb;
  --accent-indigo: #6366f1;
  --accent-amber: #f59e0b;
  --accent-orange: #c2410c;
  --accent-teal: #0d9488;
  --accent-lime: #4d7c0f;
  --accent-slate: #475569;

  /* The PTO calendar's two answers. Leave is one colour wherever it was written
     down — booked, or only on the 4WLA — and a day spent off the project but at
     work is another. Named for what they mean rather than reused from an accent
     at the call site, so a theme can move either without moving the other. */
  --rc-pto: #6d28d9;
  --rc-offproject: #0d9488;

  --shadow-sm: 0 1px 2px rgba(15, 17, 21, 0.05), 0 1px 1px rgba(15, 17, 21, 0.03);
  --shadow-md: 0 1px 2px rgba(15, 17, 21, 0.04), 0 6px 16px -8px rgba(15, 17, 21, 0.14);
  --shadow-lg: 0 2px 6px rgba(15, 17, 21, 0.06), 0 28px 56px -20px rgba(15, 17, 21, 0.3);

  --grid-line: rgba(15, 17, 21, 0.05);
  --grid-line-major: rgba(15, 17, 21, 0.12);
  --grid-weekend: rgba(15, 17, 21, 0.035);
  --today-line: #e60012;
  --selection: #2563eb;
  --selection-fill: rgba(37, 99, 235, 0.1);
  --connector: #8b93a3;
  --upstream: #d97706;
  --upstream-glow: rgba(217, 119, 6, 0.38);
  --scroll-track: #f3f4f6;
  --scroll-thumb: #cfd5df;
}

/* ── ENGINEERING — high-contrast instrument panel, mono-forward ──────────── */
:root[data-theme='engineering'] {
  color-scheme: dark;

  --app-bg: #07090d;
  --canvas-bg: #090c12;
  --surface: #0e1219;
  --surface-2: #131922;
  --surface-3: #1a222e;
  --surface-raised: #18202b;
  --card-bg: #10151d;
  --chrome-bg: #0a0e14;

  --text: #d8e2ec;
  --text-main: #eaf2f9;
  --text-muted: #8d9bab;
  --text-subtle: #64717f;
  --text-inverse: #07090d;

  --border: rgba(122, 209, 255, 0.13);
  --border-strong: rgba(122, 209, 255, 0.28);
  --line-soft: rgba(122, 209, 255, 0.08);
  --line-strong: rgba(122, 209, 255, 0.32);

  --good: #22c55e;
  --good-light: rgba(34, 197, 94, 0.15);
  --good-border: rgba(34, 197, 94, 0.42);
  --warn: #fbbf24;
  --warn-light: rgba(251, 191, 36, 0.15);
  --warn-border: rgba(251, 191, 36, 0.42);
  --bad: #ff4d55;
  --bad-light: rgba(255, 77, 85, 0.16);
  --bad-border: rgba(255, 77, 85, 0.45);
  --info: #38bdf8;
  --info-light: rgba(56, 189, 248, 0.15);
  --info-border: rgba(56, 189, 248, 0.42);
  --pending: #c084fc;
  --pending-light: rgba(192, 132, 252, 0.15);
  --pending-border: rgba(192, 132, 252, 0.42);
  --neutral: #94a3b8;
  --neutral-light: rgba(148, 163, 184, 0.13);
  --neutral-border: rgba(148, 163, 184, 0.34);

  --accent-blue: #38bdf8;
  --accent-indigo: #a5b4fc;
  --accent-amber: #fbbf24;
  --accent-orange: #f97316;
  --accent-teal: #2dd4bf;
  --accent-lime: #a3e635;
  --accent-slate: #8296ab;

  /* The PTO calendar's two answers. Leave is one colour wherever it was written
     down — booked, or only on the 4WLA — and a day spent off the project but at
     work is another. Named for what they mean rather than reused from an accent
     at the call site, so a theme can move either without moving the other. */
  --rc-pto: #a78bfa;
  --rc-offproject: #2dd4bf;

  --shadow-sm: 0 1px 2px rgba(0, 0, 0, 0.6);
  --shadow-md: 0 2px 6px rgba(0, 0, 0, 0.5), 0 10px 24px -10px rgba(0, 0, 0, 0.7);
  --shadow-lg: 0 4px 12px rgba(0, 0, 0, 0.55), 0 34px 70px -26px rgba(0, 0, 0, 0.85);

  --grid-line: rgba(122, 209, 255, 0.07);
  --grid-line-major: rgba(122, 209, 255, 0.16);
  --grid-weekend: rgba(122, 209, 255, 0.04);
  --today-line: #ff2233;
  --selection: #38bdf8;
  --selection-fill: rgba(56, 189, 248, 0.14);
  --connector: #6f8ba3;
  --upstream: #fbbf24;
  --upstream-glow: rgba(251, 191, 36, 0.45);
  --scroll-track: rgba(122, 209, 255, 0.05);
  --scroll-thumb: rgba(122, 209, 255, 0.2);

  --f-ui: 'Roboto Mono', ui-monospace, 'SF Mono', Menlo, Consolas, monospace;
}

/* ── BLUEPRINT — drafting-table blue with cyan rules ─────────────────────── */
:root[data-theme='blueprint'] {
  color-scheme: dark;

  --app-bg: #082044;
  --canvas-bg: #0a2751;
  --surface: #0c2d5c;
  --surface-2: #0f3568;
  --surface-3: #144077;
  --surface-raised: #123a6e;
  --card-bg: #0d3164;
  --chrome-bg: #071c3c;

  --text: #dceaff;
  --text-main: #f0f7ff;
  --text-muted: #9dbde6;
  --text-subtle: #6f96c9;
  --text-inverse: #082044;

  --border: rgba(160, 210, 255, 0.2);
  --border-strong: rgba(160, 210, 255, 0.38);
  --line-soft: rgba(160, 210, 255, 0.12);
  --line-strong: rgba(160, 210, 255, 0.45);

  --good: #4ade80;
  --good-light: rgba(74, 222, 128, 0.16);
  --good-border: rgba(74, 222, 128, 0.42);
  --warn: #fcd34d;
  --warn-light: rgba(252, 211, 77, 0.16);
  --warn-border: rgba(252, 211, 77, 0.42);
  --bad: #fb7185;
  --bad-light: rgba(251, 113, 133, 0.18);
  --bad-border: rgba(251, 113, 133, 0.45);
  --info: #7dd3fc;
  --info-light: rgba(125, 211, 252, 0.18);
  --info-border: rgba(125, 211, 252, 0.45);
  --pending: #d8b4fe;
  --pending-light: rgba(216, 180, 254, 0.16);
  --pending-border: rgba(216, 180, 254, 0.42);
  --neutral: #a5c4e8;
  --neutral-light: rgba(165, 196, 232, 0.14);
  --neutral-border: rgba(165, 196, 232, 0.34);

  --accent-blue: #7dd3fc;
  --accent-indigo: #c7d2fe;
  --accent-amber: #fcd34d;
  --accent-orange: #fdba74;
  --accent-teal: #5eead4;
  --accent-lime: #bef264;
  --accent-slate: #94a9c0;

  /* The PTO calendar's two answers. Leave is one colour wherever it was written
     down — booked, or only on the 4WLA — and a day spent off the project but at
     work is another. Named for what they mean rather than reused from an accent
     at the call site, so a theme can move either without moving the other. */
  --rc-pto: #c4b5fd;
  --rc-offproject: #5eead4;

  --shadow-sm: 0 1px 2px rgba(2, 12, 30, 0.5);
  --shadow-md: 0 2px 6px rgba(2, 12, 30, 0.45), 0 10px 24px -10px rgba(2, 12, 30, 0.7);
  --shadow-lg: 0 4px 12px rgba(2, 12, 30, 0.5), 0 34px 70px -26px rgba(2, 12, 30, 0.8);

  --grid-line: rgba(160, 210, 255, 0.13);
  --grid-line-major: rgba(160, 210, 255, 0.26);
  --grid-weekend: rgba(160, 210, 255, 0.07);
  --today-line: #ff5566;
  --selection: #7dd3fc;
  --selection-fill: rgba(125, 211, 252, 0.16);
  --connector: #8fb8e8;
  --upstream: #fcd34d;
  --upstream-glow: rgba(252, 211, 77, 0.5);
  --scroll-track: rgba(160, 210, 255, 0.08);
  --scroll-thumb: rgba(160, 210, 255, 0.28);
}

/* ── PRESENTATION — bright, low-chrome, projector-safe ───────────────────── */
:root[data-theme='presentation'] {
  color-scheme: light;

  --app-bg: #ffffff;
  --canvas-bg: #ffffff;
  --surface: #ffffff;
  --surface-2: #fafbfc;
  --surface-3: #f1f3f6;
  --surface-raised: #ffffff;
  --card-bg: #ffffff;
  --chrome-bg: #ffffff;

  --text: #101318;
  --text-main: #000000;
  --text-muted: #52586a;
  --text-subtle: #737b8c;
  --text-inverse: #ffffff;

  --border: #e2e5ea;
  --border-strong: #c8cdd6;
  --line-soft: #eceef2;
  --line-strong: #b6bcc8;

  --good: #0a7f4f;
  --good-light: #e4f5ec;
  --good-border: rgba(10, 127, 79, 0.32);
  --warn: #b45309;
  --warn-light: #fdf1e2;
  --warn-border: rgba(180, 83, 9, 0.32);
  --bad: #be123c;
  --bad-light: #fdeaef;
  --bad-border: rgba(190, 18, 60, 0.3);
  --info: #1d4ed8;
  --info-light: #e7eeff;
  --info-border: rgba(29, 78, 216, 0.3);
  --pending: #7e22ce;
  --pending-light: #f4eafc;
  --pending-border: rgba(126, 34, 206, 0.3);
  --neutral: #5b6472;
  --neutral-light: #f1f3f6;
  --neutral-border: rgba(91, 100, 114, 0.3);

  --accent-blue: #1d4ed8;
  --accent-indigo: #4f46e5;
  --accent-amber: #d97706;
  --accent-orange: #c2410c;
  --accent-teal: #0f766e;
  --accent-lime: #4d7c0f;
  --accent-slate: #425466;

  /* The PTO calendar's two answers. Leave is one colour wherever it was written
     down — booked, or only on the 4WLA — and a day spent off the project but at
     work is another. Named for what they mean rather than reused from an accent
     at the call site, so a theme can move either without moving the other. */
  --rc-pto: #5b21b6;
  --rc-offproject: #0f766e;

  --shadow-sm: 0 1px 2px rgba(16, 19, 24, 0.06);
  --shadow-md: 0 2px 4px rgba(16, 19, 24, 0.06), 0 8px 18px -10px rgba(16, 19, 24, 0.18);
  --shadow-lg: 0 4px 10px rgba(16, 19, 24, 0.08), 0 30px 60px -22px rgba(16, 19, 24, 0.32);

  --grid-line: rgba(16, 19, 24, 0.07);
  --grid-line-major: rgba(16, 19, 24, 0.16);
  --grid-weekend: rgba(16, 19, 24, 0.04);
  --today-line: #e60012;
  --selection: #1d4ed8;
  --selection-fill: rgba(29, 78, 216, 0.1);
  --connector: #6b7280;
  --upstream: #b45309;
  --upstream-glow: rgba(180, 83, 9, 0.34);
  --scroll-track: #f1f3f6;
  --scroll-thumb: #c8cdd6;

  --fs-base: 14px;
  --fs-body: 15px;
  --fs-small: 13px;
  --fs-tiny: 12px;
}

/* css/base.css */
/* ============================================================================
   CX Timeline — Base layer
   Reset, document typography, scrollbars, focus grammar, shared utilities.
   ========================================================================= */

*,
*::before,
*::after {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  padding: 0;
  height: 100%;
  overflow: hidden;
}

body {
  font-family: var(--f-ui);
  font-size: var(--fs-base);
  line-height: 1.5;
  color: var(--text);
  background: var(--app-bg);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  text-rendering: optimizeLegibility;
  transition: background var(--dur) var(--easing), color var(--dur) var(--easing);
}

h1,
h2,
h3,
h4,
h5,
h6,
p,
figure,
ul,
ol {
  margin: 0;
  padding: 0;
}

ul,
ol {
  list-style: none;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  font-family: inherit;
  font-size: inherit;
  color: inherit;
  cursor: pointer;
  border: none;
  background: none;
  padding: 0;
}

input,
select,
textarea {
  font-family: inherit;
  font-size: inherit;
  color: inherit;
}

svg {
  display: block;
}

/* ── Scrollbars — on-theme everywhere ───────────────────────────────────── */
* {
  scrollbar-width: thin;
  scrollbar-color: var(--scroll-thumb) var(--scroll-track);
}

::-webkit-scrollbar {
  width: 11px;
  height: 11px;
}
::-webkit-scrollbar-track {
  background: var(--scroll-track);
}
::-webkit-scrollbar-thumb {
  background: var(--scroll-thumb);
  border-radius: 6px;
  border: 2px solid transparent;
  background-clip: content-box;
}
::-webkit-scrollbar-thumb:hover {
  background: var(--text-subtle);
  background-clip: content-box;
}
::-webkit-scrollbar-corner {
  background: transparent;
}

/* ── Focus — one visible style, keyboard only ───────────────────────────── */
:focus {
  outline: none;
}
a:focus-visible,
button:focus-visible,
input:focus-visible,
select:focus-visible,
textarea:focus-visible,
[tabindex]:focus-visible {
  outline: var(--focus-ring);
  outline-offset: var(--focus-ring-offset);
  border-radius: var(--radius-xs);
}

/* ── Selection ──────────────────────────────────────────────────────────── */
::selection {
  background: rgba(230, 0, 18, 0.28);
  color: var(--text-main);
}

/* ── Shared type helpers ────────────────────────────────────────────────── */
.eyebrow {
  font-family: var(--f-mono);
  font-size: var(--fs-micro);
  font-weight: 600;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--text-subtle);
}

.mono {
  font-family: var(--f-mono);
  font-variant-numeric: tabular-nums;
}

.num {
  font-variant-numeric: tabular-nums;
  font-feature-settings: 'tnum' 1;
}

.truncate {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.muted {
  color: var(--text-muted);
}
.subtle {
  color: var(--text-subtle);
}

/* ── Accessibility ──────────────────────────────────────────────────────── */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.hidden {
  display: none !important;
}

/* ── Motion preference ──────────────────────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.001ms !important;
  }
}

/* ── Boot splash — shown until the app takes over ───────────────────────── */
#boot {
  position: fixed;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 18px;
  background: var(--app-bg);
  z-index: 9000;
  transition: opacity var(--dur-slow) var(--easing);
}
#boot.done {
  opacity: 0;
  pointer-events: none;
}
.boot-mark {
  display: flex;
  align-items: center;
  gap: 12px;
}
.boot-bar {
  width: 5px;
  height: 34px;
  border-radius: 2px;
  background: var(--hitachi-red);
  animation: bootPulse 1.4s var(--easing) infinite;
}
.boot-name {
  font-family: var(--f-display);
  font-size: var(--fs-xl);
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--text-main);
}
.boot-sub {
  font-family: var(--f-mono);
  font-size: var(--fs-micro);
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--text-subtle);
}
.boot-track {
  width: 190px;
  height: 2px;
  border-radius: 2px;
  background: var(--border);
  overflow: hidden;
}
.boot-fill {
  height: 100%;
  width: 30%;
  background: var(--hitachi-red);
  border-radius: 2px;
  animation: bootSlide 1.15s var(--easing) infinite;
}

@keyframes bootPulse {
  0%,
  100% {
    opacity: 1;
    transform: scaleY(1);
  }
  50% {
    opacity: 0.45;
    transform: scaleY(0.6);
  }
}
@keyframes bootSlide {
  0% {
    transform: translateX(-110%);
  }
  100% {
    transform: translateX(360%);
  }
}

/* css/components.css */
/* ============================================================================
   CX Timeline — Component kit
   ----------------------------------------------------------------------------
   One interaction grammar, shared by every control in the app (the same
   grammar cx-portal settled on): 8px radius, --dur-fast transitions, 1px
   press travel, 0.45 opacity when disabled, and two visual roles —
   solid Hitachi red = primary action, bordered surface = everything else.
   ========================================================================= */

/* ── Buttons ────────────────────────────────────────────────────────────── */
.cx-btn {
  font-family: var(--f-ui);
  font-size: var(--fs-small);
  font-weight: 500;
  color: var(--text-muted);
  background: var(--surface);
  border: 1px solid var(--border-strong);
  padding: 6px 12px;
  border-radius: 8px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  white-space: nowrap;
  cursor: pointer;
  user-select: none;
  transition: background var(--dur-fast) var(--easing),
    border-color var(--dur-fast) var(--easing), color var(--dur-fast) var(--easing),
    box-shadow var(--dur-fast) var(--easing), transform var(--dur-fast) var(--easing);
}
.cx-btn:hover:not(:disabled) {
  color: var(--text);
  border-color: var(--line-strong);
  background: var(--surface-2);
}
.cx-btn:active:not(:disabled) {
  transform: translateY(1px);
}
.cx-btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.cx-btn.primary {
  color: var(--white);
  background: var(--hitachi-red);
  border-color: var(--hitachi-red);
  font-weight: 600;
}
.cx-btn.primary:hover:not(:disabled) {
  background: var(--hitachi-red-hover);
  border-color: var(--hitachi-red-hover);
  color: var(--white);
  box-shadow: 0 2px 6px rgba(230, 0, 18, 0.3), inset 0 1px 0 rgba(255, 255, 255, 0.1);
}

.cx-btn.ghost {
  background: transparent;
  border-color: transparent;
}
.cx-btn.ghost:hover:not(:disabled) {
  background: var(--surface-2);
  border-color: var(--border);
}

.cx-btn.danger {
  color: var(--bad);
  border-color: var(--bad-border);
}
.cx-btn.danger:hover:not(:disabled) {
  background: var(--bad-light);
  border-color: var(--bad);
  color: var(--bad);
}

.cx-btn.mini {
  font-size: var(--fs-tiny);
  padding: 4px 9px;
  border-radius: 6px;
  gap: 4px;
}

.cx-btn.icon {
  padding: 0;
  width: 30px;
  height: 30px;
  flex: 0 0 auto;
}
.cx-btn.icon.mini {
  width: 24px;
  height: 24px;
}

.cx-btn.active,
.cx-btn[aria-pressed='true'] {
  color: var(--text-main);
  background: var(--surface-3);
  border-color: var(--line-strong);
}

.cx-btn .icon-svg {
  flex: 0 0 auto;
}

/* ── Segmented control (scale switcher, alignment, connector style) ─────── */
.cx-seg {
  display: inline-flex;
  align-items: center;
  background: var(--surface-2);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 2px;
  gap: 2px;
}
.cx-seg button {
  font-family: var(--f-mono);
  font-size: var(--fs-micro);
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--text-subtle);
  padding: 4px 9px;
  border-radius: 6px;
  transition: background var(--dur-fast) var(--easing), color var(--dur-fast) var(--easing);
  display: inline-flex;
  align-items: center;
  gap: 4px;
}
.cx-seg button:hover {
  color: var(--text);
  background: var(--surface-3);
}
.cx-seg button.active {
  color: var(--text-main);
  background: var(--surface-raised);
  box-shadow: var(--shadow-sm);
}
.cx-seg.stretch {
  display: flex;
}
.cx-seg.stretch button {
  flex: 1;
  justify-content: center;
}

/* ── Badges & tags ──────────────────────────────────────────────────────── */
.cx-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: var(--fs-tiny);
  font-weight: 600;
  padding: 3px 8px;
  border-radius: 5px;
  white-space: nowrap;
  background: var(--neutral-light);
  color: var(--neutral);
  border: 1px solid transparent;
}
.cx-badge::before {
  content: '';
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: currentColor;
  flex: 0 0 auto;
}
.cx-badge.nodot::before {
  display: none;
}
.cx-badge.good {
  background: var(--good-light);
  color: var(--good);
  border-color: var(--good-border);
}
.cx-badge.warn {
  background: var(--warn-light);
  color: var(--warn);
  border-color: var(--warn-border);
}
.cx-badge.bad {
  background: var(--bad-light);
  color: var(--bad);
  border-color: var(--bad-border);
}
.cx-badge.info {
  background: var(--info-light);
  color: var(--info);
  border-color: var(--info-border);
}
.cx-badge.pending {
  background: var(--pending-light);
  color: var(--pending);
  border-color: var(--pending-border);
}
.cx-badge.neutral {
  background: var(--neutral-light);
  color: var(--neutral);
  border-color: var(--neutral-border);
}

.cx-tag {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-family: var(--f-mono);
  font-size: var(--fs-micro);
  font-weight: 500;
  letter-spacing: 0.04em;
  padding: 2px 6px;
  border-radius: 4px;
  background: var(--surface-3);
  color: var(--text-muted);
  white-space: nowrap;
}

/* ── Chip stat (the shared KPI vocabulary) ──────────────────────────────── */
.cx-chipstat {
  display: inline-flex;
  align-items: baseline;
  gap: 7px;
  padding: 4px 10px;
  border-radius: 7px;
  background: var(--neutral-light);
  border: 1px solid var(--neutral-border);
}
.cx-chipstat .cs-label {
  font-family: var(--f-mono);
  font-size: var(--fs-micro);
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  opacity: 0.85;
}
.cx-chipstat .cs-value {
  font-size: var(--fs-base);
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}
.cx-chipstat.good {
  background: var(--good-light);
  border-color: var(--good-border);
  color: var(--good);
}
.cx-chipstat.warn {
  background: var(--warn-light);
  border-color: var(--warn-border);
  color: var(--warn);
}
.cx-chipstat.bad {
  background: var(--bad-light);
  border-color: var(--bad-border);
  color: var(--bad);
}
.cx-chipstat.info {
  background: var(--info-light);
  border-color: var(--info-border);
  color: var(--info);
}
.cx-chipstat.pending {
  background: var(--pending-light);
  border-color: var(--pending-border);
  color: var(--pending);
}
.cx-chipstat.muted {
  color: var(--text-muted);
}

/* ── Form controls ──────────────────────────────────────────────────────── */
.cx-field {
  display: flex;
  flex-direction: column;
  gap: 5px;
  min-width: 0;
}
.cx-label {
  font-family: var(--f-mono);
  font-size: var(--fs-micro);
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--text-subtle);
}
.cx-hint {
  font-size: var(--fs-tiny);
  color: var(--text-subtle);
  line-height: 1.4;
}

.cx-input,
.cx-select,
.cx-textarea {
  width: 100%;
  font-family: var(--f-ui);
  font-size: var(--fs-small);
  font-weight: 500;
  color: var(--text);
  background: var(--surface-2);
  border: 1px solid var(--border-strong);
  border-radius: 8px;
  padding: 6px 9px;
  transition: border-color var(--dur-fast) var(--easing), box-shadow var(--dur-fast) var(--easing),
    background var(--dur-fast) var(--easing);
}
.cx-textarea {
  resize: vertical;
  min-height: 64px;
  line-height: 1.5;
}
.cx-input:hover,
.cx-select:hover,
.cx-textarea:hover {
  border-color: var(--line-strong);
}
.cx-input:focus,
.cx-select:focus,
.cx-textarea:focus {
  outline: none;
  border-color: rgba(230, 0, 18, 0.55);
  box-shadow: var(--ring);
  background: var(--surface);
}
.cx-input::placeholder,
.cx-textarea::placeholder {
  color: var(--text-subtle);
}
.cx-input[type='date'],
.cx-input[type='number'] {
  font-family: var(--f-mono);
  font-variant-numeric: tabular-nums;
}
.cx-select {
  appearance: none;
  padding-right: 26px;
  background-image: linear-gradient(45deg, transparent 50%, currentColor 50%),
    linear-gradient(135deg, currentColor 50%, transparent 50%);
  background-position: calc(100% - 14px) calc(50% + 1px), calc(100% - 9px) calc(50% + 1px);
  background-size: 5px 5px, 5px 5px;
  background-repeat: no-repeat;
  cursor: pointer;
}
.cx-select option {
  background: var(--surface);
  color: var(--text);
}

.cx-input.mini,
.cx-select.mini {
  padding: 4px 7px;
  font-size: var(--fs-tiny);
  border-radius: 6px;
}
.cx-select.mini {
  padding-right: 22px;
}

/* Colour input — square swatch */
.cx-color {
  width: 34px;
  height: 28px;
  padding: 2px;
  border: 1px solid var(--border-strong);
  border-radius: 7px;
  background: var(--surface-2);
  cursor: pointer;
  flex: 0 0 auto;
}
.cx-color::-webkit-color-swatch-wrapper {
  padding: 0;
}
.cx-color::-webkit-color-swatch {
  border: none;
  border-radius: 5px;
}
.cx-color::-moz-color-swatch {
  border: none;
  border-radius: 5px;
}

/* Range */
.cx-range {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 4px;
  border-radius: 3px;
  background: var(--surface-3);
  outline: none;
  cursor: pointer;
}
.cx-range::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 13px;
  height: 13px;
  border-radius: 50%;
  background: var(--hitachi-red);
  border: 2px solid var(--surface);
  box-shadow: var(--shadow-sm);
  cursor: grab;
}
.cx-range::-moz-range-thumb {
  width: 13px;
  height: 13px;
  border-radius: 50%;
  background: var(--hitachi-red);
  border: 2px solid var(--surface);
  cursor: grab;
}

/* Checkbox / switch */
.cx-check {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  cursor: pointer;
  user-select: none;
  font-size: var(--fs-small);
  color: var(--text-muted);
}
.cx-check input {
  appearance: none;
  width: 15px;
  height: 15px;
  border-radius: 4px;
  border: 1px solid var(--border-strong);
  background: var(--surface-2);
  cursor: pointer;
  position: relative;
  flex: 0 0 auto;
  transition: background var(--dur-fast) var(--easing), border-color var(--dur-fast) var(--easing);
}
.cx-check input:checked {
  background: var(--hitachi-red);
  border-color: var(--hitachi-red);
}
.cx-check input:checked::after {
  content: '';
  position: absolute;
  left: 4.5px;
  top: 1.5px;
  width: 4px;
  height: 8px;
  border: solid var(--white);
  border-width: 0 2px 2px 0;
  transform: rotate(45deg);
}
.cx-check:hover input {
  border-color: var(--line-strong);
}

.cx-switch {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  cursor: pointer;
  user-select: none;
  font-size: var(--fs-small);
  color: var(--text-muted);
}
.cx-switch input {
  appearance: none;
  width: 30px;
  height: 17px;
  border-radius: 9px;
  background: var(--surface-3);
  border: 1px solid var(--border-strong);
  position: relative;
  cursor: pointer;
  flex: 0 0 auto;
  transition: background var(--dur-fast) var(--easing), border-color var(--dur-fast) var(--easing);
}
.cx-switch input::after {
  content: '';
  position: absolute;
  top: 1.5px;
  left: 2px;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: var(--text-subtle);
  transition: transform var(--dur-fast) var(--easing), background var(--dur-fast) var(--easing);
}
.cx-switch input:checked {
  background: var(--hitachi-red);
  border-color: var(--hitachi-red);
}
.cx-switch input:checked::after {
  transform: translateX(12px);
  background: var(--white);
}

/* ── Cards ──────────────────────────────────────────────────────────────── */
.cx-card {
  background: var(--card-bg);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-sm);
  overflow: hidden;
}
.cx-card-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 11px 14px;
  border-bottom: 1px solid var(--border);
}
.cx-card-title {
  font-size: var(--fs-small);
  font-weight: 700;
  letter-spacing: 0.01em;
  color: var(--text-main);
}
.cx-card-body {
  padding: 14px;
}

/* ── Modals ─────────────────────────────────────────────────────────────── */
.cx-modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.6);
  backdrop-filter: blur(3px);
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding: 56px 20px;
  overflow-y: auto;
  z-index: 5000;
  animation: overlayIn var(--dur) var(--easing);
}
@keyframes overlayIn {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}
.cx-modal {
  background: var(--surface);
  border: 1px solid var(--border-strong);
  border-radius: var(--radius-lg);
  width: 100%;
  max-width: 620px;
  max-height: calc(100vh - 112px);
  display: flex;
  flex-direction: column;
  box-shadow: var(--shadow-lg);
  animation: modalIn var(--dur) var(--easing);
}
@keyframes modalIn {
  from {
    opacity: 0;
    transform: translateY(16px) scale(0.99);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
.cx-modal.wide {
  max-width: 880px;
}
.cx-modal.xl {
  max-width: min(1180px, 95vw);
}
.cx-modal-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  padding: 16px 18px 14px;
  border-bottom: 1px solid var(--border);
  flex: 0 0 auto;
}
.cx-modal-title {
  font-family: var(--f-display);
  font-size: var(--fs-lg);
  font-weight: 700;
  color: var(--text-main);
  line-height: 1.25;
}
.cx-modal-sub {
  font-size: var(--fs-tiny);
  color: var(--text-subtle);
  margin-top: 3px;
}
.cx-modal-body {
  padding: 18px;
  overflow-y: auto;
  flex: 1 1 auto;
}
.cx-modal-foot {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
  padding: 13px 18px;
  border-top: 1px solid var(--border);
  background: var(--surface-2);
  flex: 0 0 auto;
}
.cx-modal-foot .spacer {
  flex: 1;
}

/* ── Context menu ───────────────────────────────────────────────────────── */
.cx-menu {
  position: fixed;
  min-width: 208px;
  max-height: 78vh;
  overflow-y: auto;
  background: var(--surface-raised);
  border: 1px solid var(--border-strong);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-lg);
  padding: 5px;
  z-index: 6000;
  animation: menuIn var(--dur-fast) var(--easing);
}
@keyframes menuIn {
  from {
    opacity: 0;
    transform: translateY(-4px) scale(0.98);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
.cx-menu-item {
  display: flex;
  align-items: center;
  gap: 9px;
  width: 100%;
  padding: 6px 9px;
  border-radius: 7px;
  font-size: var(--fs-small);
  color: var(--text-muted);
  text-align: left;
  transition: background var(--dur-fast) var(--easing), color var(--dur-fast) var(--easing);
}
.cx-menu-item:hover:not(:disabled) {
  background: var(--surface-3);
  color: var(--text-main);
}
.cx-menu-item:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}
.cx-menu-item .mi-label {
  flex: 1;
  white-space: nowrap;
}
.cx-menu-item .mi-key {
  font-family: var(--f-mono);
  font-size: var(--fs-micro);
  color: var(--text-subtle);
  letter-spacing: 0.04em;
}
.cx-menu-item.danger {
  color: var(--bad);
}
.cx-menu-item.danger:hover:not(:disabled) {
  background: var(--bad-light);
  color: var(--bad);
}
.cx-menu-sep {
  height: 1px;
  background: var(--border);
  margin: 4px 6px;
}
.cx-menu-head {
  font-family: var(--f-mono);
  font-size: var(--fs-micro);
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--text-subtle);
  padding: 7px 9px 4px;
}

/* ── Toasts ─────────────────────────────────────────────────────────────── */
#cx-toasts {
  position: fixed;
  bottom: calc(var(--statusbar-h) + 14px);
  right: 16px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  z-index: 7000;
  pointer-events: none;
}
.cx-toast {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 236px;
  max-width: 380px;
  padding: 10px 13px;
  border-radius: var(--radius-md);
  background: var(--surface-raised);
  border: 1px solid var(--border-strong);
  border-left: 3px solid var(--neutral);
  box-shadow: var(--shadow-lg);
  font-size: var(--fs-small);
  color: var(--text);
  pointer-events: auto;
  animation: toastIn var(--dur) var(--easing);
}
.cx-toast.out {
  animation: toastOut var(--dur) var(--easing) forwards;
}
@keyframes toastIn {
  from {
    opacity: 0;
    transform: translateX(24px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
@keyframes toastOut {
  to {
    opacity: 0;
    transform: translateX(24px);
  }
}
.cx-toast.good {
  border-left-color: var(--good);
}
.cx-toast.good .t-icon {
  color: var(--good);
}
.cx-toast.warn {
  border-left-color: var(--warn);
}
.cx-toast.warn .t-icon {
  color: var(--warn);
}
.cx-toast.bad {
  border-left-color: var(--bad);
}
.cx-toast.bad .t-icon {
  color: var(--bad);
}
.cx-toast.info {
  border-left-color: var(--info);
}
.cx-toast.info .t-icon {
  color: var(--info);
}
.cx-toast .t-body {
  flex: 1;
  min-width: 0;
}
.cx-toast .t-title {
  font-weight: 600;
  color: var(--text-main);
}
.cx-toast .t-msg {
  font-size: var(--fs-tiny);
  color: var(--text-muted);
  margin-top: 1px;
}

/* ── Tooltip ────────────────────────────────────────────────────────────── */
.cx-tooltip {
  position: fixed;
  z-index: 8000;
  max-width: 320px;
  padding: 7px 10px;
  border-radius: 8px;
  background: var(--surface-raised);
  border: 1px solid var(--border-strong);
  box-shadow: var(--shadow-lg);
  font-size: var(--fs-tiny);
  line-height: 1.45;
  color: var(--text);
  pointer-events: none;
  animation: tipIn var(--dur-fast) var(--easing);
}
@keyframes tipIn {
  from {
    opacity: 0;
    transform: translateY(3px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
.cx-tooltip .tip-title {
  font-weight: 700;
  color: var(--text-main);
  margin-bottom: 2px;
}
.cx-tooltip .tip-meta {
  font-family: var(--f-mono);
  font-size: var(--fs-micro);
  color: var(--text-subtle);
  letter-spacing: 0.04em;
}
.cx-tooltip .tip-notes {
  margin-top: 6px;
  padding-top: 6px;
  border-top: 1px solid var(--border);
  color: var(--text-muted);
  max-height: 180px;
  overflow: hidden;
}
.cx-tooltip .tip-notes * {
  max-width: 100%;
}

/* ── Empty / loading states ─────────────────────────────────────────────── */
.cx-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 9px;
  padding: 30px 18px;
  text-align: center;
  color: var(--text-subtle);
}
.cx-empty .ce-icon {
  color: var(--text-subtle);
  opacity: 0.5;
}
.cx-empty .ce-title {
  font-size: var(--fs-small);
  font-weight: 600;
  color: var(--text-muted);
}
.cx-empty .ce-msg {
  font-size: var(--fs-tiny);
  max-width: 260px;
  line-height: 1.5;
}

.cx-skel {
  height: 11px;
  border-radius: 5px;
  background: linear-gradient(90deg, var(--surface-2) 25%, var(--surface-3) 50%, var(--surface-2) 75%);
  background-size: 200% 100%;
  animation: skel 1.3s linear infinite;
}
@keyframes skel {
  to {
    background-position: -200% 0;
  }
}

/* ── Progress bar ───────────────────────────────────────────────────────── */
.cx-progress {
  height: 5px;
  border-radius: 3px;
  background: var(--surface-3);
  overflow: hidden;
}
.cx-progress > span {
  display: block;
  height: 100%;
  border-radius: 3px;
  background: var(--good);
  transition: width var(--dur) var(--easing);
}

/* ── Section / accordion within panels ──────────────────────────────────── */
.cx-section {
  border-bottom: 1px solid var(--border);
}
.cx-section-head {
  display: flex;
  align-items: center;
  gap: 7px;
  width: 100%;
  padding: 9px 12px;
  font-family: var(--f-mono);
  font-size: var(--fs-micro);
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--text-subtle);
  transition: color var(--dur-fast) var(--easing), background var(--dur-fast) var(--easing);
}
.cx-section-head:hover {
  color: var(--text-muted);
  background: var(--surface-2);
}
.cx-section-head .sec-caret {
  transition: transform var(--dur-fast) var(--easing);
}
.cx-section.collapsed .sec-caret {
  transform: rotate(-90deg);
}
.cx-section-head .sec-title {
  flex: 1;
  text-align: left;
}
.cx-section-body {
  padding: 4px 12px 14px;
  display: flex;
  flex-direction: column;
  gap: 11px;
}
.cx-section.collapsed .cx-section-body {
  display: none;
}

/* ── Grid helper for inspector rows ─────────────────────────────────────── */
.cx-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 9px;
}
.cx-row.three {
  grid-template-columns: 1fr 1fr 1fr;
}
.cx-inline {
  display: flex;
  align-items: center;
  gap: 8px;
}
.cx-inline.wrap {
  flex-wrap: wrap;
}

/* ── Swatch grid (colour presets) ───────────────────────────────────────── */
.cx-swatches {
  display: grid;
  grid-template-columns: repeat(10, 1fr);
  gap: 4px;
}
.cx-swatch {
  aspect-ratio: 1;
  border-radius: 5px;
  border: 1px solid var(--border-strong);
  cursor: pointer;
  transition: transform var(--dur-fast) var(--easing), box-shadow var(--dur-fast) var(--easing);
}
.cx-swatch:hover {
  transform: scale(1.14);
  box-shadow: var(--shadow-md);
  z-index: 1;
}
.cx-swatch.active {
  outline: 2px solid var(--hitachi-red);
  outline-offset: 1px;
}

/* ── Icon picker ────────────────────────────────────────────────────────── */
.cx-iconpick {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(34px, 1fr));
  gap: 4px;
  max-height: 220px;
  overflow-y: auto;
  padding: 2px;
}
.cx-iconpick button {
  aspect-ratio: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 7px;
  border: 1px solid transparent;
  color: var(--text-muted);
  transition: all var(--dur-fast) var(--easing);
}
.cx-iconpick button:hover {
  background: var(--surface-3);
  color: var(--text-main);
  border-color: var(--border-strong);
}
.cx-iconpick button.active {
  background: var(--info-light);
  color: var(--info);
  border-color: var(--info-border);
}

/* ── List rows (lanes, search results, history) ─────────────────────────── */
.cx-list {
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.cx-listrow {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 8px;
  border-radius: 8px;
  border: 1px solid transparent;
  font-size: var(--fs-small);
  color: var(--text-muted);
  cursor: pointer;
  transition: background var(--dur-fast) var(--easing), border-color var(--dur-fast) var(--easing),
    color var(--dur-fast) var(--easing);
}
.cx-listrow:hover {
  background: var(--surface-2);
  border-color: var(--border);
  color: var(--text);
}
.cx-listrow.active {
  background: var(--surface-3);
  border-color: var(--border-strong);
  color: var(--text-main);
}
.cx-listrow .lr-main {
  flex: 1;
  min-width: 0;
}
.cx-listrow .lr-title {
  font-weight: 500;
  color: var(--text);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.cx-listrow .lr-meta {
  font-family: var(--f-mono);
  font-size: var(--fs-micro);
  color: var(--text-subtle);
  letter-spacing: 0.04em;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.cx-listrow .lr-actions {
  display: flex;
  gap: 2px;
  opacity: 0;
  transition: opacity var(--dur-fast) var(--easing);
}
.cx-listrow:hover .lr-actions,
.cx-listrow.active .lr-actions {
  opacity: 1;
}

/* ── Editable list options (Dropdown Lists pane + Manage lists dialog) ──── */
/* The dock is ~250px wide, so a one-line row would squeeze the name field to
   nothing. A two-row grid keeps it usable there and in the wide dialog. */
.list-opt {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  grid-template-areas:
    "swatch name    actions"
    "foot   foot    foot";
  align-items: center;
  gap: 7px 8px;
  padding: 9px 9px 8px;
  border-radius: 8px;
  border: 1px solid var(--border);
  background: var(--surface-2);
  transition: border-color var(--dur-fast) var(--easing);
}
.list-opt:hover {
  border-color: var(--border-strong);
}
.list-opt .lo-swatch {
  grid-area: swatch;
}
.list-opt .lo-name {
  grid-area: name;
  min-width: 0;
}
.list-opt .lo-actions {
  grid-area: actions;
  display: flex;
  gap: 2px;
}
.list-opt .lo-foot {
  grid-area: foot;
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}
.list-opt .lo-meta {
  flex: 1;
  min-width: 0;
  font-family: var(--f-mono);
  font-size: var(--fs-micro);
  color: var(--text-subtle);
  letter-spacing: 0.04em;
  /* ids can be long (a font stack is one) — wrap rather than hide them */
  overflow-wrap: anywhere;
}
.list-opt .lo-tone {
  flex: 0 0 auto;
}

/* ── Dot / swatch marker used in lists and the legend ───────────────────── */
.cx-dot {
  width: 9px;
  height: 9px;
  border-radius: 3px;
  flex: 0 0 auto;
}
.cx-dot.round {
  border-radius: 50%;
}

/* ── Inline alert (broken dependency, and anything else needing a decision) ─ */
.insp-alert {
  margin: 11px 12px 0;
  padding: 9px 11px;
  border: 1px solid var(--bad-border);
  border-left: 3px solid var(--bad);
  border-radius: var(--radius-md);
  background: var(--bad-light);
  color: var(--bad);
  font-size: var(--fs-small);
}

/* A list row whose subject needs attention. */
.cx-listrow.danger {
  border-color: var(--bad-border);
  background: var(--bad-light);
}
.cx-listrow.danger:hover {
  border-color: var(--bad);
}
.cx-listrow.danger .lr-title {
  color: var(--bad);
  font-weight: 600;
}

/* ── Chip-stat rows ────────────────────────────────────────────────────── */

.cx-chipstats {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

/* ── Progress from the calendar ─────────────────────────────────────────── */

.la-progress-head {
  display: flex;
  justify-content: flex-end;
  margin-bottom: 8px;
}
.la-progress-wait {
  margin-top: 3px;
  font-size: var(--fs-tiny);
  color: var(--text-muted);
}
.la-progress-toggle {
  margin-top: 6px;
}
.la-progress-acts {
  display: grid;
  gap: 4px;
  margin: 6px 0 0;
  padding: 6px 8px;
  list-style: none;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--surface-2);
}
.la-progress-acts[hidden] {
  display: none;
}
.la-progress-act {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto auto;
  gap: 10px;
  align-items: center;
  font-size: var(--fs-tiny);
}
.la-progress-act-title {
  color: var(--text);
  overflow-wrap: anywhere;
}
.la-progress-act-facts {
  font-family: var(--f-mono);
  color: var(--text-subtle);
}
@media (max-width: 560px) {
  .la-progress-act {
    grid-template-columns: minmax(0, 1fr) auto;
  }
  .la-progress-act-facts {
    grid-column: 1 / -1;
    grid-row: 2;
  }
}

/* ── P6 register ───────────────────────────────────────────────────────── */

.p6-stamps {
  display: flex;
  gap: 8px;
}
.p6-stamp {
  flex: 1;
  min-width: 0;
  padding: 6px 8px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--surface-2);
}
.p6-stamp-label {
  display: block;
  font-family: var(--f-mono);
  font-size: var(--fs-micro);
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--text-subtle);
}
.p6-stamp-value {
  display: block;
  overflow: hidden;
  font-size: var(--fs-tiny);
  color: var(--text);
  text-overflow: ellipsis;
  white-space: nowrap;
}
.p6-stamp-value.none {
  color: var(--text-subtle);
  font-style: italic;
}

/* A placed activity is the common case; the marker carries it, so the row
   itself stays quiet rather than shouting in green. */
.cx-listrow.p6-row.active {
  background: transparent;
  border-color: var(--border);
}
.cx-listrow.p6-row.active:hover {
  background: var(--surface-2);
  border-color: var(--border-strong);
}
.cx-listrow.p6-row .cx-badge {
  flex: 0 0 auto;
}

/* The activity ID on a linked object, in the inspector. */
.p6-link {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 7px 9px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--surface-2);
}
.p6-link .p6-id {
  font-family: var(--f-mono);
  font-size: var(--fs-tiny);
  font-weight: 700;
  letter-spacing: 0.04em;
  color: var(--text-main);
}
.p6-link .p6-dates {
  flex: 1;
  min-width: 0;
  font-family: var(--f-mono);
  font-size: var(--fs-micro);
  color: var(--text-muted);
}

/* A P6 row carries a name, an id, dates and up to four badges. In a 250px
   dock that cannot be one line — the name loses every time. Two rows, with
   the badges wrapping under the meta. */
.p6-row {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  grid-template-areas:
    'mark name  acts'
    '.    meta  meta'
    '.    badge badge';
  align-items: center;
  gap: 4px 8px;
  padding: 8px 9px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--surface-2);
  cursor: pointer;
  transition: border-color var(--dur-fast) var(--easing), background var(--dur-fast) var(--easing);
}
.p6-row:hover {
  border-color: var(--border-strong);
  background: var(--surface-3);
}
.p6-row.placed {
  border-left: 2px solid var(--good);
}
.p6-row .p6-mark {
  grid-area: mark;
  width: 8px;
  height: 8px;
  border-radius: 2px;
}
.p6-row .p6-name {
  grid-area: name;
  overflow: hidden;
  font-size: var(--fs-small);
  font-weight: 500;
  color: var(--text);
  text-overflow: ellipsis;
  white-space: nowrap;
}
.p6-row .p6-acts {
  grid-area: acts;
  display: flex;
  gap: 2px;
}
.p6-row .p6-meta {
  grid-area: meta;
  font-family: var(--f-mono);
  font-size: var(--fs-micro);
  color: var(--text-subtle);
  letter-spacing: 0.03em;
  overflow-wrap: anywhere;
}
.p6-row .p6-badges {
  grid-area: badge;
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
}
.p6-row .p6-badges:empty {
  display: none;
}

/* ── Searchable picker ─────────────────────────────────────────────────── */

/* A select stops being usable around fifty options; the P6 register has
   fifteen hundred. Type to narrow, arrow keys to move, Enter to take. */
.cx-picker-list {
  max-height: 46vh;
  margin-top: 10px;
  overflow-y: auto;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--surface-2);
}
.cx-picker-item {
  padding: 7px 10px;
  border-bottom: 1px solid var(--border);
  cursor: pointer;
}
.cx-picker-item:last-child {
  border-bottom: 0;
}
.cx-picker-item:hover {
  background: var(--surface-3);
}
.cx-picker-item.on {
  background: color-mix(in srgb, var(--accent) 16%, transparent);
  box-shadow: inset 2px 0 0 var(--accent);
}
.cx-picker-item .pi-label {
  font-size: var(--fs-small);
  color: var(--text);
}
.cx-picker-item .pi-meta {
  margin-top: 1px;
  font-family: var(--f-mono);
  font-size: var(--fs-micro);
  color: var(--text-subtle);
  letter-spacing: 0.03em;
}

.p6-row[draggable='true'] {
  cursor: grab;
}
.p6-row.dragging {
  opacity: 0.5;
  border-color: var(--accent);
}

/* ── Linked P6 activities, in the inspector ────────────────────────────── */

.p6-links {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.p6-chip {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  grid-template-areas:
    'id    close'
    'name  close'
    'dates close';
  align-items: center;
  gap: 1px 6px;
  padding: 6px 7px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--surface-2);
}
.p6-chip.unknown {
  border-color: var(--bad);
}
.p6-chip .p6-id {
  grid-area: id;
  font-family: var(--f-mono);
  font-size: var(--fs-micro);
  font-weight: 700;
  letter-spacing: 0.05em;
  color: var(--text-main);
}
.p6-chip .p6-chip-name {
  grid-area: name;
  overflow: hidden;
  font-size: var(--fs-tiny);
  color: var(--text);
  text-overflow: ellipsis;
  white-space: nowrap;
}
.p6-chip .p6-dates {
  grid-area: dates;
  font-family: var(--f-mono);
  font-size: var(--fs-micro);
  color: var(--text-subtle);
}
.p6-chip .cx-btn {
  grid-area: close;
}

/* css/layout.css */
/* ============================================================================
   CX Timeline — Application shell
   Sidenav · toolbar · dock panels · canvas frame · inspector · status bar
   ========================================================================= */

#app {
  display: grid;
  grid-template-columns: var(--sidenav-w) 1fr;
  grid-template-rows: 1fr var(--statusbar-h);
  grid-template-areas:
    'nav main'
    'nav status';
  height: 100vh;
  width: 100vw;
  overflow: hidden;
}

/* ── Side navigation ────────────────────────────────────────────────────── */
#sidenav {
  grid-area: nav;
  background: var(--chrome-bg);
  border-right: 1px solid var(--border);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  z-index: 200;
  transition: width var(--dur) var(--easing);
}

.sidenav-brand {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 17px 15px 15px;
  border-bottom: 1px solid var(--border);
  flex: 0 0 auto;
}
.brand-mark {
  width: 5px;
  height: 30px;
  border-radius: 2px;
  background: var(--hitachi-red);
  flex: 0 0 auto;
}
.sidenav-brand-text {
  display: flex;
  flex-direction: column;
  line-height: 1.25;
  min-width: 0;
}
.sidenav-brand-name {
  font-family: var(--f-display);
  font-size: var(--fs-tiny);
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--text-main);
}
.sidenav-brand-sub {
  font-family: var(--f-mono);
  font-size: 9px;
  font-weight: 500;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--text-subtle);
  margin-top: 2px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.sidenav-links {
  flex: 1;
  padding: 8px 8px 12px;
  display: flex;
  flex-direction: column;
  gap: 1px;
  overflow-y: auto;
  overflow-x: hidden;
}

.sidenav-group {
  display: flex;
  flex-direction: column;
  gap: 1px;
}
/* The heading is a button: it folds its section away. */
.sidenav-section-label {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  background: none;
  border: 0;
  cursor: pointer;
  text-align: left;
  font-family: var(--f-mono);
  font-size: var(--fs-micro);
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--text-subtle);
  opacity: 0.75;
  padding: 14px 14px 4px;
  border-radius: 6px;
  transition: opacity var(--dur-fast) var(--easing), color var(--dur-fast) var(--easing);
}
.sidenav-section-label:hover,
.sidenav-section-label:focus-visible {
  opacity: 1;
  color: var(--text-muted);
}
.sidenav-group:first-child .sidenav-section-label {
  padding-top: 6px;
}
.sidenav-fold {
  display: inline-flex;
  opacity: 0;
  transition: transform var(--dur-fast) var(--easing), opacity var(--dur-fast) var(--easing);
}
.sidenav-section-label:hover .sidenav-fold,
.sidenav-section-label:focus-visible .sidenav-fold,
.sidenav-group.folded .sidenav-fold {
  opacity: 1;
}
.sidenav-group.folded .sidenav-fold {
  transform: rotate(-90deg);
}
/* Folded, but never hiding where you are: the open pane stays in view. */
.sidenav-group.folded .nav-link:not(.active) {
  display: none;
}

/* The command menu's entry point, above the list of places. */
.sidenav-command {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 8px 10px 0;
  padding: 7px 10px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--surface-2);
  color: var(--text-subtle);
  font: inherit;
  font-size: var(--fs-tiny);
  cursor: pointer;
  text-align: left;
  transition: color var(--dur-fast) var(--easing), border-color var(--dur-fast) var(--easing);
}
.sidenav-command:hover,
.sidenav-command:focus-visible {
  color: var(--text-main);
  border-color: var(--border-strong);
}
.sidenav-command .nav-label { flex: 1; }
.sidenav-command kbd {
  font-family: var(--f-mono);
  font-size: var(--fs-micro);
  color: var(--text-subtle);
  border: 1px solid var(--border);
  border-radius: 4px;
  padding: 0 5px;
}

.nav-link {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: var(--fs-base);
  font-weight: 500;
  color: var(--text-muted);
  padding: 8px 11px;
  border-radius: 8px;
  border-left: 3px solid transparent;
  white-space: nowrap;
  letter-spacing: 0.01em;
  transition: color var(--dur-fast) var(--easing), background var(--dur-fast) var(--easing),
    border-color var(--dur-fast) var(--easing);
  position: relative;
}
.nav-link:hover {
  color: var(--text-main);
  background: var(--surface-2);
}
.nav-link.active {
  color: var(--text-main);
  background: var(--surface-3);
  border-left-color: var(--hitachi-red);
}
.nav-link .nav-icon {
  width: 16px;
  height: 16px;
  flex: 0 0 auto;
  opacity: 0.7;
  transition: opacity var(--dur-fast) var(--easing);
}
.nav-link:hover .nav-icon,
.nav-link.active .nav-icon {
  opacity: 1;
}
.nav-link .nav-label {
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
}
.nav-link .nav-count {
  font-family: var(--f-mono);
  font-size: var(--fs-micro);
  font-variant-numeric: tabular-nums;
  color: var(--text-subtle);
  background: var(--surface-3);
  padding: 1px 5px;
  border-radius: 4px;
}

.sidenav-footer {
  padding: 9px 9px 12px;
  border-top: 1px solid var(--border);
  flex: 0 0 auto;
  display: flex;
  flex-direction: column;
  gap: 7px;
}
.sidenav-project-tag {
  font-family: var(--f-mono);
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--text-subtle);
  padding: 0 5px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* ── Main region ────────────────────────────────────────────────────────── */
#main {
  grid-area: main;
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
  background: var(--app-bg);
}

/* ── Toolbar ────────────────────────────────────────────────────────────── */
#toolbar {
  height: var(--toolbar-h);
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 0 12px;
  background: var(--chrome-bg);
  border-bottom: 1px solid var(--border);
  overflow-x: auto;
  overflow-y: hidden;
  scrollbar-width: none;
}
#toolbar::-webkit-scrollbar {
  display: none;
}
.tb-group {
  display: flex;
  align-items: center;
  gap: 5px;
  flex: 0 0 auto;
}
.tb-sep {
  width: 1px;
  height: 22px;
  background: var(--border);
  flex: 0 0 auto;
  margin: 0 2px;
}
.tb-spacer {
  flex: 1 1 auto;
  min-width: 8px;
}
.tb-title {
  display: flex;
  flex-direction: column;
  line-height: 1.2;
  min-width: 0;
  max-width: 260px;
  cursor: pointer;
  padding: 3px 7px;
  border-radius: 7px;
  border: 1px solid transparent;
  transition: background var(--dur-fast) var(--easing), border-color var(--dur-fast) var(--easing);
}
.tb-title:hover {
  background: var(--surface-2);
  border-color: var(--border);
}
.tb-title .tt-name {
  font-family: var(--f-display);
  font-size: var(--fs-body);
  font-weight: 700;
  color: var(--text-main);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.tb-title .tt-meta {
  font-family: var(--f-mono);
  font-size: 9px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--text-subtle);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* ── Workspace: dock · canvas · inspector ───────────────────────────────── */
#workspace {
  flex: 1 1 auto;
  display: flex;
  min-height: 0;
  min-width: 0;
  position: relative;
}

/* Left dock panel */
#dock {
  width: 260px;
  flex: 0 0 auto;
  display: flex;
  flex-direction: column;
  background: var(--surface);
  border-right: 1px solid var(--border);
  min-height: 0;
  position: relative;
}
#dock.collapsed {
  display: none;
}
.dock-tabs {
  display: flex;
  align-items: center;
  gap: 1px;
  padding: 6px 6px 0;
  border-bottom: 1px solid var(--border);
  flex: 0 0 auto;
  overflow-x: auto;
  scrollbar-width: none;
}
.dock-tabs::-webkit-scrollbar {
  display: none;
}
.dock-tab {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 6px 9px;
  border-radius: 7px 7px 0 0;
  font-family: var(--f-mono);
  font-size: var(--fs-micro);
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--text-subtle);
  border-bottom: 2px solid transparent;
  margin-bottom: -1px;
  white-space: nowrap;
  transition: color var(--dur-fast) var(--easing), border-color var(--dur-fast) var(--easing),
    background var(--dur-fast) var(--easing);
}
.dock-tab:hover {
  color: var(--text-muted);
  background: var(--surface-2);
}
.dock-tab.active {
  color: var(--text-main);
  border-bottom-color: var(--hitachi-red);
}
.dock-body {
  flex: 1 1 auto;
  overflow-y: auto;
  overflow-x: hidden;
  min-height: 0;
}
.dock-pane {
  display: none;
  flex-direction: column;
  height: 100%;
}
.dock-pane.active {
  display: flex;
}

/* Resizer handles */
.resizer {
  position: absolute;
  top: 0;
  bottom: 0;
  width: 5px;
  cursor: col-resize;
  z-index: 60;
  background: transparent;
  transition: background var(--dur-fast) var(--easing);
}
.resizer:hover,
.resizer.dragging {
  background: var(--hitachi-red);
  opacity: 0.55;
}
.resizer.right {
  right: -3px;
}
.resizer.left {
  left: -3px;
}

/* Canvas frame */
#canvas-frame {
  flex: 1 1 auto;
  position: relative;
  min-width: 0;
  min-height: 0;
  background: var(--canvas-bg);
  overflow: hidden;
}

/* Right inspector — floating, dockable */
#inspector {
  width: 306px;
  flex: 0 0 auto;
  display: flex;
  flex-direction: column;
  background: var(--surface);
  border-left: 1px solid var(--border);
  min-height: 0;
  position: relative;
}
#inspector.collapsed {
  display: none;
}
#inspector.floating {
  position: absolute;
  top: 14px;
  right: 14px;
  bottom: 14px;
  height: auto;
  border: 1px solid var(--border-strong);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-lg);
  z-index: 300;
  overflow: hidden;
}
.insp-head {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 12px;
  border-bottom: 1px solid var(--border);
  flex: 0 0 auto;
  cursor: default;
}
.insp-head .ih-title {
  flex: 1;
  min-width: 0;
}
.insp-head .ih-kind {
  font-family: var(--f-mono);
  font-size: var(--fs-micro);
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--text-subtle);
}
.insp-head .ih-name {
  font-size: var(--fs-small);
  font-weight: 700;
  color: var(--text-main);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.insp-body {
  flex: 1 1 auto;
  overflow-y: auto;
  overflow-x: hidden;
  min-height: 0;
}

/* Panel header used inside dock panes */
.pane-head {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 9px 11px;
  border-bottom: 1px solid var(--border);
  flex: 0 0 auto;
}
.pane-head .ph-title {
  flex: 1;
  font-family: var(--f-mono);
  font-size: var(--fs-micro);
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--text-subtle);
}
.pane-scroll {
  flex: 1 1 auto;
  overflow-y: auto;
  overflow-x: hidden;
  padding: 8px;
  min-height: 0;
}
.pane-foot {
  padding: 8px;
  border-top: 1px solid var(--border);
  flex: 0 0 auto;
  display: flex;
  gap: 6px;
}

/* ── Status bar ─────────────────────────────────────────────────────────── */
#statusbar {
  grid-area: status;
  height: var(--statusbar-h);
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 0 12px;
  background: var(--chrome-bg);
  border-top: 1px solid var(--border);
  font-family: var(--f-mono);
  font-size: var(--fs-micro);
  letter-spacing: 0.06em;
  color: var(--text-subtle);
  overflow: hidden;
  white-space: nowrap;
}
.sb-item {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  flex: 0 0 auto;
}
.sb-item.clickable {
  cursor: pointer;
  padding: 2px 5px;
  border-radius: 5px;
  transition: background var(--dur-fast) var(--easing), color var(--dur-fast) var(--easing);
}
.sb-item.clickable:hover {
  background: var(--surface-2);
  color: var(--text-muted);
}
.sb-spacer {
  flex: 1 1 auto;
}
/* The desktop app's page zoom: − 100% +, the browser's Ctrl + / Ctrl − made
   visible, since the window has no browser chrome to show it. */
.sb-page-zoom { gap: 0; border: 1px solid var(--border); border-radius: 5px; overflow: hidden; }
.sb-page-zoom button {
  font: inherit;
  color: inherit;
  background: transparent;
  border: 0;
  padding: 1px 7px;
  cursor: pointer;
  transition: background var(--dur-fast) var(--easing);
}
.sb-page-zoom button:hover { background: var(--surface-2); }
.sb-page-zoom .sb-zoom-reset { min-width: 44px; font-family: var(--f-mono); border-left: 1px solid var(--border); border-right: 1px solid var(--border); }
.sb-item.sb-warn {
  color: var(--bad);
  font-weight: 700;
}
.sb-item.sb-warn:hover {
  background: var(--bad-light);
  color: var(--bad);
}
/* A colleague's version is waiting in the folder. Not an error — nothing is
   wrong and nothing is lost — so it reads as something to attend to rather
   than something that has gone wrong. */
.sb-item.behind {
  color: var(--warn);
  font-weight: 700;
}
.sb-item.behind:hover {
  background: var(--warn-light);
  color: var(--warn);
}
.sb-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--good);
  flex: 0 0 auto;
}
.sb-dot.saving {
  background: var(--warn);
  animation: sbPulse 0.9s ease-in-out infinite;
}
.sb-dot.error {
  background: var(--bad);
}
/* Held rather than failed: a colleague has the pen, so there is nothing wrong
   and nothing to fix — but nothing was saved either, and the dot must not be
   the same colour as one that was. */
.sb-dot.held {
  background: var(--warn);
}
@keyframes sbPulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.3;
  }
}

/* ── Presentation mode — strip the chrome ───────────────────────────────── */
body.presenting #sidenav,
body.presenting #dock,
body.presenting #inspector,
body.presenting #statusbar {
  display: none !important;
}
body.presenting #toolbar {
  height: 40px;
  opacity: 0.14;
  transition: opacity var(--dur) var(--easing);
}
body.presenting #toolbar:hover {
  opacity: 1;
}
body.presenting #app {
  grid-template-columns: 1fr;
  grid-template-rows: 1fr;
  grid-template-areas: 'main';
}

/* ── Responsive: narrow windows collapse the dock ───────────────────────── */
@media (max-width: 1180px) {
  #inspector:not(.floating) {
    width: 268px;
  }
  #dock {
    width: 226px;
  }
}
@media (max-width: 900px) {
  #app {
    grid-template-columns: 56px 1fr;
  }
  #sidenav .nav-label,
  #sidenav .sidenav-brand-text,
  #sidenav .sidenav-section-label,
  #sidenav .sidenav-project-tag,
  #sidenav .nav-count {
    display: none;
  }
  .nav-link {
    justify-content: center;
    padding: 9px 0;
  }
  .sidenav-brand {
    justify-content: center;
    padding: 15px 0;
  }
  /* The headings that unfold a section are gone at this width, so nothing
     may stay folded behind them. */
  .sidenav-group.folded .nav-link:not(.active) {
    display: flex;
  }
  .sidenav-command {
    justify-content: center;
    margin: 8px 6px 0;
    padding: 7px 0;
  }
  .sidenav-command .nav-label,
  .sidenav-command kbd {
    display: none;
  }
}

/* ══════════════════════════════════════════════════════════════════════════
   Account, access and sharing (hosted deployments)

   None of this renders when config.js is blank — the application boots
   straight into the canvas, exactly as the local-first build always has.
   ═══════════════════════════════════════════════════════════════════════ */

/* ── The sign-in gate ──────────────────────────────────────────────────── */

.cx-gate {
  position: fixed;
  inset: 0;
  z-index: 4000;
  display: grid;
  place-items: center;
  padding: 24px;
  background: var(--bg);
  /* The workspace is already mounted behind this; it must never flash. */
  animation: cx-gate-in var(--dur-slow) var(--easing);
}
.cx-gate.done {
  opacity: 0;
  pointer-events: none;
  transition: opacity 240ms var(--easing);
}
@keyframes cx-gate-in {
  from { opacity: 0; }
  to   { opacity: 1; }
}

.cx-gate-card {
  width: min(400px, 100%);
  padding: 30px 30px 24px;
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  background: var(--surface);
  box-shadow: var(--shadow-lg);
}

.cx-gate-brand {
  display: flex;
  align-items: center;
  gap: 11px;
  margin-bottom: 26px;
}
.cx-gate-name {
  font-family: var(--f-mono);
  font-size: var(--fs-small);
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--text-main);
}
.cx-gate-sub {
  font-family: var(--f-mono);
  font-size: var(--fs-micro);
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--text-subtle);
}

.cx-gate-title {
  margin: 0 0 5px;
  font-size: 21px;
  font-weight: 650;
  letter-spacing: -0.01em;
  color: var(--text-main);
}
.cx-gate-lede {
  margin-bottom: 20px;
  font-size: var(--fs-small);
  color: var(--text-muted);
}

.cx-gate-form {
  display: flex;
  flex-direction: column;
  gap: 13px;
}
.cx-gate-form .cx-btn {
  justify-content: center;
  width: 100%;
  padding: 9px;
}
.cx-gate-form .cx-btn.loading {
  opacity: 0.65;
  pointer-events: none;
}

.cx-gate-msg:empty {
  display: none;
}
.cx-gate-msg {
  padding: 8px 10px;
  border-radius: var(--radius-sm);
  font-size: var(--fs-small);
  border: 1px solid var(--bad);
  background: color-mix(in srgb, var(--bad) 12%, transparent);
  color: var(--text-main);
}
.cx-gate-msg.good {
  border-color: var(--good);
  background: color-mix(in srgb, var(--good) 12%, transparent);
}

.cx-gate-links {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  margin-top: 16px;
}
.cx-gate-link {
  padding: 0;
  border: 0;
  background: none;
  font: inherit;
  font-size: var(--fs-small);
  color: var(--accent);
  cursor: pointer;
}
.cx-gate-link:hover {
  text-decoration: underline;
}

.cx-gate-local {
  margin-top: 20px;
  padding-top: 16px;
  border-top: 1px solid var(--border);
  text-align: center;
}
.cx-gate-local .cx-btn {
  margin-bottom: 5px;
}

/* ── Read-only ─────────────────────────────────────────────────────────── */

.cx-readonly-bar {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 6px 14px;
  border-bottom: 1px solid color-mix(in srgb, var(--warn) 40%, var(--border));
  background: color-mix(in srgb, var(--warn) 12%, transparent);
  font-size: var(--fs-small);
  color: var(--text-main);
}
.cx-readonly-bar .ro-icon {
  display: inline-flex;
  color: var(--warn);
}
/* The ask sits at the far end of the bar, away from the sentence explaining
   why it is there — it is an action, not part of the reading. */
.cx-readonly-bar .cx-btn,
.cx-readonly-bar .ro-asked {
  margin-left: auto;
}
.cx-readonly-bar .ro-asked {
  color: var(--text-muted);
  font-style: italic;
}

/* Editing affordances stand down rather than lying about what they will do. */
body.read-only #toolbar .tb-group.editing,
body.read-only #toolbar .tb-group.editing + .tb-sep,
body.read-only .nav-link[data-pane='palette'],
body.read-only .ob-handle,
body.read-only .ob-anchor {
  display: none;
}
body.read-only .tl-obj {
  cursor: default;
}

/* The inspector is entirely editing controls. A viewer can read every value —
   which is the point of view access — but typing into a field the store will
   refuse would show text that silently vanishes on the next rebuild. */
body.read-only #inspector input,
body.read-only #inspector textarea,
body.read-only #inspector select,
body.read-only #inspector .cx-btn:not(.ghost),
body.read-only #inspector .cx-toggle,
body.read-only #inspector .cx-swatch {
  pointer-events: none;
  opacity: 0.72;
}

/* ── Account block ─────────────────────────────────────────────────────── */

.cx-account {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 8px;
  padding: 7px 8px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--surface-2);
}
.cx-account .acc-main {
  flex: 1;
  min-width: 0;
}
.cx-account .acc-name {
  overflow: hidden;
  font-size: var(--fs-small);
  font-weight: 500;
  color: var(--text);
  text-overflow: ellipsis;
  white-space: nowrap;
}
.cx-account .acc-role {
  font-family: var(--f-mono);
  font-size: var(--fs-micro);
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--text-subtle);
}

.acc-avatar {
  display: grid;
  flex: 0 0 auto;
  place-items: center;
  width: 26px;
  height: 26px;
  border-radius: 50%;
  background: var(--accent);
  color: #fff;
  font-family: var(--f-mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.04em;
}
.acc-avatar.small {
  width: 22px;
  height: 22px;
  font-size: 9px;
}

/* The date window in force, on the toolbar, with its own way out. Hidden when
   no window is set. */
.tb-window {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  border-color: var(--info);
  color: var(--info);
  white-space: nowrap;
}

/* ── The canvas with nothing on it (ui/canvas_hint.js) ────────────────── */
.canvas-hint {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  pointer-events: none;
  /* Above the floating legend (40), which otherwise covers the card's buttons
     on a short canvas; below menus and dialogs. */
  z-index: 45;
}
.canvas-hint[hidden] { display: none; }
.canvas-hint-card {
  pointer-events: auto;
  max-width: 420px;
  padding: 18px 20px;
  border: 1px solid var(--border);
  border-radius: 12px;
  background: var(--surface);
  box-shadow: var(--shadow-md);
  text-align: center;
}
.canvas-hint .ch-title {
  font-weight: 600;
  color: var(--text-main);
  margin-bottom: 6px;
}
.canvas-hint .ch-msg {
  font-size: var(--fs-small);
  color: var(--text-muted);
  line-height: 1.5;
}
.canvas-hint .ch-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 6px;
  margin-top: 12px;
}

/* css/timeline.css */
/* ============================================================================
   CX Timeline — Canvas
   Ruler · lane gutter · grid · objects · connectors · today marker · minimap
   ========================================================================= */

.tl-root {
  position: absolute;
  inset: 0;
  display: grid;
  grid-template-columns: var(--lane-gutter-w) 1fr;
  grid-template-rows: var(--ruler-h) 1fr;
  grid-template-areas:
    'corner ruler'
    'gutter canvas';
  overflow: hidden;
  background: var(--canvas-bg);
  user-select: none;
}
.tl-root.no-gutter {
  grid-template-columns: 0 1fr;
}

/* ── Corner ─────────────────────────────────────────────────────────────── */
.tl-corner {
  grid-area: corner;
  background: var(--chrome-bg);
  border-right: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 3px;
  padding: 0 11px;
  z-index: 30;
}
.tl-corner .tc-label {
  font-family: var(--f-mono);
  font-size: var(--fs-micro);
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--text-subtle);
}
.tl-corner .tc-actions {
  display: flex;
  gap: 3px;
}

/* ── Ruler ──────────────────────────────────────────────────────────────── */
.tl-ruler {
  grid-area: ruler;
  position: relative;
  overflow: hidden;
  background: var(--chrome-bg);
  border-bottom: 1px solid var(--border);
  z-index: 25;
  cursor: ew-resize;
}
.tl-band {
  position: absolute;
  left: 0;
  right: 0;
  /* Clipped at the ruler edge only — individual ticks do not clip. */
  overflow: hidden;
}
.tl-band.upper {
  top: 0;
  height: 26px;
  border-bottom: 1px solid var(--border);
}
.tl-band.lower {
  top: 26px;
  bottom: 0;
}
.tl-tick {
  position: absolute;
  top: 0;
  bottom: 0;
  display: flex;
  align-items: center;
  padding-left: 7px;
  border-left: 1px solid var(--line-soft);
  white-space: nowrap;
  /* Never clipped: the renderer strides labels far enough apart that they
     cannot collide, so a label may spill past its own tick box safely. */
  overflow: visible;
  font-family: var(--f-mono);
  font-size: var(--fs-micro);
  letter-spacing: 0.06em;
  color: var(--text-subtle);
  pointer-events: none;
}
.tl-band.upper .tl-tick {
  font-weight: 700;
  font-size: var(--fs-tiny);
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--text-muted);
  border-left-color: var(--line-strong);
}
.tl-tick.major {
  border-left-color: var(--line-strong);
  color: var(--text-muted);
  font-weight: 600;
}
.tl-tick.weekend {
  background: var(--grid-weekend);
}
.tl-tick.today {
  color: var(--today-line);
  font-weight: 700;
}
.tl-tick .tk-sub {
  margin-left: 5px;
  opacity: 0.62;
  font-weight: 400;
}

/* ── Lane gutter ────────────────────────────────────────────────────────── */
.tl-gutter {
  grid-area: gutter;
  position: relative;
  overflow: hidden;
  background: var(--chrome-bg);
  border-right: 1px solid var(--border);
  z-index: 20;
}
.tl-gutter-inner {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  will-change: transform;
}
.tl-lane-label {
  position: relative;
  display: flex;
  align-items: center;
  /* The grip and the action buttons are taken out of flow below, so the lane
     name gets the full width and only wraps at real word boundaries. */
  padding: 0 30px 0 24px;
  border-bottom: 1px solid var(--border);
  overflow: hidden;
  transition: background var(--dur-fast) var(--easing);
}
.tl-lane-label:hover {
  background: var(--surface-2);
}
.tl-lane-label.dragging {
  opacity: 0.5;
}
.tl-lane-label.drop-target {
  box-shadow: inset 0 3px 0 var(--hitachi-red);
}
.tl-lane-label .ll-bar {
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 3px;
  background: currentColor;
}
.tl-lane-label .ll-grip {
  position: absolute;
  left: 7px;
  top: 8px;
  color: var(--text-subtle);
  opacity: 0;
  cursor: grab;
  display: flex;
  transition: opacity var(--dur-fast) var(--easing);
}
.tl-lane-label:hover .ll-grip {
  opacity: 0.75;
}
.tl-lane-label .ll-main {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 8px 0;
  align-self: flex-start;
}
.tl-lane-label .ll-name {
  font-size: var(--fs-small);
  font-weight: 600;
  color: var(--text);
  /* Lane names wrap; the lane grows to fit rather than hiding the name. */
  white-space: normal;
  overflow-wrap: anywhere;
  line-height: 1.28;
}
.tl-lane-label .ll-meta {
  font-family: var(--f-mono);
  font-size: 9px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--text-subtle);
  white-space: nowrap;
}
.tl-lane-label .ll-actions {
  position: absolute;
  right: 4px;
  top: 4px;
  display: flex;
  flex-direction: column;
  gap: 1px;
  opacity: 0;
  background: var(--chrome-bg);
  border-radius: 6px;
  transition: opacity var(--dur-fast) var(--easing);
}
.tl-lane-label:hover .ll-actions {
  opacity: 1;
}
.tl-lane-label.locked .ll-name {
  color: var(--text-muted);
}
.tl-lane-label.collapsed .ll-meta {
  display: none;
}
/* Lane row height handle */
.tl-lane-resize {
  position: absolute;
  left: 0;
  right: 0;
  bottom: -3px;
  height: 6px;
  cursor: row-resize;
  z-index: 5;
}
.tl-lane-resize:hover {
  background: var(--hitachi-red);
  opacity: 0.5;
}

/* ── Canvas ─────────────────────────────────────────────────────────────── */
.tl-canvas {
  grid-area: canvas;
  position: relative;
  overflow: hidden;
  cursor: default;
  /* Focused programmatically to reclaim keyboard control, never by tabbing. */
  outline: none;
}
.tl-canvas.panning {
  cursor: grabbing;
}
.tl-canvas.pan-ready {
  cursor: grab;
}
.tl-canvas.connecting {
  cursor: crosshair;
}
.tl-canvas.placing {
  cursor: copy;
}

.tl-scroll {
  position: absolute;
  inset: 0;
  overflow-y: auto;
  overflow-x: hidden;
  overscroll-behavior: contain;
}
.tl-stage {
  position: relative;
  width: 100%;
}

/* Grid layer */
.tl-grid {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 0;
}
.tl-gridline {
  position: absolute;
  top: 0;
  bottom: 0;
  width: 1px;
  background: var(--grid-line);
}
.tl-gridline.major {
  background: var(--grid-line-major);
}
.tl-gridband {
  position: absolute;
  top: 0;
  bottom: 0;
  background: var(--grid-weekend);
  pointer-events: none;
}

/* Lane bands */
.tl-lane-row {
  position: absolute;
  left: 0;
  right: 0;
  border-bottom: 1px solid var(--line-soft);
  pointer-events: none;
}
.tl-lane-row.alt {
  background: rgba(127, 127, 127, 0.024);
}
.tl-lane-row.locked {
  background-image: repeating-linear-gradient(
    45deg,
    transparent,
    transparent 7px,
    rgba(127, 127, 127, 0.035) 7px,
    rgba(127, 127, 127, 0.035) 14px
  );
}
.tl-lane-row.drop-active {
  background: var(--selection-fill);
}

/* ── Objects ────────────────────────────────────────────────────────────── */
.tl-objects {
  position: absolute;
  inset: 0;
  z-index: 2;
}

.tl-obj {
  position: absolute;
  box-sizing: border-box;
  display: flex;
  align-items: center;
  /* Labels may extend beyond the bar; the packer reserved that space. */
  overflow: visible;
  cursor: pointer;
  transition: box-shadow var(--dur-fast) var(--easing), filter var(--dur-fast) var(--easing);
  will-change: transform;
}
.tl-obj:hover {
  filter: brightness(1.08);
  z-index: 5;
}
.tl-obj.selected {
  z-index: 6;
}
.tl-obj.dragging {
  opacity: 0.86;
  z-index: 20;
  cursor: grabbing;
}
.tl-obj.locked {
  cursor: default;
}
.tl-obj.filtered-out {
  opacity: 0.16;
  filter: grayscale(0.85);
  pointer-events: none;
}
/* ── Broken dependency ──────────────────────────────────────────────────── */
.tl-obj.violated::before {
  content: '';
  position: absolute;
  inset: -2px;
  border: 1.5px solid var(--bad);
  border-radius: calc(var(--obj-radius, 6px) + 2px);
  pointer-events: none;
  z-index: 4;
  animation: objBreach 1.6s var(--easing) infinite;
}
@keyframes objBreach {
  0%,
  100% {
    box-shadow: 0 0 0 0 rgba(229, 27, 34, 0);
  }
  50% {
    box-shadow: 0 0 0 3px rgba(229, 27, 34, 0.28);
  }
}
.tl-obj .ob-breach {
  position: absolute;
  left: -3px;
  top: -9px;
  display: inline-flex;
  align-items: center;
  gap: 3px;
  padding: 1px 4px;
  border-radius: 4px;
  background: var(--bad);
  color: #fff;
  font-family: var(--f-mono);
  font-size: 8.5px;
  font-weight: 700;
  letter-spacing: 0.04em;
  white-space: nowrap;
  box-shadow: var(--shadow-sm);
  pointer-events: auto;
  cursor: help;
  z-index: 7;
}
/* Point glyphs have no top-left corner to hang the badge off. */
.tl-obj.shape-diamond .ob-breach,
.tl-obj.shape-marker .ob-breach,
.tl-obj.shape-release .ob-breach {
  left: 50%;
  top: -11px;
  transform: translateX(-50%);
}

.tl-obj.search-hit {
  animation: hitPulse 1.5s var(--easing) 2;
}
@keyframes hitPulse {
  0%,
  100% {
    box-shadow: 0 0 0 0 rgba(230, 0, 18, 0);
  }
  50% {
    box-shadow: 0 0 0 4px rgba(230, 0, 18, 0.5);
  }
}

/* Bar */
.tl-obj.shape-bar .ob-body,
.tl-obj.shape-band .ob-body,
.tl-obj.shape-container .ob-body {
  position: absolute;
  inset: 0;
  border-radius: inherit;
  overflow: hidden;
}
.tl-obj .ob-fill {
  position: absolute;
  inset: 0;
}
.tl-obj .ob-progress {
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  background: rgba(255, 255, 255, 0.26);
  border-right: 1px solid rgba(255, 255, 255, 0.45);
  pointer-events: none;
}
:root[data-theme='light'] .tl-obj .ob-progress,
:root[data-theme='presentation'] .tl-obj .ob-progress {
  background: rgba(0, 0, 0, 0.16);
  border-right-color: rgba(0, 0, 0, 0.3);
}
/* ── Labels ───────────────────────────────────────────────────────────────
   Nothing here truncates. The layout pass measures every label, wraps it and
   reserves the room it needs, so these rules only have to print the lines.
   -------------------------------------------------------------------------- */
.tl-obj .ob-label {
  position: relative;
  z-index: 2;
  display: flex;
  align-items: center;
  gap: 5px;
  padding: 0 8px;
  min-width: 0;
  width: 100%;
  overflow: visible;
  pointer-events: none;
}
.tl-obj .ob-textwrap {
  display: flex;
  flex-direction: column;
  justify-content: center;
  min-width: 0;
  line-height: 1.28;
}
.tl-obj .ob-line {
  display: block;
  white-space: pre;
  overflow: visible;
}
.tl-obj .ob-sub {
  font-size: 0.84em;
  font-weight: 400;
  opacity: 0.8;
}

/* Full label beside a bar too narrow to hold it. */
.tl-obj .ob-outside {
  position: absolute;
  left: 100%;
  top: 50%;
  transform: translateY(-50%);
  margin-left: 7px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  font-size: var(--fs-tiny);
  line-height: 1.28;
  color: var(--text);
  pointer-events: none;
  z-index: 3;
}
.tl-obj .ob-outside .ob-sub {
  color: var(--text-muted);
}

/* Centred label under (or over) a point glyph. */
.tl-obj .ob-point-label {
  position: absolute;
  left: 50%;
  top: calc(50% + 13px);
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  line-height: 1.28;
  font-size: var(--fs-tiny);
  font-weight: 600;
  color: var(--text);
  pointer-events: none;
  z-index: 3;
  text-shadow: 0 1px 3px var(--canvas-bg), 0 0 6px var(--canvas-bg);
}
.tl-obj .ob-point-label.above {
  top: auto;
  bottom: calc(50% + 13px);
}
.tl-obj .ob-point-label .ob-sub {
  font-weight: 500;
  color: var(--text-muted);
}
.tl-obj .ob-icon {
  flex: 0 0 auto;
  display: flex;
  opacity: 0.9;
}
.tl-obj .ob-pct {
  font-family: var(--f-mono);
  font-size: 9px;
  font-weight: 600;
  opacity: 0.85;
  margin-left: auto;
  padding-left: 6px;
  flex: 0 0 auto;
}

/* Band — freeze / outage / maintenance: full-lane translucent block */
.tl-obj.shape-band .ob-fill {
  opacity: 0.2;
}
.tl-obj.shape-band {
  border-style: dashed;
}
.tl-obj.shape-band .ob-label {
  font-weight: 600;
}

/* Container — an outline that groups a stretch of the plan */
.tl-obj.shape-container .ob-fill {
  opacity: 0.07;
}
.tl-obj.shape-container .ob-label {
  align-items: flex-start;
  padding-top: 3px;
}

/* Milestone / diamond */
.tl-obj.shape-diamond,
.tl-obj.shape-release,
.tl-obj.shape-marker {
  justify-content: center;
  overflow: visible;
}
.tl-obj .ob-glyph {
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  display: flex;
  align-items: center;
  justify-content: center;
}
.tl-obj .ob-diamond {
  width: 15px;
  height: 15px;
  transform: rotate(45deg);
  border-radius: 2px;
}

/* Release flag */
.tl-obj.shape-release .ob-flag {
  position: absolute;
  left: 50%;
  top: 4px;
  bottom: 4px;
  width: 3px;
  transform: translateX(-50%);
  border-radius: 2px;
}
.tl-obj.shape-release .ob-chip {
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 2px 7px;
  border-radius: 5px;
  font-family: var(--f-mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.04em;
  white-space: nowrap;
  border: 1px solid;
  box-shadow: var(--shadow-sm);
}

/* Marker — risk / issue / decision / document pin */
.tl-obj.shape-marker .ob-pin {
  width: 20px;
  height: 20px;
  border-radius: 50% 50% 50% 2px;
  transform: rotate(45deg);
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: var(--shadow-sm);
}
.tl-obj.shape-marker .ob-pin > span {
  transform: rotate(-45deg);
  display: flex;
}

/* Sticky note */
.tl-obj.shape-sticky {
  align-items: flex-start;
}
.tl-obj.shape-sticky .ob-body {
  position: absolute;
  inset: 0;
  border-radius: inherit;
  box-shadow: var(--shadow-md);
  overflow: hidden;
}
.tl-obj.shape-sticky .ob-note {
  position: relative;
  z-index: 2;
  padding: 6px 8px;
  font-size: var(--fs-tiny);
  line-height: 1.4;
  width: 100%;
  /* The note grows to fit its text — nothing is clamped away. */
  overflow: visible;
}

/* Callout */
.tl-obj.shape-callout .ob-tail {
  position: absolute;
  left: 14px;
  bottom: -7px;
  width: 12px;
  height: 12px;
  transform: rotate(45deg);
  border-right: 1px solid;
  border-bottom: 1px solid;
}

/* Text box */
.tl-obj.shape-text {
  background: transparent;
  border: 1px dashed transparent;
}
.tl-obj.shape-text:hover,
.tl-obj.shape-text.selected {
  border-color: var(--border-strong);
}
.tl-obj.shape-text .ob-label {
  white-space: normal;
  align-items: flex-start;
  padding: 4px 6px;
}

/* Image */
.tl-obj.shape-image .ob-img {
  position: absolute;
  inset: 0;
  object-fit: cover;
  border-radius: inherit;
}
.tl-obj.shape-image .ob-img-missing {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-subtle);
  background: var(--surface-2);
  border-radius: inherit;
}

/* Selection chrome */
.tl-obj.selected::after {
  content: '';
  position: absolute;
  inset: -3px;
  border: 2px solid var(--selection);
  border-radius: calc(var(--obj-radius, 6px) + 3px);
  pointer-events: none;
}
.tl-obj.shape-diamond.selected::after,
.tl-obj.shape-marker.selected::after,
.tl-obj.shape-release.selected::after {
  border-radius: 50%;
  inset: -2px;
}

/* ── What the selection is waiting on ───────────────────────────────────────
   Selecting a bar marks its predecessors and the arrows arriving from them,
   for as long as the selection stands. The ring is dashed where the selection's
   own is solid, so "this is the one I clicked" and "this comes first" are never
   confused. It is an outline rather than a pseudo-element on purpose: ::before
   already carries the broken-dependency ring and ::after the selection ring,
   and a predecessor may well be either. */
.tl-obj.upstream {
  outline: 2px dashed var(--upstream);
  outline-offset: 2px;
  border-radius: var(--obj-radius, 6px);
}
.tl-obj.shape-diamond.upstream,
.tl-obj.shape-marker.upstream,
.tl-obj.shape-release.upstream {
  border-radius: 50%;
}
/* A filtered-out predecessor stays quiet: the filter is the stronger statement. */
.tl-obj.filtered-out.upstream {
  outline: none;
}

/* The flash. One-shot, fired by the renderer when the selection changes: it
   says where to look, then gets out of the way of the standing highlight. */
.tl-obj.upstream-flash {
  animation: upstreamFlash 0.4s var(--easing) 3;
}
@keyframes upstreamFlash {
  0%,
  100% {
    box-shadow: 0 0 0 0 var(--upstream-glow);
  }
  45% {
    box-shadow: 0 0 0 5px var(--upstream-glow);
  }
}

/* Resize handles */
.tl-handle {
  position: absolute;
  top: 0;
  bottom: 0;
  width: 8px;
  cursor: ew-resize;
  z-index: 8;
  display: flex;
  align-items: center;
  justify-content: center;
}
.tl-handle.left {
  left: -4px;
}
.tl-handle.right {
  right: -4px;
}
.tl-handle::before {
  content: '';
  width: 3px;
  height: 60%;
  min-height: 10px;
  border-radius: 2px;
  background: var(--selection);
  opacity: 0;
  transition: opacity var(--dur-fast) var(--easing);
}
.tl-obj.selected .tl-handle::before,
.tl-obj:hover .tl-handle::before {
  opacity: 0.95;
}

/* Connection anchors */
.tl-anchor {
  position: absolute;
  top: 50%;
  width: 11px;
  height: 11px;
  margin-top: -5.5px;
  border-radius: 50%;
  background: var(--surface);
  border: 2px solid var(--selection);
  opacity: 0;
  transition: opacity var(--dur-fast) var(--easing), transform var(--dur-fast) var(--easing);
  cursor: crosshair;
  z-index: 9;
}
.tl-anchor.start {
  left: -13px;
}
.tl-anchor.end {
  right: -13px;
}
.tl-obj:hover .tl-anchor,
.tl-obj.selected .tl-anchor,
.tl-canvas.connecting .tl-anchor {
  opacity: 1;
}
.tl-anchor:hover {
  transform: scale(1.3);
  background: var(--selection);
}

/* ══════════════════════════════════════════════════════════════════════════
   Baseline comparison

   The ghost sits behind the live bar at the same height, so the pair reads as
   one object that moved. The arrow between their finish edges is what carries
   the message across a lane — the ghost alone is easy to miss.
   ═══════════════════════════════════════════════════════════════════════ */

.tl-baseline {
  position: absolute;
  border: 1.5px dashed var(--text-subtle);
  border-radius: 5px;
  background: repeating-linear-gradient(
    45deg,
    transparent,
    transparent 5px,
    color-mix(in srgb, var(--text-subtle) 22%, transparent) 5px,
    color-mix(in srgb, var(--text-subtle) 22%, transparent) 10px
  );
  /* The striped area takes the reason the plan moved, so it accepts a press.
     It still sits below the objects (z 100), which is what keeps a click on an
     overlapping bar going to the bar. */
  pointer-events: auto;
  cursor: text;
  /* Behind the objects (z 100) but above the lane bands. */
  z-index: 60;
}
.tl-baseline.slip {
  border-color: var(--bad);
  background: repeating-linear-gradient(
    45deg,
    transparent,
    transparent 5px,
    color-mix(in srgb, var(--bad) 20%, transparent) 5px,
    color-mix(in srgb, var(--bad) 20%, transparent) 10px
  );
}
.tl-baseline.ahead {
  border-color: var(--good);
  background: repeating-linear-gradient(
    45deg,
    transparent,
    transparent 5px,
    color-mix(in srgb, var(--good) 20%, transparent) 5px,
    color-mix(in srgb, var(--good) 20%, transparent) 10px
  );
}
.tl-baseline.reshaped {
  border-color: var(--warn);
}

/* ══════════════════════════════════════════════════════════════════════════
   What actually happened
   ══════════════════════════════════════════════════════════════════════════
   A slim solid bar on its own floor directly under the scheduled one, wherever
   somebody has recorded a date that differs from the plan. Solid, not striped:
   a ghost is a claim another snapshot makes about this bar, and this is the bar
   — what it did. Below rather than behind, because the two nearly always
   overlap, and two bars sharing a height at nearly the same dates is a smear
   rather than a comparison.
   ═══════════════════════════════════════════════════════════════════════ */

.tl-actual {
  position: absolute;
  border-radius: 3px;
  background: var(--text-subtle);
  pointer-events: auto;
  /* Above the lane bands and the ghost, below the objects (z 100): a press on
     an overlapping bar still goes to the bar. */
  z-index: 70;
}
.tl-actual.late { background: var(--bad); }
.tl-actual.early { background: var(--good); }
.tl-actual.shifted { background: var(--warn); }

/* Started and not finished. The recorded end is the scheduled one — "it began
   on the 4th and is still due on the 20th" — so the bar fades out rather than
   ending in a square edge that would read as a finish somebody reported. */
.tl-actual.open {
  -webkit-mask-image: linear-gradient(to right, #000 55%, transparent 100%);
  mask-image: linear-gradient(to right, #000 55%, transparent 100%);
}

/* The same arrow the comparison draws, between the scheduled edge and the one
   actually hit. Its own class so the two can diverge without a `kind` argument
   threaded through every call for the sake of one word. */
.tl-actual-shift {
  position: absolute;
  height: 0;
  pointer-events: none;
  z-index: 140;
}
.tl-actual-shift .sh-line {
  position: absolute;
  top: -1px;
  left: 0;
  width: 100%;
  height: 2px;
  border-radius: 1px;
  background: currentColor;
}
.tl-actual-shift .sh-head {
  position: absolute;
  top: -4px;
  width: 0;
  height: 0;
  border-top: 4.5px solid transparent;
  border-bottom: 4.5px solid transparent;
}
.tl-actual-shift.right .sh-head {
  right: -1px;
  border-left: 7px solid currentColor;
}
.tl-actual-shift.left .sh-head {
  left: -1px;
  border-right: 7px solid currentColor;
}
.tl-actual-shift .sh-days {
  position: absolute;
  top: -9px;
  left: 50%;
  padding: 1px 5px;
  transform: translateX(-50%);
  border: 1px solid currentColor;
  border-radius: 999px;
  background: var(--surface);
  color: currentColor;
  font-family: var(--f-mono);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.04em;
  white-space: nowrap;
}
.tl-actual-shift.late { color: var(--bad); }
.tl-actual-shift.early { color: var(--good); }
.tl-actual-shift.shifted { color: var(--warn); }

/* ── An object's note, shown under it ──────────────────────────────────── */

/* Whole, wrapped as it was measured, in the band the packer reserved. No
   overflow rule belongs here: this is one more piece of timeline text, and the
   way to shorten it is to write less or switch it off. */
.tl-note {
  position: absolute;
  display: flex;
  flex-direction: column;
  justify-content: flex-start;
  padding: 0 6px;
  border-left: 2px solid color-mix(in srgb, var(--text-subtle) 55%, transparent);
  color: var(--text-muted);
  pointer-events: none;
  z-index: 55;
}
.tl-note .tn-line {
  color: inherit;
  font-family: var(--f-ui);
  font-size: 10px;
  font-style: italic;
  font-weight: 400;
  line-height: 13px;
  white-space: nowrap;
}

/* ── Why it moved ──────────────────────────────────────────────────────── */

/* Hovering says the area answers to a click without printing anything that
   would have to be measured first. */
.tl-baseline:hover {
  border-style: solid;
}
body.read-only .tl-baseline,
body.read-only .tl-baseline-reason {
  cursor: default;
}

/* Written inside the ghost only when layout measured it to fit on one line
   there — never clipped, so no overflow rule belongs here. */
.tl-baseline .bl-reason {
  display: block;
  padding: 0 6px;
  color: currentColor;
  font-family: var(--f-ui);
  font-size: 10px;
  font-weight: 600;
  line-height: 13px;
  white-space: nowrap;
}
.tl-baseline.slip .bl-reason { color: var(--bad); }
.tl-baseline.ahead .bl-reason { color: var(--good); }
.tl-baseline.reshaped .bl-reason { color: var(--warn); }

/* Too long for the striped area: it goes in the band packing reserved along
   the bottom of the row, one span per measured line. */
.tl-baseline-reason {
  position: absolute;
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 1px 6px;
  border-left: 2px solid currentColor;
  border-radius: 0 3px 3px 0;
  background: color-mix(in srgb, var(--surface) 78%, transparent);
  color: var(--text-subtle);
  cursor: text;
  pointer-events: auto;
  z-index: 70;
}
.tl-baseline-reason.slip { color: var(--bad); }
.tl-baseline-reason.ahead { color: var(--good); }
.tl-baseline-reason.reshaped { color: var(--warn); }
.tl-baseline-reason .br-line {
  color: currentColor;
  font-family: var(--f-ui);
  font-size: 10px;
  font-weight: 600;
  line-height: 13px;
  white-space: nowrap;
}

/* The editor itself: a plain field over the striped area, so typing happens
   where the text will end up rather than in a dialog somewhere else. */
.tl-reason-input {
  position: absolute;
  min-height: 34px;
  padding: 4px 6px;
  border: 1.5px solid var(--selection);
  border-radius: 5px;
  background: var(--surface);
  color: var(--text);
  font-family: var(--f-ui);
  font-size: 11px;
  line-height: 14px;
  resize: none;
  box-shadow: var(--shadow-lg);
  z-index: 400;
}
.tl-reason-input:focus {
  outline: none;
}

/* A ghost covering the same dates as its own bar cannot sit behind it — the two
   would read as one pile. Layout gives it a slim tier under the bar instead and
   grows the row, so it reads as the bar's shadow. */
.tl-baseline.stacked {
  border-width: 1px;
  border-radius: 3px;
}

/* ── The shift ─────────────────────────────────────────────────────────── */

.tl-shift {
  position: absolute;
  height: 0;
  pointer-events: none;
  z-index: 140; /* above the bars: this is the headline */
}
.tl-shift .sh-line {
  position: absolute;
  top: -1px;
  left: 0;
  width: 100%;
  height: 2px;
  border-radius: 1px;
  background: currentColor;
}
.tl-shift .sh-head {
  position: absolute;
  top: -4px;
  width: 0;
  height: 0;
  border-top: 4.5px solid transparent;
  border-bottom: 4.5px solid transparent;
}
.tl-shift.right .sh-head {
  right: -1px;
  border-left: 7px solid currentColor;
}
.tl-shift.left .sh-head {
  left: -1px;
  border-right: 7px solid currentColor;
}
.tl-shift .sh-days {
  position: absolute;
  top: -9px;
  left: 50%;
  padding: 1px 5px;
  transform: translateX(-50%);
  border: 1px solid currentColor;
  border-radius: 999px;
  background: var(--surface);
  color: currentColor;
  font-family: var(--f-mono);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.04em;
  white-space: nowrap;
}
.tl-shift.slip {
  color: var(--bad);
}
.tl-shift.ahead {
  color: var(--good);
}
.tl-shift.reshaped {
  color: var(--warn);
}

/* ── Gone since the baseline ───────────────────────────────────────────── */

/* Nothing else in the application shows these: the object is not in the
   document any more, so only the snapshot knows it existed. */
.tl-baseline-gone {
  position: absolute;
  display: flex;
  align-items: center;
  padding: 0 6px;
  border: 1.5px dashed var(--bad);
  border-radius: 5px;
  background: color-mix(in srgb, var(--bad) 8%, transparent);
  opacity: 0.75;
  pointer-events: none;
  z-index: 60;
}
/* The name spills past a narrow outline rather than being clipped by it —
   layout measured it and reserved the room, like every other timeline label. */
.tl-baseline-gone .bg-label {
  flex: 0 0 auto;
  color: var(--bad);
  font-size: var(--fs-micro);
  font-style: italic;
  text-decoration: line-through;
  white-space: nowrap;
}

.tl-slip-arrow.slip {
  background: var(--bad);
}
.tl-slip-arrow.ahead {
  background: var(--good);
}

/* ── Connectors ─────────────────────────────────────────────────────────── */
.tl-connectors {
  position: absolute;
  inset: 0;
  overflow: visible;
  pointer-events: none;
  z-index: 3;
}
.tl-link {
  fill: none;
  stroke: var(--connector);
  stroke-width: 1.5;
  pointer-events: stroke;
  cursor: pointer;
  transition: stroke var(--dur-fast) var(--easing), stroke-width var(--dur-fast) var(--easing);
}
.tl-link:hover {
  stroke: var(--selection);
  stroke-width: 2.5;
}
.tl-link.selected {
  stroke: var(--selection);
  stroke-width: 2.5;
}
.tl-link.critical {
  stroke: var(--bad);
  stroke-width: 2.2;
}
/* A dependency arriving at the selection. Wins over the critical-path colour —
   the critical path is standing information, this is the answer to a click the
   user just made — but not over a violation, which is a fault. */
.tl-link.upstream:not(.violated) {
  stroke: var(--upstream);
  stroke-width: 2.6;
}
.tl-link.upstream.flash:not(.violated) {
  animation: linkUpstream 0.4s var(--easing) 3;
}
@keyframes linkUpstream {
  0%,
  100% {
    stroke-width: 2.6;
  }
  45% {
    stroke-width: 5.5;
  }
}
/* A dependency whose precedence constraint is currently impossible. */
.tl-link.violated {
  stroke: var(--bad) !important;
  stroke-width: 2.4;
  stroke-dasharray: 7 4;
  animation: linkBreach 1.1s linear infinite;
}
.tl-link.violated:hover {
  stroke-width: 3.2;
}
@keyframes linkBreach {
  to {
    stroke-dashoffset: -22;
  }
}
.tl-link-label.violated {
  fill: var(--bad);
  font-weight: 700;
}
.tl-link.dim {
  opacity: 0.22;
}
.tl-link-hit {
  fill: none;
  stroke: transparent;
  stroke-width: 11;
  pointer-events: stroke;
  cursor: pointer;
}
.tl-link-label {
  font-family: var(--f-mono);
  font-size: 9px;
  fill: var(--text-subtle);
  pointer-events: none;
}
.tl-link-preview {
  fill: none;
  stroke: var(--selection);
  stroke-width: 2;
  stroke-dasharray: 5 4;
  pointer-events: none;
}

/* ── Today marker ───────────────────────────────────────────────────────── */
.tl-today {
  position: absolute;
  top: 0;
  bottom: 0;
  width: 2px;
  background: var(--today-line);
  pointer-events: none;
  z-index: 7;
  box-shadow: 0 0 10px var(--today-line);
}
.tl-today.simulated {
  background: repeating-linear-gradient(
    to bottom,
    var(--today-line) 0,
    var(--today-line) 6px,
    transparent 6px,
    transparent 11px
  );
  box-shadow: none;
}
.tl-today-flag {
  position: absolute;
  top: 0;
  left: 0;
  transform: translateX(-50%);
  z-index: 28;
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 2px 7px;
  border-radius: 0 0 5px 5px;
  background: var(--today-line);
  color: #fff;
  font-family: var(--f-mono);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.14em;
  white-space: nowrap;
  pointer-events: none;
}
.tl-today-flag.simulated {
  background: var(--warn);
  color: var(--text-inverse);
}

/* ── Marquee selection ──────────────────────────────────────────────────── */
.tl-marquee {
  position: absolute;
  border: 1px solid var(--selection);
  background: var(--selection-fill);
  border-radius: 3px;
  pointer-events: none;
  z-index: 10;
}

/* ── Drag guide line (snap feedback) ────────────────────────────────────── */
.tl-guide {
  position: absolute;
  top: 0;
  bottom: 0;
  width: 1px;
  background: var(--selection);
  pointer-events: none;
  z-index: 9;
  opacity: 0.75;
}
.tl-guide-label {
  position: absolute;
  top: 4px;
  transform: translateX(-50%);
  padding: 2px 6px;
  border-radius: 4px;
  background: var(--selection);
  color: #fff;
  font-family: var(--f-mono);
  font-size: 9px;
  font-weight: 700;
  white-space: nowrap;
  pointer-events: none;
  z-index: 11;
}

/* ── Minimap ────────────────────────────────────────────────────────────── */
.tl-minimap {
  position: absolute;
  right: 14px;
  bottom: 14px;
  width: 300px;
  height: 74px;
  background: var(--surface);
  border: 1px solid var(--border-strong);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-lg);
  overflow: hidden;
  z-index: 40;
  cursor: pointer;
  transition: opacity var(--dur) var(--easing);
}
.tl-minimap.hidden {
  display: none;
}
.tl-minimap:hover {
  border-color: var(--line-strong);
}
.tl-minimap-head {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 17px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 6px;
  background: var(--surface-2);
  border-bottom: 1px solid var(--border);
  font-family: var(--f-mono);
  font-size: 8px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--text-subtle);
  z-index: 2;
}
.tl-minimap-body {
  position: absolute;
  top: 17px;
  left: 0;
  right: 0;
  bottom: 0;
}
.tl-mini-obj {
  position: absolute;
  height: 3px;
  border-radius: 2px;
  min-width: 2px;
}
.tl-mini-today {
  position: absolute;
  top: 0;
  bottom: 0;
  width: 1px;
  background: var(--today-line);
}
.tl-mini-view {
  position: absolute;
  top: 0;
  bottom: 0;
  border: 1px solid var(--selection);
  background: var(--selection-fill);
  border-radius: 2px;
  cursor: grab;
}
.tl-mini-view:active {
  cursor: grabbing;
}

/* ── Legend ─────────────────────────────────────────────────────────────── */
.tl-legend {
  position: absolute;
  /* Clear of the lane gutter, which shares this containing block. */
  left: calc(var(--lane-gutter-w) + 14px);
  bottom: 14px;
  max-width: 300px;
  max-height: 46%;
  overflow-y: auto;
  background: var(--surface);
  border: 1px solid var(--border-strong);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-lg);
  padding: 9px 11px;
  z-index: 40;
  font-size: var(--fs-tiny);
}
.tl-legend.hidden {
  display: none;
}
.tl-legend-title {
  font-family: var(--f-mono);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--text-subtle);
  margin-bottom: 6px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.tl-legend-group + .tl-legend-group {
  margin-top: 8px;
  padding-top: 7px;
  border-top: 1px solid var(--border);
}
.tl-legend-items {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.tl-legend-item {
  display: flex;
  align-items: center;
  gap: 7px;
  color: var(--text-muted);
  cursor: pointer;
  border-radius: 4px;
  padding: 1px 3px;
  transition: background var(--dur-fast) var(--easing), color var(--dur-fast) var(--easing);
}
.tl-legend-item:hover {
  background: var(--surface-2);
  color: var(--text);
}
.tl-legend-item.off {
  opacity: 0.4;
}
.tl-legend-item .li-count {
  margin-left: auto;
  font-family: var(--f-mono);
  font-size: 9px;
  color: var(--text-subtle);
}

/* ── Empty canvas state ─────────────────────────────────────────────────── */
.tl-empty {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 12px;
  pointer-events: none;
  z-index: 4;
}
.tl-empty > * {
  pointer-events: auto;
}

/* ── Presentation mode canvas tweaks ────────────────────────────────────── */
body.presenting .tl-handle,
body.presenting .tl-anchor,
body.presenting .tl-lane-label .ll-actions,
body.presenting .tl-lane-label .ll-grip,
body.presenting .tl-lane-resize {
  display: none !important;
}
body.presenting .tl-obj {
  cursor: default;
}
body.presenting .tl-root {
  --ruler-h: 52px;
}

/* ── Print / PDF ────────────────────────────────────────────────────────── */
@media print {
  @page {
    size: A3 landscape;
    margin: 10mm;
  }
  body {
    background: #fff;
  }
  #sidenav,
  #toolbar,
  #dock,
  #inspector,
  #statusbar,
  .tl-minimap,
  #cx-toasts {
    display: none !important;
  }
  #app {
    grid-template-columns: 1fr;
    grid-template-areas: 'main';
    height: auto;
  }
  .tl-root {
    position: static;
    height: auto;
  }
  .tl-scroll {
    overflow: visible;
    position: static;
  }
}

/* ── Baseline mode banner ──────────────────────────────────────────────── */

/* Comparison changes what every bar means, so the canvas says so. */
.tl-baseline-bar {
  position: absolute;
  /* Below the ruler, not over it — the ruler is how you read every date on
     the canvas, and the banner covering it made the plan harder to read, not
     easier. */
  z-index: 30;
  top: var(--ruler-h);
  right: 0;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 5px 12px;
  border: 1px solid color-mix(in srgb, var(--accent) 40%, var(--border));
  border-top: 0;
  border-right: 0;
  border-bottom-left-radius: 10px;
  background: var(--surface);
  box-shadow: var(--shadow-sm);
  font-size: var(--fs-tiny);
  pointer-events: none;
}
.tl-baseline-bar .bb-eyebrow {
  font-family: var(--f-mono);
  font-size: var(--fs-micro);
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--text-subtle);
}
.tl-baseline-bar .bb-name {
  max-width: 220px;
  overflow: hidden;
  color: var(--text-main);
  font-weight: 600;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.tl-baseline-bar .bb-sep {
  width: 1px;
  height: 13px;
  background: var(--border-strong);
}
.tl-baseline-bar .bb-stat {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-family: var(--f-mono);
  font-size: var(--fs-micro);
  letter-spacing: 0.03em;
}
.tl-baseline-bar .bb-stat::before {
  content: '';
  width: 7px;
  height: 7px;
  border-radius: 2px;
  background: currentColor;
}
.tl-baseline-bar .bb-stat.slip { color: var(--bad); }
.tl-baseline-bar .bb-stat.ahead { color: var(--good); }
.tl-baseline-bar .bb-stat.reshaped { color: var(--warn); }
.tl-baseline-bar .bb-stat.gone { color: var(--bad); }
.tl-baseline-bar .bb-stat.none { color: var(--text-subtle); }

/* Presentation mode strips the chrome, but this is content, not chrome. */
body.presenting .tl-baseline-bar {
  display: flex;
}

/* ── Drop target ───────────────────────────────────────────────────────── */

/* While a P6 activity is being dragged, the bar under the pointer says it
   will accept the link. The whole canvas dims its labels slightly so the
   outlined target is the thing the eye lands on. */
.tl-obj.drop-target {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
  box-shadow: 0 0 0 6px color-mix(in srgb, var(--accent) 22%, transparent);
}
/* ── The end a dependency will arrive at ───────────────────────────────── */

/* Which edge of the target the pointer is over decides the relationship the
   drop creates — finish-to-start or finish-to-finish are the same gesture
   ending 40px apart — so the edge says so before the mouse is released. */
.tl-obj.link-target {
  outline: 1.5px solid var(--selection);
  outline-offset: 1px;
}
/* A child element rather than a pseudo-element: `::after` is already the
   selection ring and `::before` the broken-dependency badge, and a bar can be
   selected while it is being linked to. */
.tl-link-end {
  position: absolute;
  top: -3px;
  bottom: -3px;
  width: 4px;
  border-radius: 2px;
  background: var(--selection);
  pointer-events: none;
  z-index: 6;
}
.tl-link-end.at-start {
  left: -3px;
}
.tl-link-end.at-end {
  right: -3px;
}

body.p6-dragging .tl-obj {
  transition: opacity var(--dur-fast) var(--easing);
}
body.p6-dragging .tl-canvas {
  cursor: copy;
}

/* css/notes.css */
/* ============================================================================
   CX Timeline — Rich notes editor & rendered notes
   ========================================================================= */

.note-editor {
  display: flex;
  flex-direction: column;
  border: 1px solid var(--border-strong);
  border-radius: var(--radius-md);
  overflow: hidden;
  background: var(--surface-2);
}

.note-toolbar {
  display: flex;
  align-items: center;
  gap: 2px;
  flex-wrap: wrap;
  padding: 5px 6px;
  background: var(--surface-3);
  border-bottom: 1px solid var(--border);
}
.note-tb-sep {
  width: 1px;
  height: 16px;
  background: var(--border-strong);
  margin: 0 4px;
}

.note-surface {
  padding: 12px 14px;
  font-family: var(--f-body), var(--f-ui);
  font-size: var(--fs-body);
  line-height: 1.6;
  color: var(--text);
  background: var(--surface);
  overflow-y: auto;
  max-height: 52vh;
  outline: none;
}
.note-surface:focus {
  box-shadow: inset 0 0 0 2px rgba(230, 0, 18, 0.18);
}

/* ── Shared note typography (editor + rendered) ─────────────────────────── */
.note-surface h1,
.note-render h1 {
  font-size: 20px;
  font-weight: 700;
  margin: 14px 0 6px;
}
.note-surface h2,
.note-render h2 {
  font-size: 17px;
  font-weight: 700;
  margin: 12px 0 5px;
}
.note-surface h3,
.note-render h3 {
  font-size: 15px;
  font-weight: 700;
  margin: 11px 0 4px;
}
.note-surface p,
.note-render p {
  margin: 0 0 8px;
}
.note-surface ul,
.note-render ul {
  list-style: disc;
  padding-left: 22px;
  margin: 0 0 8px;
}
.note-surface ol,
.note-render ol {
  list-style: decimal;
  padding-left: 22px;
  margin: 0 0 8px;
}
.note-surface li,
.note-render li {
  margin: 2px 0;
}
.note-surface blockquote,
.note-render blockquote {
  margin: 8px 0;
  padding: 6px 12px;
  border-left: 3px solid var(--border-strong);
  color: var(--text-muted);
  font-style: italic;
}
.note-surface a,
.note-render a {
  color: var(--accent-blue);
  text-decoration: underline;
  text-underline-offset: 2px;
}
.note-surface a:hover,
.note-render a:hover {
  color: var(--hitachi-red);
}
.note-surface hr,
.note-render hr {
  border: none;
  border-top: 1px solid var(--border-strong);
  margin: 12px 0;
}
.note-surface img,
.note-render img {
  max-width: 100%;
  border-radius: var(--radius-sm);
  margin: 6px 0;
  display: block;
}
.note-surface code,
.note-render code {
  font-family: var(--f-mono);
  font-size: 0.92em;
  background: var(--surface-3);
  padding: 1px 5px;
  border-radius: 4px;
}
.note-surface pre,
.note-render pre {
  font-family: var(--f-mono);
  font-size: var(--fs-small);
  background: var(--surface-3);
  padding: 10px 12px;
  border-radius: var(--radius-sm);
  overflow-x: auto;
  margin: 0 0 8px;
}

.note-surface table,
.note-render table {
  border-collapse: collapse;
  width: 100%;
  margin: 8px 0;
  font-size: var(--fs-small);
}
.note-surface th,
.note-render th {
  background: var(--surface-3);
  font-family: var(--f-mono);
  font-size: var(--fs-micro);
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--text-muted);
  text-align: left;
}
.note-surface th,
.note-surface td,
.note-render th,
.note-render td {
  border: 1px solid var(--border-strong);
  padding: 5px 8px;
}

.note-check {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  margin: 3px 0;
}
.note-check input[type='checkbox'] {
  appearance: none;
  width: 14px;
  height: 14px;
  margin-top: 3px;
  border-radius: 4px;
  border: 1px solid var(--border-strong);
  background: var(--surface-2);
  cursor: pointer;
  position: relative;
  flex: 0 0 auto;
}
.note-check input[type='checkbox']:checked {
  background: var(--good);
  border-color: var(--good);
}
.note-check input[type='checkbox']:checked::after {
  content: '';
  position: absolute;
  left: 4px;
  top: 1px;
  width: 4px;
  height: 8px;
  border: solid #fff;
  border-width: 0 2px 2px 0;
  transform: rotate(45deg);
}
.note-check input[type='checkbox']:checked + span {
  text-decoration: line-through;
  color: var(--text-subtle);
}

/* ── Rendered (read-only) ───────────────────────────────────────────────── */
.note-render {
  font-family: var(--f-body), var(--f-ui);
  font-size: var(--fs-small);
  line-height: 1.55;
  color: var(--text-muted);
  overflow-y: auto;
}
.note-render > *:last-child {
  margin-bottom: 0;
}

/* ── Attachment list ────────────────────────────────────────────────────── */
.att-list {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.att-row {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 8px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--surface-2);
  font-size: var(--fs-tiny);
  transition: border-color var(--dur-fast) var(--easing), background var(--dur-fast) var(--easing);
}
.att-row:hover {
  border-color: var(--border-strong);
  background: var(--surface-3);
}
.att-row .att-icon {
  color: var(--text-subtle);
  display: flex;
  flex: 0 0 auto;
}
.att-row .att-main {
  flex: 1;
  min-width: 0;
}
.att-row .att-name {
  color: var(--text);
  font-weight: 500;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.att-row .att-meta {
  font-family: var(--f-mono);
  font-size: 9px;
  color: var(--text-subtle);
  letter-spacing: 0.05em;
}
.att-drop {
  border: 1px dashed var(--border-strong);
  border-radius: var(--radius-md);
  padding: 14px;
  text-align: center;
  font-size: var(--fs-tiny);
  color: var(--text-subtle);
  transition: border-color var(--dur-fast) var(--easing), background var(--dur-fast) var(--easing);
  cursor: pointer;
}
.att-drop:hover,
.att-drop.over {
  border-color: var(--hitachi-red);
  background: var(--surface-2);
  color: var(--text-muted);
}

/* css/calendar.css */
/* ============================================================================
   CX Timeline — Resource Calendar, the part the page needs before it opens
   Workspace switch · the calendar's stage · the look-ahead grid the timeline
   also draws

   Everything that styles only what the calendar bundle builds is in rc.css,
   which ui/calendar_loader.js fetches with calendar.bundle.js the first time
   the calendar opens — it is most of the calendar's styling, and a page that
   never opens the calendar should not download it. A rule stays here if the
   main bundle can draw an element it matches (`.ws-*`, `.la-*`, the frame
   itself), or if moving it later would let it win a tie it used to lose —
   rc.css loads after this file, so order between the two is not the order
   they were written in. `.rc-table td/th` stay for that reason: the
   look-ahead's tables are `.rc-table.la-grid`, and `.la-grid td` must win.

   Every colour goes through a token. The calendar is a second interface, not a
   second product, so it inherits all five themes for free — and would break
   every one of them the moment a raw hex appeared here.
   ========================================================================= */

/* ── The workspace switch ───────────────────────────────────────────────── */

.ws-switch {
  display: flex;
  gap: 2px;
  padding: var(--space-2);
  margin: 0 var(--space-2) var(--space-2);
  background: var(--surface-2);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
}

.ws-btn {
  flex: 1 1 0;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 7px 6px;
  border: 0;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--text-muted);
  font-family: var(--f-mono);
  font-size: var(--fs-tiny);
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  cursor: pointer;
  transition: background var(--dur-fast) var(--easing), color var(--dur-fast) var(--easing);
}
.ws-btn:hover { color: var(--text-main); }
.ws-btn[aria-pressed='true'] {
  background: var(--surface-raised);
  color: var(--text-main);
  box-shadow: inset 0 0 0 1px var(--border-strong);
}
.ws-btn svg { flex: 0 0 auto; }

/* Which stage is on screen. The timeline is hidden rather than unmounted, so
   the viewport, the selection and the render caches survive a switch. */
body[data-workspace='calendar'] #canvas-frame,
body[data-workspace='calendar'] #minimap,
body[data-workspace='calendar'] #legend { display: none; }

body[data-workspace='calendar'] #rc-frame { display: flex; }

/* The toolbar, the dock and the pane list all belong to the timeline. Rather
   than teach every control about modes, the ones that only mean something over
   a canvas are dropped wholesale.

   The pane links matter as much as the dock itself: leaving them visible would
   offer Lanes and Baselines while the panel they open is hidden, so a click
   would appear to do nothing at all. */
body[data-workspace='calendar'] #dock,
body[data-workspace='calendar'] #inspector,
body[data-workspace='calendar'] .sidenav-links,
body[data-workspace='calendar'] .tb-timeline,
/* Separators between groups that have gone would otherwise be left floating
   in an empty toolbar. */
body[data-workspace='calendar'] .tb-sep { display: none; }

/* Which leaves the switch at the top and the project tag at the bottom, so the
   sidebar still says where you are and how to get back. */
body[data-workspace='calendar'] .ws-switch { margin-bottom: auto; }

/* ── The stage ──────────────────────────────────────────────────────────── */

#rc-frame {
  flex: 1 1 auto;
  min-width: 0;
  display: none;
  flex-direction: column;
  overflow: hidden;
  background: var(--surface);
}
.rc-table th {
  text-align: left;
  padding: 8px 10px;
  border-bottom: 1px solid var(--border-strong);
  font-family: var(--f-mono);
  font-size: var(--fs-tiny);
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--text-muted);
  white-space: nowrap;
}
.rc-table td {
  padding: 8px 10px;
  border-bottom: 1px solid var(--border);
  color: var(--text-main);
  vertical-align: middle;
}

/* ── The look-ahead grid ────────────────────────────────────────────────
   Activities down, calendar days across — the shape of the workbook itself,
   because somebody reading this has the spreadsheet open beside it and the two
   have to be recognisably the same thing.

   The left columns stay put while the days scroll. A hundred-odd days do not
   fit on any screen, and a mark with its activity scrolled off the side is not
   evidence of anything. */

.la-grid {
  border-collapse: separate;
  border-spacing: 0;
  font-size: var(--fs-tiny);
}
.la-grid th,
.la-grid td {
  border-right: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
  padding: 4px 6px;
  white-space: nowrap;
}

/* The frozen side. `left` is set inline per column, because the widths are the
   content's and only the browser knows them. */
.la-grid .la-meta {
  position: sticky;
  z-index: 2;
  background: var(--surface);
  text-align: left;
  max-width: 260px;
}
.la-grid thead .la-meta { z-index: 4; }
/* The frozen body cells rule their edges with shadows, not borders. A sticky
   cell's border is see-through in this table — transparent or not — so the
   days scrolling under it showed along every edge: a band's hatch, an unmapped
   cell's outline, a shift's colour, in hairlines down the activity columns.
   A shadow is painted on the cell itself. Each edge is its own property, so a
   row kind changes one edge and the hover bar (`--la-mark`) adds to them. */
.la-grid tbody .la-meta {
  border-right-width: 0;
  border-bottom-width: 0;
  --la-mark: 0 0 transparent;
  --la-rule-t: 0 0 transparent;
  --la-rule-r: inset -1px 0 0 var(--border);
  --la-rule-b: inset 0 -1px 0 var(--border);
  box-shadow: var(--la-mark), var(--la-rule-t), var(--la-rule-r), var(--la-rule-b);
}
/* The body wraps, as the editor's does: an activity's description and a day's
   names are read whole, and the row grows to hold them. A day column stops
   widening at a readable measure and wraps the names inside it instead. */
.la-grid tbody td {
  white-space: normal;
  overflow-wrap: break-word;
  line-height: 1.3;
}
/* A floor as well as a ceiling. Without the floor, "Everything" — seven weeks
   of columns — let the browser squeeze a day down to one letter and spell the
   names down the cell. `break-word` keeps a name whole unless it alone is
   wider than the column. */
.la-grid tbody td.la-day { min-width: 58px; max-width: 110px; }
/* The names the workbook gives its own left-hand columns — Location, SSWP,
   Party to action, and whatever else that sheet carries. They sit in the day-
   number row, one per column, so they have to take the header's background
   rather than the body's: `.la-meta` is the more specific selector and would
   otherwise leave them the colour of the rows underneath. */
.la-grid thead .la-meta-head {
  background: var(--surface-2);
  color: var(--text-main);
  vertical-align: bottom;
}
.la-grid .la-meta.la-last { border-right: 2px solid var(--border-strong); }
.la-grid tbody .la-meta.la-last { border-right-width: 0; --la-rule-r: inset -2px 0 0 var(--border-strong); }

.la-grid thead th {
  position: sticky;
  top: 0;
  z-index: 3;
  background: var(--surface-2);
  font-family: var(--f-mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--text-muted);
  text-align: center;
}
.la-grid thead th.la-month {
  text-align: left;
  border-bottom: none;
  color: var(--text-main);
}
.la-grid thead th.la-weekend { color: var(--text-faint); }

.la-day {
  text-align: center;
  min-width: 26px;
  font-family: var(--f-mono);
  font-size: 10px;
  color: var(--text-main);
}
/* Weekends are grey on every row, always — fixed shading, as on the sheet,
   never a colour from the legend and never in the key. A day painted with a
   shift carries its colour inline, which covers the grey; clear the shift and
   the grey is back. */
.la-grid tbody td.la-day.la-weekend:not(.la-painted) { background-color: var(--la-weekend); color: var(--la-weekend-ink); }
/* A painted cell states its own colour, so the text has to stay legible over
   whatever that turns out to be rather than over a token we chose. */
.la-day.la-painted { color: #111; font-weight: 700; }
.la-day.la-painted.la-dark { color: #fff; }
/* A colour the legend does not know is drawn with a hatch over it, so an
   unmapped shift is visible on the grid rather than only in a count. */
.la-day.la-unmapped {
  background-image: repeating-linear-gradient(
    45deg, transparent 0 3px, rgba(0, 0, 0, 0.45) 3px 5px);
  box-shadow: inset 0 0 0 2px var(--warn);
}

.la-swatch {
  display: inline-block;
  width: 14px;
  height: 14px;
  border-radius: 3px;
  border: 1px solid var(--border-strong);
  vertical-align: -3px;
  margin-right: 6px;
}
.la-legend {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2) var(--space-4);
  align-items: center;
  margin-bottom: var(--space-3);
  font-size: var(--fs-tiny);
  color: var(--text-muted);
}

/* A section heading in the workbook: the row whose activity cells are painted.
   It titles the rows under it, so it reads as a title rather than as work. */
.la-grid tr.la-head-row .la-meta {
  font-size: var(--fs-small);
  font-weight: 700;
  letter-spacing: 0.01em;
  border-top: 2px solid var(--border-strong);
}
.la-grid tr.la-head-row .la-day { border-top: 2px solid var(--border-strong); }
.la-grid tbody tr.la-head-row .la-meta { border-top-width: 0; --la-rule-t: inset 0 2px 0 var(--border-strong); }
/* A section band runs the whole width of the calendar, the activity columns
   and every day, so the rows under it read as one group — the band BART's
   sheet draws and the export writes. Fixed shading, like the weekends, which
   still show through it as they do on the sheet. */
.la-grid tbody tr.la-head-row > td { background-color: var(--la-band); color: var(--la-band-ink); }
.la-grid tbody tr.la-head-row > td.la-day.la-weekend { background-color: var(--la-weekend); }

/* The Resource row the workbook writes under an activity: who is on it.
   Drawn as a continuation of the line above rather than as a row of its own —
   no top border, lighter type, the description set in italics — because that is
   what it is. Its location and hours are inherited, and reading it as a
   separate activity is exactly the mistake to design against. */
.la-grid tr.la-resource-row > td {
  border-top: none;
  border-bottom: 1px solid var(--border-strong);
}
.la-grid tr.la-resource-row .la-meta {
  font-style: italic;
  color: var(--text-muted);
}
.la-grid tbody tr.la-resource-row > td.la-meta { border-bottom-width: 0; --la-rule-b: inset 0 -1px 0 var(--border-strong); }
/* "PTO" and "Other Group / Project" stand on their own rather than under an
   activity, so unlike the Resource row they get their top border back — a row
   about a person is not a continuation of the line above it, and drawn as one it
   would look like the previous activity's crew. */
.la-grid tr.la-absence-row > td {
  border-top: 1px solid var(--border);
}
.la-grid tr.la-absence-row .la-meta {
  font-style: normal;
  font-weight: 600;
  color: var(--text-muted);
}
.la-grid tbody tr.la-absence-row > td.la-meta { border-top-width: 0; --la-rule-t: inset 0 1px 0 var(--border); }

/* The names are words, not marks, so they get the text face and room to be
   read — a mono 10px column of "R. Okafor" is not legible at any zoom. */
.la-grid td.la-resource {
  font-family: var(--f-ui);
  font-size: var(--fs-tiny);
  font-weight: 500;
  letter-spacing: 0;
}

/* ── Today, and the month band ──────────────────────────────────────────── */

/* Today is a line down the grid rather than a tinted cell: a fill would be one
   more colour competing with the workbook's own, and the whole point of this
   view is that the colours are BART's. */
.la-grid .la-today { border-left: 2px solid var(--accent, #e60012); }
/* The body's cells only. On a heading this outranked `position: sticky`, so
   today's day number and weekday scrolled away with the rows — and the offset
   that pins each header row was read as a nudge, drawing them over the rows
   below. */
.la-grid td.la-today { position: relative; }
.la-grid thead th.la-today { color: var(--accent, #e60012); }

/* The month band is its own row with its own weight, and the label inside it
   is sticky: a month spans thirty columns, so the label scrolls away long
   before the month does. Pinned just past the frozen activity columns, it
   stays legible the whole way across. */
.la-grid thead th.la-month {
  background: var(--surface-3, var(--surface-2));
  border-bottom: 1px solid var(--border-strong);
  overflow: visible;
  padding: 6px;
}
.la-month-label {
  position: sticky;
  left: var(--la-meta-w, 0px);
  display: inline-block;
  padding: 2px 8px;
  border-radius: var(--radius-sm, 4px);
  background: var(--surface-3, var(--surface-2));
  font-family: var(--f-mono);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.1em;
  color: var(--text-main);
  white-space: nowrap;
}
.la-grid thead th.la-num { font-size: 11px; color: var(--text-main); }

/* An unexplained colour, in the strip above the grid. Hatched like the cells
   it paints, so the two read as the same thing. */
.la-unknown { display: inline-flex; align-items: center; gap: 4px; }
.la-swatch-unmapped {
  background-image: repeating-linear-gradient(
    45deg, transparent 0 3px, rgba(0, 0, 0, 0.45) 3px 5px);
  box-shadow: inset 0 0 0 2px var(--warn);
  margin-right: 0;
}

/* ── On a tablet, standing up ───────────────────────────────────────────────
   The huddle is run at a fixed time with the team in front of you, and the
   device in your hand is as likely to be a tablet as a laptop. Nothing here
   changes what the calendar *is* — the tables still say the same things — it
   is the chrome that has to stop assuming a wide screen.

   No layout below is invented for a phone. The week plan is seven columns of
   assignments and the look-ahead is a hundred days wide; both scroll inside
   their own frame already, and pretending they fit a 380px screen would be a
   worse answer than letting them scroll. */



/* A cancelled day is struck through as well as red, so it reads the same to
   somebody who cannot tell red from the other shift colours. The line takes
   the text colour the cell already chose for legibility over its paint. */
.la-day.la-cancel {
  background-image: linear-gradient(
    to top right, transparent calc(50% - 1px), currentColor calc(50% - 1px),
    currentColor calc(50% + 1px), transparent calc(50% + 1px));
}

/* ── A tablet in the room ────────────────────────────────────────────────
   The huddle is run standing, on a tablet held in one hand, and a tablet in
   landscape is wider than the 900px where the narrow rules begin — so none of
   them applied to the device the meeting is most often run on. Touch is the
   test here, not width: every control in the calendar reaches 44px, the size
   a thumb hits without looking, and in landscape the meeting splits into the
   question on the left and the answer on the right, so answering never means
   scrolling past the question to find the buttons. */


/* A BART resource cancelled while the activity went ahead ("X.~WIT"): the
   code stays where it was, struck through in red, so the day still says what
   was asked for and what was taken off. Over a painted day the red is the
   brand's own, which reads on the legend's light fills where the theme's
   softer status red does not. */
.lae-code-cancelled,
.la-code-cancelled,
.rc-code-cancelled {
  color: var(--bad);
  text-decoration: line-through;
  text-decoration-thickness: 2px;
  font-weight: 700;
}
.lae-grid td.lae-painted .lae-code-cancelled,
.la-grid td.la-painted .la-code-cancelled,
.lae-grid td.lae-weekend .lae-code-cancelled,
.la-grid td.la-weekend .la-code-cancelled { color: var(--hitachi-red); }
.lae-grid td.lae-painted.lae-dark .lae-code-cancelled,
.la-grid td.la-painted.la-dark .la-code-cancelled { color: var(--surface); background: var(--hitachi-red); padding: 0 2px; }

/* ── Only my rows ─────────────────────────────────────────────────────────
   Your own name on a names row: outlined in the primary colour and bold, so
   it reads without the colour too. */
.la-grid td.la-mine {
  box-shadow: inset 0 0 0 2px var(--primary);
  font-weight: 700;
  color: var(--text-main);
}
.la-only-mine { font-weight: 600; }
/* Back, this week, forward — the editor's pager, on the read view. */
.la-pager { display: flex; align-items: center; gap: 4px; }
.la-pager-range {
  font-family: var(--f-mono);
  font-size: var(--fs-tiny);
  font-weight: 700;
  letter-spacing: 0.04em;
  color: var(--text-main);
  padding: 0 6px;
  white-space: nowrap;
}
.la-written-note, .la-reading-note, .lae-before-note { margin: 0 0 4px; }
/* Where one source of the calendar hands over to the next — a workbook
   reading to the next, or to the look-ahead as written — on the one grid. */
.la-grid th.la-source-start,
.la-grid td.la-source-start { box-shadow: inset 2px 0 0 var(--info); }
/* The calendar narrowed to the one row "Show cells" opened, and the way back. */
.la-pinned {
  display: flex;
  gap: 10px;
  align-items: center;
  flex-wrap: wrap;
  margin: 0 0 8px;
  padding: 6px 10px;
  border: 1px solid var(--info-border);
  border-radius: 8px;
  background: var(--info-light);
  color: var(--text-main);
  font-size: var(--fs-small);
}
/* A reason given instead of a P6 activity reads as a word, not an ID. */
.la-grid td.la-p6-flag { font-style: italic; color: var(--text-muted); }
/* The row under the pointer, marked without repainting anything: a bar down
   the first frozen column, so a day far to the right can be read back to its
   activity. Every colour on the grid is the workbook's — a shift, a band, a
   weekend, a hatch — and a hover fill would be one more, drawn over them. */
.la-grid tbody tr:hover > td.la-meta:first-child { --la-mark: inset 3px 0 0 var(--primary); }
.la-grid tbody tr:hover > td:first-child:not(.la-meta) { box-shadow: inset 3px 0 0 var(--primary); }
.la-grid td.la-openable { cursor: pointer; }
.la-grid td.la-openable:hover { text-decoration: underline; text-underline-offset: 3px; }
.la-grid td.la-openable:focus-visible { outline: 2px solid var(--primary); outline-offset: -2px; }

/* ── The cancellation log as a calendar ──────────────────────────────────
   One row per activity, each cancelled run one cell across its days with who
   and why written in it. The colour is whose it was — BART red, Hitachi blue,
   another party amber, and lavender in a dashed purple outline while nobody
   has said — filled for a day cancelled outright, and as the outline and the
   writing for a BART resource struck out of work that went ahead. */
.la-cancel-grid .la-cancel-meta {
  text-align: left;
  min-width: 90px;
  max-width: 260px;
  vertical-align: top;
}
.la-cancel-grid tbody .la-cancel-meta:first-child { min-width: 200px; font-weight: 500; }
.la-cancel-grid .la-cancel-run {
  white-space: pre-line;
  text-align: center;
  vertical-align: middle;
  font-family: var(--f-ui);
  font-size: var(--fs-tiny);
  line-height: 1.3;
}
.la-cancel-grid tbody td.la-day.la-cancel-run { min-width: 120px; max-width: none; }
.la-cancel-grid tbody td.la-cancel-run-activity.la-cancel-by-hitachi { background-color: var(--la-cancel-hitachi); color: var(--la-cancel-hitachi-ink); font-weight: 700; }
.la-cancel-grid tbody td.la-cancel-run-activity.la-cancel-by-other { background-color: var(--la-cancel-other); color: var(--la-cancel-other-ink); font-weight: 700; }
.la-cancel-grid tbody td.la-cancel-run-activity.la-cancel-open {
  background-color: var(--la-cancel-open);
  color: var(--la-cancel-open-ink);
  outline: 2px dashed var(--pending);
  outline-offset: -2px;
}
.la-cancel-grid .la-cancel-run-support { --cancel-ink: var(--bad); box-shadow: inset 0 0 0 2px var(--cancel-ink); color: var(--text-main); }
.la-cancel-grid .la-cancel-run-support.la-cancel-by-hitachi { --cancel-ink: var(--info); }
.la-cancel-grid .la-cancel-run-support.la-cancel-by-other { --cancel-ink: var(--warn); }
.la-cancel-grid .la-cancel-run-support.la-cancel-open { --cancel-ink: var(--pending); box-shadow: none; outline: 2px dashed var(--cancel-ink); outline-offset: -2px; }
.la-cancel-grid .la-cancel-run-support .la-code-cancelled,
.la-cancel-grid .la-cancel-run-support .la-cancel-why { color: var(--cancel-ink); }
/* The key over the calendar: a swatch per answer, drawn as the cells are. */
.la-cancel-key { display: flex; gap: 6px 14px; flex-wrap: wrap; align-items: center; margin: 0 0 10px; font-size: var(--fs-tiny); }
.la-cancel-key-item { display: inline-flex; gap: 6px; align-items: center; }
.la-cancel-swatch { width: 16px; height: 12px; border-radius: 2px; flex: 0 0 auto; }
.la-cancel-swatch.la-cancel-by-hitachi { background-color: var(--la-cancel-hitachi); }
.la-cancel-swatch.la-cancel-by-other { background-color: var(--la-cancel-other); }
.la-cancel-swatch.la-cancel-open { background-color: var(--la-cancel-open); outline: 2px dashed var(--pending); outline-offset: -2px; }
.la-cancel-swatch.la-cancel-support { box-shadow: inset 0 0 0 2px var(--text-muted); }
.la-cancel-grid .la-cancel-why { font-weight: 600; }
.la-cancel-grid .la-cancel-run.la-cancel-open { font-style: italic; }

/* css/rc.css */
/* ============================================================================
   CX Timeline — Resource Calendar
   Roster · huddle · week · PTO · reports · the look-ahead and its editor

   Fetched with calendar.bundle.js the first time the calendar opens
   (ui/calendar_loader.js), and linked directly by the phone app and the
   desktop shell, which carry the calendar from the start. Every rule here
   matches only what the calendar bundle builds; anything the main page can
   draw is in calendar.css, which loads first. Before adding a rule here that
   ties with one in calendar.css, read the header there: this file loads
   later, so it wins every tie.

   Every colour goes through a token, as everywhere else.
   ========================================================================= */

.rc-head {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  gap: var(--space-3);
  padding: var(--space-3) var(--space-4);
  border-bottom: 1px solid var(--border);
  background: var(--chrome-bg);
}

.rc-eyebrow {
  font-family: var(--f-mono);
  font-size: var(--fs-tiny);
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--text-muted);
}

.rc-tabs {
  display: flex;
  gap: 2px;
  margin-left: auto;
}

.rc-tab {
  padding: 6px 12px;
  border: 0;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--text-muted);
  font-size: var(--fs-small);
  font-weight: 600;
  cursor: pointer;
  transition: background var(--dur-fast) var(--easing), color var(--dur-fast) var(--easing);
}
.rc-tab:hover { color: var(--text-main); background: var(--surface-2); }
.rc-tab[aria-pressed='true'] { background: var(--surface-3); color: var(--text-main); }

.rc-body {
  flex: 1 1 auto;
  min-height: 0;
  overflow: auto;
  padding: var(--space-4);
}

/* ── States that are not the calendar ───────────────────────────────────── */

.rc-state {
  max-width: 460px;
  margin: 10vh auto 0;
  text-align: center;
}
.rc-state .rc-state-icon {
  /* Centred as a box: base.css makes every svg a block, which text-align
     leaves on the left. */
  display: flex;
  justify-content: center;
  color: var(--text-muted);
  opacity: 0.5;
  margin-bottom: var(--space-3);
}
.rc-state h2 {
  font-family: var(--f-display);
  font-size: 17px;
  font-weight: 700;
  color: var(--text-main);
  margin: 0 0 var(--space-2);
}
.rc-state p {
  font-size: var(--fs-small);
  line-height: 1.6;
  color: var(--text-muted);
  margin: 0 0 var(--space-4);
}

.rc-signin {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
  text-align: left;
  padding: var(--space-4);
  background: var(--surface-2);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
}
.rc-error {
  font-size: var(--fs-small);
  color: var(--bad);
  background: var(--bad-light);
  border: 1px solid var(--bad-border);
  border-radius: var(--radius-sm);
  padding: var(--space-2) var(--space-3);
}

/* ── The offline queue ──────────────────────────────────────────────────── */

/* The huddle is at a fixed time whether or not the network is up, so entries
   queue locally. That has to be visible without being alarming — nothing is
   lost, it simply has not gone yet. */
.rc-queue {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 3px 9px;
  border-radius: 999px;
  background: var(--warn-light);
  border: 1px solid var(--warn-border);
  color: var(--warn);
  font-family: var(--f-mono);
  font-size: var(--fs-tiny);
  font-weight: 600;
}
.rc-queue[hidden] { display: none; }

/* ── Tables ─────────────────────────────────────────────────────────────── */

.rc-table {
  width: 100%;
  border-collapse: collapse;
  font-size: var(--fs-small);
}
/* Not the PTO grid: there the cell *is* its colour, and a hover fill painted
   over every cell in the row turned a person's leave white the moment the
   pointer crossed it. That grid highlights the name cell instead.
   Nor the look-ahead, for the same reason: the fill outranked the section
   band, so a heading went dark under its own dark ink, and the shorthand reset
   `background-image`, so a cancelled day lost its strike and an unmapped colour
   its hatch while the pointer was on them. It marks the row its own way
   (calendar.css). */
.rc-table:not(.rc-pto-grid):not(.la-grid) tbody tr:hover td { background: var(--surface-2); }
.rc-pto-grid tbody tr:hover td.rc-pto-name { background: var(--surface-2); }
.rc-table .rc-num { text-align: right; font-family: var(--f-mono); }
.rc-table .rc-inactive td { opacity: 0.45; }
/* Reports: every value sits centred under its own heading. The headings were
   left-aligned and the numbers right-aligned, so a column's figures sat under
   the gap between two headings and the table read as out of line. The first
   column is the name the row is about, and stays left. */
.rc-table.rc-report th:not(:first-child),
.rc-table.rc-report td:not(:first-child) { text-align: center; }

/* A wide table scrolls inside its own frame; the page never scrolls sideways. */
.rc-scroll {
  overflow-x: auto;
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  background: var(--surface-2);
}

.rc-section {
  margin-bottom: var(--space-5);
}
.rc-section-head {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  margin-bottom: var(--space-3);
}
.rc-section-head h3 {
  font-family: var(--f-display);
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.02em;
  color: var(--text-main);
  margin: 0;
}
.rc-section-head .cx-btn { margin-left: auto; }
/* A head with several actions keeps them together at the right, in the order
   written, rather than each pushing itself away from the last. */
.rc-section-actions {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--space-2);
  margin-left: auto;
}
.rc-section-head .rc-section-actions .cx-btn { margin-left: 0; }

.rc-hint {
  font-size: var(--fs-tiny);
  line-height: 1.6;
  color: var(--text-muted);
  margin: var(--space-2) 0 0;
}

/* The huddle runs from the keyboard, so the row that has focus has to be
   obvious — you are looking at the team, not at the cursor. */
.rc-huddle-row:focus { outline: none; }
.rc-huddle-row:focus-visible,
.rc-huddle-row:focus { box-shadow: inset 3px 0 0 var(--accent, #e60012); background: var(--surface-2); }

/* A planned day can be revised, so it has to look like it can be. */
.rc-table td.rc-clickable { cursor: pointer; }
.rc-table td.rc-clickable:hover { background: var(--surface-3, var(--surface-2)); }

@media (max-width: 900px) {
  /* The tab row stops fighting the eyebrow for the same line. */
  .rc-head {
    flex-wrap: wrap;
    gap: var(--space-2);
    padding: var(--space-2) var(--space-3);
  }
  .rc-tabs {
    margin-left: 0;
    width: 100%;
    overflow-x: auto;
    /* A row of tabs that scrolls has to look like it does. */
    scrollbar-width: thin;
    padding-bottom: 2px;
  }
  .rc-tab { flex: 0 0 auto; }

  .rc-body { padding: var(--space-3); }

  /* Touch targets. A 20px button is a miss when somebody is holding the
     tablet in the other hand, and the huddle is one button per person. */
  .rc-table .cx-btn.mini {
    min-height: 34px;
    padding-inline: 12px;
  }
  .rc-table td, .rc-table th { padding: 10px 8px; }

  /* The section heads stack rather than squeezing the action off the edge. */
  .rc-section-head { flex-wrap: wrap; }
  .rc-section-head .cx-btn { margin-left: 0; }
  .rc-section-actions { margin-left: 0; }
}

@media (max-width: 620px) {
  /* The huddle is the one screen worth reshaping: four columns of prose do
     not fit, and the meeting still has to be run. Each person becomes a card
     — their name, what was planned, and the buttons — which is the same
     information in the order it is asked for. */
  .rc-table.rc-huddle { display: block; }
  .rc-table.rc-huddle thead { display: none; }
  .rc-table.rc-huddle tbody,
  .rc-table.rc-huddle tr { display: block; }
  .rc-table.rc-huddle tr {
    border: 1px solid var(--border);
    border-radius: var(--radius-md);
    margin-bottom: var(--space-3);
    padding: var(--space-2);
    background: var(--surface);
  }
  .rc-table.rc-huddle td {
    display: block;
    border: 0;
    padding: 4px 2px;
  }
  /* The label the header row would have carried, on the cell itself. */
  .rc-table.rc-huddle td::before {
    content: attr(data-label);
    display: block;
    font-family: var(--f-mono);
    font-size: 10px;
    font-weight: 700;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--text-faint);
    margin-bottom: 2px;
  }
  .rc-table.rc-huddle td:first-child::before { content: none; }
  .rc-table.rc-huddle td:first-child { font-weight: 700; font-size: var(--fs-small); }
}

/* ── What is still in the way ────────────────────────────────────────────
   Above the meeting rather than inside it: these are the items the huddle
   keeps returning to, and they stay until somebody closes one. */
.rc-blockers { margin-bottom: var(--space-4); }
.rc-blocker {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  padding: 8px 10px;
  border: 1px solid var(--border);
  border-left: 3px solid var(--warn);
  border-radius: var(--radius-md);
  background: var(--surface-2);
  margin-bottom: 6px;
}
.rc-blocker.overdue { border-left-color: var(--bad); }
.rc-blocker-main { flex: 1 1 auto; min-width: 0; }
.rc-blocker-what { font-weight: 600; font-size: var(--fs-small); color: var(--text-main); }
.rc-blocker-state { display: flex; gap: 4px; flex-wrap: wrap; flex: 0 0 auto; }

@media (max-width: 620px) {
  .rc-blocker { flex-wrap: wrap; }
  .rc-blocker-main { flex-basis: 100%; }
}

/* ── Saying what is left, on the way to recording it ─────────────────────
   The strip that replaces the status buttons for anything but a completed
   task. It has to fit where the buttons were — a table cell in one place and
   a presenter panel in the other — so it wraps rather than fixing a width. */
.rc-saymore {
  display: flex;
  align-items: center;
  gap: 4px;
  flex-wrap: wrap;
}
.rc-saymore .cx-input { min-width: 140px; flex: 1 1 160px; }
.rc-saymore-clip {
  position: relative;
  overflow: hidden;
  display: inline-flex;
  align-items: center;
  cursor: pointer;
}
/* The real control, kept where a click and a screen reader both find it and
   the eye does not. `display: none` would take it out of the tab order. */
.rc-saymore-photo {
  position: absolute;
  inset: 0;
  opacity: 0;
  cursor: pointer;
}
.rc-saymore-clip:has(.rc-saymore-photo:focus-visible) { outline: 2px solid var(--accent); }

/* A photograph that was attached, on the outcome it belongs to. */
.rc-evidence {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  margin-top: 3px;
}

/* ── The meeting, run rather than filled in ──────────────────────────────
   One person, in focus, readable from the other side of a table. Everything
   here is sized for the room rather than for the person holding the keyboard —
   the table is still there for that, one Escape away. */
.rc-present {
  max-width: 760px;
  margin: 0 auto;
  padding: var(--space-4) var(--space-3) var(--space-5);
  outline: none;
}
.rc-present-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: var(--space-4);
}
.rc-present-who {
  font-family: var(--f-display);
  font-size: 34px;
  font-weight: 700;
  letter-spacing: -0.01em;
  color: var(--text-main);
  margin: 0;
}
/* The question, in the words somebody would actually say. */
.rc-present-ask {
  font-size: 19px;
  line-height: 1.45;
  color: var(--text-main);
  margin: var(--space-4) 0 var(--space-3);
}
/* What the room needs, which is not what the person answering needs. */
.rc-present-context {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-bottom: var(--space-4);
}
.rc-present-answer {
  padding: var(--space-3) 0;
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
}
/* A status is one press per person, so it has to be a target you cannot miss
   from standing. */
.rc-present-answer .cx-btn {
  min-height: 44px;
  padding-inline: 18px;
  font-size: var(--fs-small);
}
.rc-present-next { margin: var(--space-4) 0; }
.rc-present-move {
  display: flex;
  gap: var(--space-2);
  justify-content: flex-end;
}
.rc-present-move .cx-btn { min-height: 40px; padding-inline: 20px; }

@media (max-width: 620px) {
  .rc-present-who { font-size: 26px; }
  .rc-present-ask { font-size: 17px; }
  .rc-present-move { justify-content: stretch; }
  .rc-present-move .cx-btn { flex: 1; }
}

/* ── Resources: who is where ─────────────────────────────────────────────
   People down, days across, and two things in each cell rather than one: what
   the plan says, and what the 4WLA asked for. The interesting case is the two
   disagreeing, so a layout that could only show one of them would hide the
   whole point of the view. */

.rc-table.rc-resources td { vertical-align: top; }
.rc-table.rc-resources th,
.rc-table.rc-resources td { min-width: 132px; }
.rc-table.rc-resources th:first-child,
.rc-table.rc-resources td:first-child { min-width: 150px; }

.rc-res-cell { font-size: var(--fs-tiny); }

/* ── Today ───────────────────────────────────────────────────────────────
   A week grid is read by running a finger down a day, and the day somebody is
   nearly always looking for is this one. It used to be a two-pixel rule on the
   left edge of the cells, which is invisible in a table that has borders
   anyway — so the whole column is tinted and the heading says the word. The
   tint is `--info-light`, a wash rather than a colour: the cells carry status
   badges and an outcome of their own, and anything stronger would compete with
   the content it is supposed to be pointing at. */
.rc-res-today,
/* …and it survives the row hover.
   `.rc-table tbody tr:hover td` is the more specific selector, so crossing a
   row with the pointer painted `--surface-2` straight over today's column and
   the one thing the reader was following disappeared. The PTO grid learnt this
   the same way, with somebody's leave turning white under the cursor. */
.rc-table.rc-resources tbody tr:hover td.rc-res-today {
  background: var(--info-light);
  box-shadow: inset 2px 0 0 var(--info), inset -2px 0 0 var(--info);
}
.rc-res-today-head { color: var(--info); }

/* ── The weekend ─────────────────────────────────────────────────────────
   Every week shows all seven days, and Saturday and Sunday are shaded down the
   whole column — the look-ahead's weekend grey, washed so the badges and tasks
   on a possession weekend stay readable. Today's tint wins on the day it is a
   weekend, because that is the column somebody is following. */
.rc-table.rc-resources td.rc-res-weekend:not(.rc-res-today),
.rc-table.rc-resources tbody tr:hover td.rc-res-weekend:not(.rc-res-today) {
  background: color-mix(in srgb, var(--la-weekend) 32%, transparent);
}
.rc-table.rc-resources th.rc-res-weekend:not(.rc-res-today) {
  background: color-mix(in srgb, var(--la-weekend) 45%, var(--surface-2));
  color: var(--text-main);
}

/* Back, the week, forward: one group, held together. */
.rc-week-nav {
  display: inline-flex;
  align-items: center;
  gap: var(--space-1, 4px);
}
.rc-week-nav h3 { padding: 0 var(--space-1, 4px); white-space: nowrap; }
.rc-section-head .rc-week-nav .cx-btn { margin-left: 0; }
.rc-section-head .rc-week-nav + .cx-btn { margin-left: auto; }
.rc-today-tag {
  display: block;
  font-family: var(--f-mono);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--info);
}

/* The bottom row: how many people can actually be staffed. Set apart from the
   people above it, because it is about the day rather than about anybody. */
.rc-res-coverage td {
  border-top: 2px solid var(--border-strong);
  font-size: var(--fs-tiny);
  color: var(--text-muted);
  vertical-align: middle;
}

/* ── One task ───────────────────────────────────────────────────────────── */

.rc-res-job {
  margin-bottom: 6px;
  padding-left: 6px;
  border-left: 2px solid var(--border);
}
.rc-res-task { font-weight: 500; color: var(--text-main); }
.rc-res-flags { display: flex; flex-wrap: wrap; gap: 3px; }
.rc-res-flags:empty { display: none; }
/* The actions are the least interesting thing in a cell that already carries a
   task, a place, its flags and how it went — so they are icons, and quiet until
   the cell is under the pointer or one of them has focus. Never *hidden*: a
   touch screen has no hover, and this calendar is used standing up. */
.rc-res-acts { display: flex; flex-wrap: wrap; gap: 2px; margin-top: 3px; }
.rc-res-acts .cx-btn { opacity: 0.45; padding: 2px 4px; }
.rc-res-cell:hover .rc-res-acts .cx-btn,
.rc-res-acts .cx-btn:focus-visible,
.rc-res-acts .cx-btn:hover { opacity: 1; }

/* A day the huddle has already answered, coloured by the answer.
   The left edge carries it rather than a fill: a fill on a cell that may hold
   three tasks would say the whole day went that way. Completed is deliberately
   quiet — the interesting cells are the ones that are not. */
.rc-res-done.rc-res-completed  { border-left-color: var(--good); }
.rc-res-done.rc-res-partial,
.rc-res-done.rc-res-carried    { border-left-color: var(--warn); }
.rc-res-done.rc-res-blocked    { border-left-color: var(--bad); }
.rc-res-done.rc-res-reassigned { border-left-color: var(--info); }
.rc-res-done.rc-res-absent     { border-left-color: var(--text-faint); }

/* A day off asked for and not answered. Set apart from the tasks above it,
   because it is about the person rather than about the work — and it is a
   question rather than a state, which is why it is not drawn as leave. */
.rc-res-asked-off { margin-top: 4px; }

/* What was said about it in the meeting. Recorded elsewhere and read here, so
   it is set back from the plan above it rather than dressed as another field. */
.rc-res-outcome {
  margin-top: 4px;
  padding-top: 3px;
  border-top: 1px dotted var(--border);
  display: flex;
  flex-direction: column;
  gap: 2px;
  align-items: flex-start;
}
.rc-res-outcome .rc-eyebrow { font-size: 9px; letter-spacing: 0.1em; }

/* A day on another group's project is work, and it is not this project's —
   set back rather than badged, because it is one of several things in a cell. */
.rc-res-job.rc-res-away { color: var(--text-muted); font-style: italic; }

/* A day the 4WLA called off. Still drawn — somebody was going to be there —
   but struck through and edged in red, beside a "Cancelled" badge that says it
   in words. */
.rc-res-job.rc-res-cancelled { border-left-color: var(--bad); }
.rc-res-job.rc-res-cancelled .rc-res-task {
  color: var(--text-muted);
  text-decoration: line-through;
}

/* What BART asked for, set apart from what was decided. Bordered rather than
   tinted, because a tint would read as a status. */
.rc-res-asked {
  border: 1px dashed var(--warn);
  border-radius: var(--radius-sm, 4px);
  padding: 3px 5px;
  margin-bottom: 4px;
}
/* Agreeing is the quiet case, so it stops shouting: the plan is against this
   very row and there is nothing to reconcile. */
.rc-res-asked.agrees {
  border-style: solid;
  border-color: var(--border);
  color: var(--text-muted);
}
.rc-res-asked .rc-eyebrow { display: block; margin-bottom: 1px; }

@media (max-width: 620px) {
  /* Seven columns of prose do not fit, and unlike the look-ahead grid this one
     is a week rather than a hundred days — so it stacks into a card per person,
     the way the huddle does, with the day name on each cell. */
  .rc-table.rc-resources { display: block; }
  .rc-table.rc-resources thead { display: none; }
  .rc-table.rc-resources tbody,
  .rc-table.rc-resources tr { display: block; }
  .rc-table.rc-resources tr {
    border: 1px solid var(--border);
    border-radius: var(--radius-md);
    margin-bottom: var(--space-3);
    padding: var(--space-2);
    background: var(--surface);
  }
  .rc-table.rc-resources td {
    display: block;
    border: 0;
    padding: 4px 2px;
    min-width: 0;
  }
  .rc-table.rc-resources td::before {
    content: attr(data-label);
    display: block;
    font-family: var(--f-mono);
    font-size: 10px;
    font-weight: 700;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--text-faint);
    margin-bottom: 2px;
  }
  .rc-table.rc-resources td:first-child::before { content: none; }
  .rc-table.rc-resources td:first-child { font-weight: 700; font-size: var(--fs-small); }
}

/* Two tasks on one day, told apart without a heavy rule: a shift is often more
   than one job, and they have to read as separate things rather than as one
   description that wrapped. */
.rc-day-rule { border-top: 1px dashed var(--border); margin: 5px 0; }
.rc-day-next { margin-top: 6px; padding-top: 5px; border-top: 1px dashed var(--border); }

/* A hint that is a warning rather than an aside — the export dialog saying the
   print will come out too small to read. Not an error: the export is still
   perfectly possible, and it is the reader's call. */
.rc-hint.rc-warn { color: var(--warn); font-weight: 500; }

/* A note on an outcome, whatever its status. Under the buttons rather than in
   a dialog, for the reason the strip is: the one thing a meeting cannot afford
   is an answer that looks recorded and is not, and a box in the row cannot be
   dismissed. */
.rc-notes {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 4px 6px;
  align-items: end;
  margin-top: 6px;
  max-width: 420px;
}
.rc-notes .rc-eyebrow { grid-column: 1 / -1; }
.rc-notes-box { min-height: 44px; resize: vertical; font-size: var(--fs-tiny); }
.rc-edit-outcome { margin-top: 4px; }

/* ── PTO ────────────────────────────────────────────────────────────────────
   Four weeks across, the team down the side. Twenty-eight columns leave no room
   for words, so the cell *is* the answer: one colour for leave however it was
   written down, another for a day spent off the project but at work, and the
   title attribute carries the rest. Those two must never read alike — one is a
   day somebody was away and the other is a day they worked — and nothing else
   here earns a colour of its own. */

.rc-pto-grid th,
.rc-pto-grid td { text-align: center; padding: 3px 2px; }
.rc-pto-grid .rc-pto-day {
  font-family: var(--f-mono);
  font-size: var(--fs-tiny);
  font-weight: 500;
  line-height: 1.25;
  min-width: 26px;
  color: var(--text-muted);
}
.rc-pto-grid .rc-pto-name {
  text-align: left;
  white-space: nowrap;
  position: sticky;
  left: 0;
  background: var(--surface);
  z-index: 1;
  min-width: 140px;
}
.rc-pto-cell { height: 22px; }
.rc-pto-weekend { background: var(--surface-sunk, rgba(127, 127, 127, 0.06)); }
.rc-pto-off { background: var(--surface-sunk, rgba(127, 127, 127, 0.06)); }
.rc-pto-today { border-left: 2px solid var(--accent, #e60012); }

/* PTO is one colour, wherever it was written down.
   It used to be three — a fill for a booking, a deepened fill where the sheet
   agreed, a hatch for the sheet alone — which drew a distinction about
   *bookkeeping* in the one colour on the screen that answers "who is off". A
   reader scanning four weeks of the team for a day somebody is away had to
   learn three swatches to read one fact. Where the day came from is still
   worth knowing and is still said: it is in the cell's title, in the count
   under the grid, and in whether the cell can be clicked to book it. */
.rc-pto-booked,
.rc-pto-booked.rc-pto-agreed,
.rc-pto-sheet { background: var(--rc-pto); }
.rc-pto-sheet.rc-clickable { cursor: pointer; }
.rc-pto-sheet.rc-clickable:hover { outline: 2px solid var(--text); outline-offset: -2px; }
/* Asked for and not answered. Hatched in the leave colour rather than filled
   with it: it is the same *kind* of thing as a day off and it is not one yet,
   and the day can still be staffed while the question is open. The hatch is
   how that reads at a glance across four weeks of the team. */
.rc-pto-asked {
  background: repeating-linear-gradient(
    45deg,
    var(--rc-pto) 0 3px,
    transparent 3px 7px
  );
}

/* A request waiting on somebody. Bordered rather than tinted, for the reason
   the 4WLA block in the week plan is: a tint would read as a status, and this
   is a list of open questions. */
.rc-pto-asks { border-color: var(--warn-border); }

/* Off the project — the office, another group's work — is not leave, and must
   never be mistaken for it. A colour of its own rather than a hatch of the
   leave colour, because those are days somebody worked and the difference
   between them and a day off is the whole question this screen answers. */
.rc-pto-elsewhere { background: var(--rc-offproject); }

.rc-pto-key {
  display: flex;
  flex-wrap: wrap;
  gap: 14px;
  margin: 10px 0 4px;
  font-size: var(--fs-tiny);
  color: var(--text-muted);
}
.rc-pto-key-item { display: inline-flex; align-items: center; gap: 6px; }
.rc-pto-swatch {
  width: 14px;
  height: 14px;
  border: 1px solid var(--border);
  border-radius: 3px;
  display: inline-block;
}

@media (max-width: 900px) {
  .rc-pto-grid .rc-pto-name { min-width: 110px; }
}

/* The cancellation log: one square per red day, so a cancelled week reads as
   a week at a glance, coloured by whose it was — BART red, Hitachi blue,
   another party amber, purple while nobody has said — as the calendar is. */
.rc-cancel-cells {
  display: flex;
  gap: 2px;
}
.rc-cancel-cell {
  --cancel-ink: var(--bad);
  width: 9px;
  height: 12px;
  border-radius: 2px;
  background: var(--cancel-ink);
}
.rc-cancel-cell.rc-cancel-by-hitachi { --cancel-ink: var(--info); }
.rc-cancel-cell.rc-cancel-by-other { --cancel-ink: var(--warn); }
.rc-cancel-cell.rc-cancel-open { --cancel-ink: var(--pending); }
/* A resource struck out of a day that went ahead: an outline, not a fill —
   the day was not cancelled, part of what it asked for was. */
.rc-cancel-cell.rc-cancel-cell-support {
  background: transparent;
  box-shadow: inset 0 0 0 2px var(--cancel-ink);
}

/* What somebody did that day, and the kind of work it was: a line of its own
   above the status buttons in the huddle, in the table and in the room. */
.rc-work {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
  margin: 0 0 6px;
}
.rc-work .rc-work-task { flex: 1 1 200px; min-width: 160px; }
.rc-work .rc-work-cat { flex: 0 1 160px; }
.rc-outcome-task { margin-top: 3px; }

/* The database is not the version this build expects — said once, at the top
   of the calendar, and dismissible. See schemaBanner() in ui/rc.js. */
.rc-schema-banner {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  margin: 0 0 14px;
  padding: 10px 12px;
  border: 1px solid var(--warn-border);
  border-radius: 8px;
  background: var(--warn-light);
  color: var(--text);
  font-size: 13px;
  line-height: 1.45;
}
.rc-schema-banner[hidden] { display: none; }
.rc-schema-icon { color: var(--warn); flex: none; margin-top: 1px; }
.rc-schema-text { flex: 1; min-width: 0; }
.rc-schema-banner .cx-btn { flex: none; }

/* Organisation → Problems: a timestamp that does not wrap, and machine words
   (where it happened, which build) set apart from what happened. */
.rc-table td.rc-nowrap { white-space: nowrap; }
.rc-table td.rc-mono { font-family: var(--f-mono); font-size: 12px; color: var(--text-muted); }

/* ── One table behaviour (ui/rc_table.js) ─────────────────────────────── */

/* A long table scrolls inside its frame, so its header can stay in view. The
   page itself already scrolls vertically; a header made sticky to the page
   would be caught by the frame's own horizontal scroll and never stick. */
.rc-scroll.rc-scroll-tall {
  max-height: min(70vh, 720px);
  overflow: auto;
}
/* Not the look-ahead, which freezes its own header and its activity columns at
   depths of their own (calendar.css). This rule is the more specific one, so it
   used to win there and put every heading at one depth: the day numbers slid
   over Activity, Description and Location going sideways, and the rows over
   them going down. */
.rc-scroll .rc-table:not(.la-grid) thead th {
  position: sticky;
  top: 0;
  z-index: 1;
  background: var(--surface-2);
}
.rc-table th.rc-num { text-align: right; }
.rc-table.rc-report th.rc-num { text-align: center; }

.rc-table th.rc-sortable {
  cursor: pointer;
  user-select: none;
}
.rc-table th.rc-sortable:hover,
.rc-table th.rc-sortable:focus-visible { color: var(--text-main); }
.rc-table th.rc-sortable::after {
  content: '';
  display: inline-block;
  width: 0.9em;
  margin-left: 4px;
  opacity: 0.35;
}
.rc-table th.rc-sortable:hover::after { content: '↕'; }
.rc-table th[aria-sort='ascending']::after { content: '↑'; opacity: 1; }
.rc-table th[aria-sort='descending']::after { content: '↓'; opacity: 1; }

.rc-table-tools {
  display: flex;
  justify-content: flex-end;
  margin: 0 0 6px;
}

@media (pointer: coarse) {
  .rc-frame .cx-btn,
  #rc-frame .cx-btn,
  #rc-frame .rc-tab {
    min-height: 44px;
  }
  #rc-frame .cx-btn.mini { padding-inline: 14px; }
  #rc-frame .cx-input,
  #rc-frame select,
  #rc-frame input[type='text'],
  #rc-frame input[type='date'] {
    min-height: 44px;
    font-size: 16px; /* below 16px a tablet zooms the page on focus */
  }
  #rc-frame .rc-table td,
  #rc-frame .rc-table th { padding: 10px 8px; }
  /* A borderless button is a word on a desktop, where a pointer finds it by
     hovering; a thumb has no hover, so each answer shows its edge. */
  #rc-frame .rc-present-answer .cx-btn,
  #rc-frame .rc-huddle .cx-btn { border: 1px solid var(--border-strong); }
}

@media (pointer: coarse) and (orientation: landscape) and (min-width: 900px) {
  .rc-present {
    max-width: 1180px;
    display: grid;
    grid-template-columns: minmax(0, 1fr) minmax(0, 1.1fr);
    column-gap: var(--space-5);
    row-gap: 0;
    align-items: start;
  }
  .rc-present > * { grid-column: 1; }
  .rc-present > .rc-present-top,
  .rc-present > .rc-present-move { grid-column: 1 / -1; }
  .rc-present > .rc-present-answer {
    grid-column: 2;
    grid-row: 2 / span 6;
    border-top: 0;
    padding-top: 0;
  }
  .rc-present-answer .cx-btn { min-height: 52px; }
}

/* ══════════════════════════════════════════════════════════════════════════
   The look-ahead editor (ui/rc_la_editor.js)

   The calendar grid, made writable: the same header rows, the same frozen
   activity columns, the workbook's own colours on the days. The activity
   columns have fixed widths so they can be frozen at known offsets.
   ═══════════════════════════════════════════════════════════════════════ */

.lae-toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--space-2) var(--space-3);
  padding: var(--space-2) 0 var(--space-3);
}
.lae-group {
  display: flex;
  align-items: center;
  gap: 6px;
}
.lae-right { margin-left: auto; }
.lae-range {
  font-family: var(--f-mono);
  font-size: var(--fs-tiny);
  font-weight: 700;
  letter-spacing: 0.04em;
  color: var(--text-main);
  padding: 0 6px;
  white-space: nowrap;
}
.lae-search { width: 170px; }

.lae-palette { gap: 4px; }
.lae-swatch {
  width: 24px;
  height: 24px;
  border-radius: 6px;
  border: 1px solid var(--border-strong);
  cursor: pointer;
  padding: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  transition: transform var(--dur-fast) var(--easing), box-shadow var(--dur-fast) var(--easing);
}
.lae-swatch:hover,
.lae-swatch:focus-visible { transform: translateY(-1px); box-shadow: var(--shadow-md); }
.lae-swatch-none {
  background: var(--surface);
  color: var(--text-muted);
}

.lae-codes { gap: 4px; }
.lae-code {
  min-width: 30px;
  height: 24px;
  padding: 0 8px;
  border-radius: 6px;
  border: 1px solid var(--border-strong);
  background: var(--surface-2);
  color: var(--text-main);
  font-family: var(--f-mono);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.04em;
  cursor: pointer;
  transition: background var(--dur-fast) var(--easing), border-color var(--dur-fast) var(--easing);
}
.lae-code:hover,
.lae-code:focus-visible { background: var(--surface-3); border-color: var(--info-border); }

.lae-status {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: var(--fs-tiny);
  color: var(--text-muted);
  white-space: nowrap;
  padding: 0 4px;
}
.lae-status-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--good);
}
.lae-status-saving .lae-status-dot { background: var(--info); }
.lae-status-retry .lae-status-dot,
.lae-status-conflict .lae-status-dot { background: var(--warn); }
.lae-status-retry { color: var(--warn); }

/* ── The grid ── */

.lae-scroll {
  position: relative;
  overflow: auto;
  max-height: calc(100vh - 250px);
  min-height: 320px;
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  background: var(--surface);
  outline: none;
}
.lae-scroll:focus,
.lae-scroll:focus-visible { outline: none; }
/* The caret cell is the focus indicator inside the grid; the frame only hints. */
.lae-scroll:focus-visible { box-shadow: 0 0 0 1px var(--info-border); }

.lae-grid {
  border-collapse: separate;
  border-spacing: 0;
  font-size: var(--fs-tiny);
  user-select: none;
  table-layout: fixed;
}
.lae-grid th,
.lae-grid td {
  border-right: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
  padding: 3px 6px;
  height: 26px;
  box-sizing: border-box;
  white-space: nowrap;
  overflow: hidden;
}

/* The header: three rows, frozen one under another. */
.lae-grid thead th {
  position: sticky;
  z-index: 3;
  background: var(--surface-2);
  font-family: var(--f-mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--text-muted);
  text-align: center;
}
.lae-grid thead tr:nth-child(1) th { top: 0; height: 26px; }
.lae-grid thead tr:nth-child(2) th { top: 26px; height: 22px; color: var(--text-main); font-size: 11px; }
.lae-grid thead tr:nth-child(3) th { top: 48px; height: 22px; border-bottom: 1px solid var(--border-strong); }
.lae-grid thead th.lae-meta,
.lae-grid thead th.lae-handle-head {
  top: 0;
  z-index: 5;
  vertical-align: bottom;
  text-align: left;
  white-space: normal;
  text-transform: none;
  letter-spacing: 0;
  font-family: var(--f-ui);
  font-size: var(--fs-tiny);
  color: var(--text-main);
  height: 70px;
}
.lae-grid thead th.lae-month {
  background: var(--surface-3);
  color: var(--text-main);
  text-align: left;
  letter-spacing: 0.1em;
}
.lae-grid thead th.lae-weekend { color: var(--text-faint); }
.lae-grid thead th.lae-today { color: var(--hitachi-red); }

/* The activity columns, frozen at fixed offsets. */
.lae-grid .lae-handle,
.lae-grid .lae-handle-head,
.lae-grid .lae-meta {
  position: sticky;
  z-index: 2;
  background: var(--surface);
}
.lae-grid .lae-handle,
.lae-grid .lae-handle-head { left: 0; width: 44px; min-width: 44px; max-width: 44px; padding: 0 2px; }
.lae-grid .lae-meta-activity_id { left: 44px; width: 104px; min-width: 104px; max-width: 104px; }
.lae-grid .lae-meta-description { left: 148px; width: 280px; min-width: 280px; max-width: 280px; }
.lae-grid .lae-meta-location { left: 428px; width: 112px; min-width: 112px; max-width: 112px; }
.lae-grid .lae-meta-sswp { left: 540px; width: 58px; min-width: 58px; max-width: 58px; }
.lae-grid .lae-meta-party { left: 598px; width: 72px; min-width: 72px; max-width: 72px; }
.lae-grid .lae-meta-work_hours { left: 670px; width: 92px; min-width: 92px; max-width: 92px; }
.lae-grid .lae-meta-last { border-right: 2px solid var(--border-strong); }
/* Every cell wraps: names, descriptions, locations and codes are read whole,
   and a row grows to hold its longest cell rather than clipping it. 26px stays
   the least a row is — a table cell's height is a minimum, not a cap. */
.lae-grid tbody td {
  white-space: normal;
  overflow-wrap: anywhere;
  line-height: 1.3;
}
.lae-grid td.lae-meta-description { font-weight: 500; color: var(--text-main); }

.lae-grid .lae-day {
  width: 58px;
  min-width: 58px;
  max-width: 58px;
  text-align: center;
  font-family: var(--f-mono);
  font-size: 10px;
  color: var(--text-main);
}
/* The same fixed greys as the calendar's view: a weekend column on every
   row, and the section band across the whole row with the weekends showing
   through. A painted day's colour is inline and covers the grey; take the
   shift off and the grey comes back. */
.lae-grid tbody td.lae-day.lae-weekend:not(.lae-painted) { background-color: var(--la-weekend); color: var(--la-weekend-ink); }
.lae-grid tfoot td.lae-weekend { background: var(--surface-2); }
.lae-grid td.lae-today { box-shadow: inset 2px 0 0 var(--hitachi-red); }
/* A painted day states its own colour, so its writing has to stay legible over
   whatever the colour turns out to be — as on the calendar grid. */
.lae-grid td.lae-painted { color: #111; font-weight: 700; }
.lae-grid td.lae-painted.lae-dark { color: #fff; }
.lae-grid td.lae-cancel {
  background-image: linear-gradient(
    to top right, transparent calc(50% - 1px), currentColor calc(50% - 1px),
    currentColor calc(50% + 1px), transparent calc(50% + 1px));
}
.lae-grid td.lae-unknown-code {
  text-decoration: underline wavy var(--warn);
  text-underline-offset: 3px;
}

/* Row kinds. */
.lae-grid tr.lae-section td {
  background-color: var(--la-band);
  border-top: 2px solid var(--border-strong);
  font-weight: 700;
  color: var(--la-band-ink);
}
.lae-grid tr.lae-section td.lae-day.lae-weekend { background-color: var(--la-weekend); }
.lae-grid tr.lae-section td.lae-meta-description { font-size: var(--fs-small); overflow: visible; }
.lae-grid tr.lae-resource td.lae-meta { font-style: italic; color: var(--text-muted); }
.lae-grid tr.lae-resource td { border-bottom-color: var(--border-strong); }
.lae-grid tr.lae-resource td.lae-day { font-family: var(--f-ui); font-weight: 500; text-align: left; }
.lae-grid tr.lae-absence td.lae-meta-description { font-weight: 700; }
.lae-grid tr.lae-absence td.lae-day { font-family: var(--f-ui); text-align: left; }
.lae-grid tr.lae-archived td { opacity: 0.45; }
.lae-grid td.lae-fixed.lae-meta { color: var(--text-muted); }

.lae-grip {
  display: inline-flex;
  width: 18px;
  height: 20px;
  align-items: center;
  justify-content: center;
  color: var(--text-faint);
  cursor: grab;
}
.lae-grid tr:hover .lae-grip { color: var(--text-muted); }
.lae-fold {
  display: inline-flex;
  width: 18px;
  height: 20px;
  align-items: center;
  justify-content: center;
  border: 0;
  background: none;
  color: var(--text-muted);
  cursor: pointer;
  padding: 0;
}

/* Selection: the range washed, the cell with the caret outlined, the corner
   square that drags a fill. */
.lae-grid td.lae-sel { box-shadow: inset 0 0 0 100px var(--info-light); }
.lae-grid td.lae-sel.lae-painted { box-shadow: inset 0 0 0 2px var(--info); }
.lae-grid td.lae-cur { outline: 2px solid var(--info); outline-offset: -2px; }
.lae-grid tr.lae-sel-row td.lae-handle { background: var(--info-light); }
.lae-grid td.lae-clip { outline: 1px dashed var(--info); outline-offset: -3px; }
.lae-grid td.lae-fill-preview { box-shadow: inset 0 0 0 100px var(--info-light); outline: 1px dashed var(--info); outline-offset: -2px; }
.lae-grid td { position: relative; }
.lae-grid td.lae-meta,
.lae-grid td.lae-handle { position: sticky; }
.lae-fill-handle {
  position: absolute;
  right: -1px;
  bottom: -1px;
  width: 7px;
  height: 7px;
  background: var(--info);
  border: 1px solid var(--surface);
  cursor: crosshair;
  z-index: 1;
}

.lae-drop-line {
  position: absolute;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--hitachi-red);
  pointer-events: none;
  z-index: 6;
}

/* Typing into a cell. */
.lae-editor {
  position: absolute;
  z-index: 7;
  box-sizing: border-box;
  padding: 2px 6px;
  border: 2px solid var(--info);
  border-radius: 0;
  background: var(--surface);
  color: var(--text-main);
  font: inherit;
  font-size: var(--fs-tiny);
  outline: none;
  box-shadow: var(--shadow-md);
}
.lae-edit-hint {
  position: absolute;
  z-index: 7;
  display: flex;
  gap: 4px;
  padding: 4px;
  border: 1px solid var(--border-strong);
  border-radius: 8px;
  background: var(--surface);
  box-shadow: var(--shadow-md);
}

/* What is asked for, per day, pinned under the grid. */
.lae-grid tfoot td {
  position: sticky;
  bottom: 0;
  z-index: 3;
  background: var(--surface-2);
  border-top: 1px solid var(--border-strong);
  height: auto;
  min-height: 26px;
  vertical-align: top;
}
.lae-grid tfoot td.lae-handle,
.lae-grid tfoot td.lae-meta { z-index: 4; }
.lae-grid tfoot td.lae-totals-label {
  left: 44px;
  width: 718px;
  min-width: 718px;
  max-width: 718px;
  font-family: var(--f-mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--text-muted);
}
.lae-grid tfoot td.lae-total {
  white-space: pre-line;
  font-family: var(--f-mono);
  font-size: 10px;
  font-weight: 700;
  line-height: 1.35;
  color: var(--text-main);
  text-align: center;
}

/* Starting: from the workbook, a file, or nothing. */
.lae-start {
  max-width: 720px;
  margin: var(--space-4) auto;
  text-align: center;
}
.lae-start h2 { margin: var(--space-2) 0; }
.lae-start-icon { color: var(--text-muted); }
.lae-start-options {
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
  margin-top: var(--space-4);
  text-align: left;
}
.lae-start-option {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-3);
  padding: 12px 14px;
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  background: var(--surface-2);
}

.lae-form {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: var(--space-2) var(--space-3);
}
.lae-summary { margin-top: var(--space-4); }
.lae-summary-total {
  font-size: var(--fs-small);
  font-weight: 600;
  color: var(--text-main);
  margin: 4px 0 var(--space-2);
}

@media (pointer: coarse) {
  .lae-swatch, .lae-code { min-height: 36px; min-width: 36px; }
  .lae-grid th, .lae-grid td { height: 32px; }
}

/* Names from the roster, offered under a names cell while typing. */
.lae-edit-hint.lae-names { flex-direction: column; min-width: 160px; padding: 4px; gap: 2px; }
.lae-edit-hint[hidden] { display: none; }
.lae-name {
  text-align: left;
  padding: 5px 8px;
  border: 0;
  border-radius: 6px;
  background: none;
  color: var(--text-main);
  font: inherit;
  font-size: var(--fs-tiny);
  cursor: pointer;
}
.lae-name:hover,
.lae-name.lae-name-on { background: var(--info-light); }

/* ── P6 in the Activity ID column ─────────────────────────────────────────
   What a row's ID says, without relying on colour: a P6 activity reads as an
   ID, a reason reads as a word in italics on a pill, an ID neither list has
   is underlined the way an unknown support code is, and an activity with
   nothing yet says so faintly. The hover names the activity in full. */
.lae-grid td.lae-p6-linked { font-family: var(--f-mono); font-size: 10px; }
.lae-grid td.lae-p6-linked.lae-p6-missing { text-decoration: line-through dotted var(--warn); }
.lae-p6-pill {
  display: inline-block;
  padding: 0 4px;
  border: 1px dashed var(--border-strong);
  border-radius: 999px;
  font-size: 10px;
  font-style: italic;
  overflow-wrap: break-word;
  color: var(--text-muted);
}
.lae-grid td.lae-p6-unknown {
  text-decoration: underline wavy var(--warn);
  text-underline-offset: 3px;
}
.lae-grid td.lae-p6-empty::before {
  content: 'Link P6…';
  color: var(--text-faint);
  font-style: italic;
}

.lae-edit-hint.lae-p6-hint {
  flex-direction: column;
  width: 460px;
  max-height: 300px;
  overflow: auto;
  padding: 4px;
  gap: 1px;
}
.lae-p6-help {
  padding: 4px 8px 6px;
  font-size: var(--fs-tiny);
  color: var(--text-muted);
}
.lae-p6-opt {
  display: grid;
  grid-template-columns: 96px 1fr auto;
  gap: 8px;
  align-items: baseline;
  text-align: left;
  padding: 5px 8px;
  border: 0;
  border-radius: 6px;
  background: none;
  color: var(--text-main);
  font: inherit;
  font-size: var(--fs-tiny);
  white-space: normal;
  cursor: pointer;
}
.lae-p6-opt:hover,
.lae-p6-opt.lae-p6-on { background: var(--info-light); }
.lae-p6-id {
  font-family: var(--f-mono);
  font-size: 10px;
  font-weight: 700;
  color: var(--text-main);
  overflow-wrap: anywhere;
}
.lae-p6-opt-flag .lae-p6-id {
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--text-faint);
}
.lae-p6-opt-flag .lae-p6-name { font-style: italic; }
.lae-p6-uses {
  font-family: var(--f-mono);
  font-size: 9px;
  color: var(--text-faint);
  white-space: nowrap;
}
.lae-p6-opt-more { grid-template-columns: 1fr; border-top: 1px solid var(--border); border-radius: 0 0 6px 6px; }
.lae-p6-more { display: inline-flex; align-items: center; gap: 6px; color: var(--text-muted); }
.lae-p6-todo.lae-p6-open { color: var(--warn); border-color: var(--warn-border); }
.lae-p6-field { display: flex; gap: 6px; align-items: center; }
.lae-p6-field .cx-input { flex: 1; min-width: 0; }

/* The picker: a search over the whole list, then the reasons. */
.p6-picker { display: flex; flex-direction: column; gap: var(--space-2); }
.p6-picker .p6-fill { margin: 0; }
.p6-picker-note { margin: 0; }
.p6-picker-list { max-height: 360px; overflow: auto; }
.p6-item {
  display: grid;
  grid-template-columns: minmax(90px, max-content) 1fr;
  column-gap: 12px;
  row-gap: 2px;
  align-items: baseline;
}
.p6-item .p6-id { font-family: var(--f-mono); font-size: var(--fs-tiny); font-weight: 700; color: var(--text-main); }
.p6-item .p6-name { color: var(--text-main); }
.p6-item .p6-meta {
  grid-column: 2;
  display: flex;
  flex-wrap: wrap;
  gap: 4px 10px;
  align-items: center;
  font-size: var(--fs-tiny);
  color: var(--text-muted);
}
.p6-item .p6-uses { font-family: var(--f-mono); font-size: 10px; color: var(--text-faint); }
.p6-item.p6-current { box-shadow: inset 3px 0 0 var(--info); }
.p6-reasons { border-top: 1px solid var(--border); padding-top: var(--space-3); }
.p6-reason-list { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 6px; }

/* The section. */
.p6-summary { display: flex; flex-wrap: wrap; align-items: baseline; gap: var(--space-3); margin: var(--space-2) 0; }
.p6-summary-count { font-family: var(--f-display); font-size: 15px; font-weight: 700; color: var(--text-main); }
.p6-coverage { display: flex; flex-wrap: wrap; gap: var(--space-3); }
.p6-stat {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 140px;
  padding: var(--space-2) var(--space-3);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  background: var(--surface-2);
}
.p6-stat-n { font-family: var(--f-mono); font-size: 18px; font-weight: 700; color: var(--text-main); }
.p6-stat-label { font-size: var(--fs-tiny); color: var(--text-muted); }
.p6-stat-good { border-color: var(--good-border, var(--border)); }
.p6-stat-warn { border-color: var(--warn-border); }
.p6-stat-warn .p6-stat-n { color: var(--warn); }
.p6-preview-line { margin: 0 0 4px; color: var(--text-main); }
.lae-cancel-form { grid-template-columns: 1fr; }
.lae-cancel-runs {
  margin: 0;
  padding-left: 18px;
  font-size: var(--fs-small);
  color: var(--text-main);
}

/* Take me back: the saves, newest first. */
.lae-restore { grid-template-columns: 1fr; }
.lae-restore-list {
  display: flex;
  flex-direction: column;
  gap: 2px;
  max-height: 320px;
  overflow: auto;
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  padding: 4px;
}
.lae-restore-point {
  display: grid;
  grid-template-columns: 170px 1fr auto;
  gap: 10px;
  align-items: center;
  padding: 7px 10px;
  border: 0;
  border-radius: 6px;
  background: none;
  color: var(--text-main);
  font: inherit;
  font-size: var(--fs-small);
  text-align: left;
  cursor: pointer;
}
.lae-restore-point:hover { background: var(--surface-2); }
.lae-restore-point.on { background: var(--info-light); outline: 1px solid var(--info-border); }
.lae-restore-when { font-family: var(--f-mono); font-size: var(--fs-tiny); }

/* ── Staffing clashes ────────────────────────────────────────────────────
   A names cell with somebody in it who cannot be there: on leave, on the PTO
   row, or on two shifts. Marked with an inset outline and a corner so it reads
   without colour too, and the reason is in the cell's tooltip. */
.lae-grid td.lae-clash {
  box-shadow: inset 0 0 0 2px var(--bad);
  background-image: linear-gradient(225deg, var(--bad) 0 6px, transparent 6px);
}
.lae-clash-btn {
  color: var(--bad);
  border-color: var(--bad-border);
  background: var(--bad-light);
}
.lae-clashes {
  display: grid;
  gap: 6px;
  max-height: 60vh;
  overflow: auto;
}
.lae-clash-day {
  margin-top: 6px;
  font-family: var(--f-mono);
  font-size: var(--fs-micro);
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--text-subtle);
}
.lae-clash-item {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 10px;
  align-items: center;
  font-size: var(--fs-tiny);
}
.lae-clash-detail {
  overflow-wrap: anywhere;
}

/* ── History of a day or a row ─────────────────────────────────────────── */
.lae-history {
  display: grid;
  gap: 4px;
  max-height: 60vh;
  margin: 0;
  padding: 0;
  overflow: auto;
  list-style: none;
}
.lae-history-item {
  display: grid;
  grid-template-columns: 150px 120px minmax(0, 1fr);
  gap: 10px;
  align-items: center;
  padding: 6px 8px;
  border-radius: var(--radius-sm);
  font-size: var(--fs-tiny);
}
.lae-history-item:nth-child(odd) {
  background: var(--surface-2);
}
.lae-history-when {
  font-family: var(--f-mono);
  color: var(--text-subtle);
}
.lae-history-what {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  align-items: center;
  overflow-wrap: anywhere;
}
.lae-history-from {
  color: var(--text-muted);
  text-decoration: line-through;
}
.lae-history-arrow {
  display: inline-flex;
  color: var(--text-subtle);
}

@media (max-width: 640px) {
  .lae-history-item {
    grid-template-columns: 1fr;
    gap: 2px;
  }
}

/* ── The administrator's inbox ───────────────────────────────────────── */
.rc-tab-count {
  display: inline-block;
  min-width: 18px;
  margin-left: 6px;
  padding: 0 5px;
  border-radius: 9px;
  border: 1px solid var(--bad-border);
  background: var(--bad-light);
  color: var(--bad);
  font-family: var(--f-mono);
  font-size: var(--fs-micro);
  font-weight: 700;
  line-height: 18px;
  text-align: center;
}
.rc-inbox-list {
  display: grid;
  gap: 6px;
  margin: 0;
  padding: 0;
  list-style: none;
}
.rc-inbox-item {
  display: grid;
  grid-template-columns: 110px minmax(0, 1fr) auto;
  gap: 12px;
  align-items: center;
  padding: 10px 12px;
  border: 1px solid var(--border);
  border-left-width: 3px;
  border-radius: var(--radius-sm);
  background: var(--surface);
}
.rc-inbox-bad { border-left-color: var(--bad); }
.rc-inbox-warn { border-left-color: var(--warn); }
.rc-inbox-info { border-left-color: var(--info); }
.rc-inbox-title {
  font-weight: 600;
  color: var(--text-main);
}
.rc-inbox-detail {
  margin-top: 2px;
  font-size: var(--fs-tiny);
  color: var(--text-muted);
  overflow-wrap: anywhere;
}
.rc-inbox-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  justify-content: flex-end;
}
.rc-inbox-failed {
  display: flex;
  gap: 6px;
  align-items: center;
  color: var(--warn);
}

@media (max-width: 700px) {
  .rc-inbox-item {
    grid-template-columns: minmax(0, 1fr);
  }
  .rc-inbox-actions { justify-content: flex-start; }
}

/* ── Settings ─────────────────────────────────────────────────────────── */
.rc-settings {
  display: grid;
  max-width: 880px;
}
.rc-settings-group {
  margin: 18px 0 6px;
  font-family: var(--f-mono);
  font-size: var(--fs-micro);
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--text-subtle);
}
.rc-settings-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  gap: 16px;
  align-items: center;
  padding: 10px 0;
  border-top: 1px solid var(--border);
}
.rc-settings-name {
  font-weight: 600;
  color: var(--text-main);
}
.rc-settings-row .rc-hint { margin: 2px 0 0; }
.rc-settings-inline {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
}
.rc-settings-inline .cx-input { flex: 1 1 160px; min-width: 0; }
.rc-settings-mono { font-family: var(--f-mono); }

@media (max-width: 700px) {
  .rc-settings-row { grid-template-columns: minmax(0, 1fr); gap: 6px; }
}

/* ── Seeing it as somebody else ──────────────────────────────────────── */
.rc-preview-banner {
  display: flex;
  align-items: center;
  gap: 10px;
  margin: 0 0 14px;
  padding: 10px 12px;
  border: 1px solid var(--info-border);
  border-radius: 8px;
  background: var(--info-light);
  color: var(--text);
  font-size: 13px;
  line-height: 1.45;
}
.rc-preview-banner > span:first-child { color: var(--info); flex: none; display: inline-flex; }
.rc-preview-text { flex: 1; min-width: 0; }

@media (max-width: 640px) {
  .rc-preview-banner { flex-wrap: wrap; }
}

/* ── My day ───────────────────────────────────────────────────────────── */
.rc-myday-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 14px;
}
.rc-myday-hello {
  margin: 2px 0 0;
  font-size: 22px;
  font-weight: 700;
  color: var(--text-main);
}
.rc-myday-cards {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 12px;
}
.rc-myday-card {
  display: grid;
  align-content: start;
  gap: 10px;
  padding: 14px 16px;
  border: 1px solid var(--border);
  border-radius: 10px;
  background: var(--surface);
}
.rc-myday-card:first-child {
  border-color: var(--primary);
  box-shadow: inset 3px 0 0 var(--primary);
}
.rc-myday-card-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
}
.rc-myday-card-head h3,
.rc-myday-weekwrap h3,
.rc-myday-note h3 {
  margin: 0;
  font-family: var(--f-mono);
  font-size: var(--fs-micro);
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--text-subtle);
}
.rc-myday-card-head .rc-hint { margin: 0; }
.rc-myday-task {
  display: grid;
  gap: 6px;
  padding: 10px 12px;
  border-radius: 8px;
  background: var(--surface-2);
}
.rc-myday-task-title {
  font-size: 15px;
  font-weight: 600;
  color: var(--text-main);
  overflow-wrap: anywhere;
}
.rc-myday-facts {
  display: flex;
  flex-wrap: wrap;
  gap: 6px 14px;
}
.rc-myday-fact {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: var(--fs-tiny);
  color: var(--text-muted);
}
.rc-myday-off {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 15px;
  font-weight: 600;
  color: var(--text-main);
}
.rc-myday-off > span:first-child { color: var(--warn); display: inline-flex; }
.rc-myday-weekwrap {
  margin-top: 18px;
}
.rc-myday-week {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 6px;
  margin: 8px 0 0;
  padding: 0;
  list-style: none;
}
.rc-myday-day {
  display: grid;
  gap: 2px;
  padding: 8px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--surface);
  min-width: 0;
}
.rc-myday-today {
  border-color: var(--primary);
}
.rc-myday-quiet {
  background: var(--surface-2);
}
.rc-myday-wd {
  font-family: var(--f-mono);
  font-size: var(--fs-micro);
  text-transform: uppercase;
  color: var(--text-subtle);
}
.rc-myday-where {
  font-size: var(--fs-tiny);
  font-weight: 600;
  color: var(--text-main);
  overflow-wrap: anywhere;
}
.rc-myday-quiet .rc-myday-where { color: var(--text-muted); font-weight: 400; }
.rc-myday-foot {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 12px;
  margin-top: 18px;
}
.rc-myday-note {
  display: grid;
  gap: 8px;
  align-content: start;
  padding: 12px 14px;
  border: 1px solid var(--border);
  border-radius: 10px;
}
.rc-myday-note .rc-hint { margin: 0; }
.rc-myday-outcome,
.rc-myday-blocker {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
}
.rc-myday-said {
  flex-basis: 100%;
  font-style: italic;
  color: var(--text-muted);
}

@media (max-width: 640px) {
  .rc-myday-week { grid-template-columns: repeat(4, minmax(0, 1fr)); }
  .rc-myday-head { flex-wrap: wrap; }
}

/* ── A task opens its whole activity ─────────────────────────────────── */
button.rc-myday-task-open {
  position: relative;
  width: 100%;
  border: 1px solid transparent;
  font: inherit;
  text-align: left;
  color: inherit;
  cursor: pointer;
  transition: border-color var(--dur-fast) var(--easing), background var(--dur-fast) var(--easing);
}
button.rc-myday-task-open:hover { border-color: var(--border-strong); }
button.rc-myday-task-open:focus-visible { outline: 2px solid var(--primary); outline-offset: 2px; }
.rc-myday-more {
  position: absolute;
  top: 10px;
  right: 12px;
  font-family: var(--f-mono);
  font-size: var(--fs-micro);
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--text-subtle);
}

.rc-activity { display: grid; gap: 14px; }
.rc-activity-facts {
  display: grid;
  grid-template-columns: max-content minmax(0, 1fr);
  gap: 4px 16px;
  margin: 0;
}
.rc-activity-facts dt {
  font-family: var(--f-mono);
  font-size: var(--fs-micro);
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--text-subtle);
  padding-top: 2px;
}
.rc-activity-facts dd {
  margin: 0;
  color: var(--text-main);
  white-space: pre-line;
  overflow-wrap: anywhere;
}
.rc-activity-sub { display: flex; align-items: baseline; gap: 10px; }
.rc-activity-sub h4 {
  margin: 0;
  font-family: var(--f-mono);
  font-size: var(--fs-micro);
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--text-subtle);
}
.rc-activity-sub .rc-hint { margin: 0; }
.rc-activity-days {
  display: grid;
  gap: 4px;
  max-height: 50vh;
  margin: 0;
  padding: 0;
  overflow: auto;
  list-style: none;
}
.rc-activity-day {
  display: grid;
  grid-template-columns: 110px 150px minmax(0, 1fr) auto;
  gap: 10px;
  align-items: center;
  padding: 7px 10px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  font-size: var(--fs-tiny);
}
.rc-activity-mine { border-color: var(--primary); box-shadow: inset 3px 0 0 var(--primary); }
.rc-activity-today .rc-activity-when { color: var(--primary); font-weight: 700; }
.rc-activity-cancelled .rc-activity-shift { color: var(--bad); text-decoration: line-through; }
.rc-activity-when { font-family: var(--f-mono); color: var(--text-muted); }
.rc-activity-shift, .rc-activity-who { display: flex; align-items: center; gap: 6px; min-width: 0; }
.rc-activity-who { flex-wrap: wrap; overflow-wrap: anywhere; }
.rc-activity-swatch {
  width: 12px;
  height: 12px;
  flex: none;
  border: 1px solid var(--border-strong);
  border-radius: 3px;
}
.rc-activity-text { font-family: var(--f-mono); color: var(--text-subtle); }
.rc-activity-why { grid-column: 1 / -1; color: var(--bad); }

@media (max-width: 640px) {
  .rc-activity-day { grid-template-columns: 1fr 1fr; }
  .rc-activity-who { grid-column: 1 / -1; }
}

/* ── What changed for you ─────────────────────────────────────────────── */
.rc-tab-count.rc-tab-count-info {
  border-color: var(--info-border);
  background: var(--info-light);
  color: var(--info);
}
.rc-myday-changes { margin-bottom: 14px; }
.rc-myday-changes[hidden] { display: none; }
.rc-myday-uptodate { margin: 0; }
.rc-myday-changes-open {
  display: grid;
  gap: 10px;
  padding: 14px 16px;
  border: 1px solid var(--warn-border);
  border-left-width: 3px;
  border-radius: 10px;
  background: var(--warn-light);
}
.rc-myday-changes-head { display: flex; flex-wrap: wrap; align-items: baseline; gap: 10px; }
.rc-myday-changes-head h3 { margin: 0; font-size: 15px; font-weight: 700; color: var(--text-main); }
.rc-myday-changes-head .rc-hint { margin: 0; }
.rc-myday-change-list { display: grid; gap: 6px; margin: 0; padding: 0; list-style: none; }
.rc-myday-change {
  display: flex;
  align-items: baseline;
  gap: 8px;
  font-size: var(--fs-small, 13px);
  color: var(--text-main);
  overflow-wrap: anywhere;
}
.rc-myday-change .cx-badge { flex: none; }
.rc-myday-changes-foot { display: flex; flex-wrap: wrap; align-items: center; gap: 10px; }
.rc-myday-changes-foot .rc-hint { margin: 0; }
#rc-frame .la-cancel-grid td.la-cancel-run[title] { cursor: pointer; }

/* ── TAWR: track access work requests ───────────────────────────────────── */

.rc-tawr-weeks { margin: 12px 0; flex-wrap: wrap; }

.rc-tawr-toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px 16px;
  margin: 0 0 12px;
}
.rc-tawr-week-line { flex: 1 1 260px; }
.rc-tawr-actions { display: flex; flex-wrap: wrap; gap: 6px; }

.rc-tawr-notice {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 10px 12px;
  margin: 0 0 12px;
  border: 1px solid var(--info-border);
  border-radius: var(--radius-md);
  background: var(--info-light);
  color: var(--text-main);
}
.rc-tawr-notice-warning { border-color: var(--warn-border); background: var(--warn-light); }
.rc-tawr-notice > div { flex: 1 1 auto; }
.rc-tawr-notice .cx-btn { flex: none; }

.rc-tawr-list {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(340px, 1fr));
  gap: 12px;
}

@media (max-width: 720px) {
  .rc-tawr-list { grid-template-columns: minmax(0, 1fr); }
}

.rc-tawr-card {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 12px 14px;
  border: 1px solid var(--border);
  border-left: 3px solid var(--border-strong);
  border-radius: var(--radius-md);
  background: var(--surface-raised);
}
.rc-tawr-card.rc-tawr-draft { border-left-color: var(--warn); }
.rc-tawr-card.rc-tawr-approved { border-left-color: var(--good); }

.rc-tawr-card-head { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; }
.rc-tawr-card-head h4 { margin: 0 6px 0 0; font-size: 15px; font-weight: 600; }

.rc-tawr-facts {
  display: grid;
  grid-template-columns: max-content minmax(0, 1fr);
  gap: 3px 10px;
  margin: 0;
  font-size: 13px;
}
.rc-tawr-facts dt {
  color: var(--text-muted);
  font-family: var(--f-mono);
  font-size: var(--fs-tiny);
  letter-spacing: 0.06em;
  text-transform: uppercase;
  padding-top: 2px;
}
.rc-tawr-facts dd { margin: 0; overflow-wrap: anywhere; }

.rc-tawr-flags { list-style: none; margin: 0; padding: 0; display: grid; gap: 4px; font-size: 12.5px; }
.rc-tawr-flags li { display: flex; gap: 6px; align-items: flex-start; }
.rc-tawr-flags li > span:first-child { flex: none; padding-top: 2px; }
.rc-tawr-flag-block { color: var(--bad); }
.rc-tawr-flag-note { color: var(--text-muted); }

.rc-tawr-meta { margin: 0; }
.rc-tawr-card-actions { display: flex; flex-wrap: wrap; gap: 6px; margin-top: auto; }

/* Review */
.rc-tawr-review { display: grid; gap: 12px; }
.rc-tawr-fit { font-size: 12.5px; color: var(--text-muted); min-height: 1em; }
.rc-tawr-fit.rc-warn { color: var(--warn); font-weight: 500; }
.rc-tawr-form { display: grid; gap: 14px; }
.rc-tawr-section {
  margin: 0;
  padding: 10px 12px 12px;
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  display: grid;
  gap: 8px;
}
.rc-tawr-section legend {
  padding: 0 6px;
  font-family: var(--f-mono);
  font-size: var(--fs-tiny);
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--text-muted);
}
.rc-tawr-qs, .rc-tawr-checks { display: flex; flex-wrap: wrap; gap: 8px 18px; }
.rc-tawr-q { display: flex; align-items: center; gap: 8px; font-size: 13px; }
.rc-tawr-grid2 { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px 14px; }

@media (max-width: 640px) { .rc-tawr-grid2 { grid-template-columns: minmax(0, 1fr); }
}
.rc-tawr-pair { display: grid; gap: 4px; font-size: 12.5px; color: var(--text-muted); }
.rc-tawr-pair .cx-input, .rc-tawr-pair .cx-select { width: 100%; }
.rc-tawr-ctl { display: inline-flex; align-items: center; gap: 6px; border-radius: var(--radius-sm); min-width: 0; }
.rc-tawr-ctl .cx-input { width: 100%; }
.rc-tawr-check { font-size: 13px; color: var(--text-main); cursor: pointer; }
.rc-tawr-textarea { width: 100%; min-height: 84px; resize: vertical; font-family: inherit; }
.rc-tawr-line { display: grid; grid-template-columns: minmax(200px, 260px) minmax(0, 1fr); align-items: center; gap: 10px; }

@media (max-width: 640px) { .rc-tawr-line { grid-template-columns: minmax(0, 1fr); }
}
.rc-tawr-rows td { padding: 4px 6px; }
.rc-tawr-rows .rc-tawr-ctl { width: 100%; }

/* A field changed by hand: marked by an outline and said in its title, never by colour alone. */
.rc-tawr-edited { box-shadow: 0 0 0 2px var(--info-border); }
.rc-tawr-edited::after {
  content: 'edited';
  font-family: var(--f-mono);
  font-size: 10px;
  letter-spacing: 0.04em;
  color: var(--info);
  padding-right: 4px;
}

/* Setup */
.rc-tawr-signature { display: grid; gap: 8px; justify-items: start; }
.rc-tawr-pad {
  width: 360px;
  max-width: 100%;
  height: 120px;
  aspect-ratio: 3 / 1;
  border: 1px dashed var(--border-strong);
  border-radius: var(--radius-md);
  background: var(--surface-2);
  color: var(--text-main);
  touch-action: none;
  cursor: crosshair;
}
.rc-tawr-descriptions { margin-top: 24px; }
.rc-tawr-chips { display: flex; flex-wrap: wrap; gap: 6px; }

/* ── The master export ─────────────────────────────────────────────────── */
.rc-mx-sheets { display: flex; flex-direction: column; gap: 6px; }
.rc-mx-dates, .rc-mx-when { display: flex; gap: 12px; flex-wrap: wrap; }
.rc-mx-dates > .cx-field, .rc-mx-when > .cx-field { flex: 1 1 140px; margin: 0; }
.rc-mx-dates[hidden], .rc-mx-when > [hidden] { display: none; }
.rc-mx-status { margin: 0; }

