  /* ══════════════════════════════════════════════════════════════════════════
     Normalisation & migration
     ═══════════════════════════════════════════════════════════════════════ */

  /**
   * Migration steps, applied in order for any document older than
   * SCHEMA_VERSION. Each step takes a document and returns the next shape.
   * Never delete a step — old files must always be able to walk forward.
   */
  const MIGRATIONS = [
    // v0 → v1: the initial released schema. Documents written by pre-release
    // builds carried dates as ISO strings and had no `row` on objects.
    (doc) => {
      (doc.objects || []).forEach((o) => {
        if (typeof o.start === 'string') o.start = toMs(o.start);
        if (typeof o.end === 'string') o.end = toMs(o.end);
        if (o.row == null) o.row = 0;
      });
      doc.schema = 1;
      return doc;
    },

    // v1 → v2: status, subsystem, test type, severity, approval and the font
    // menu became editable project data. `normalise()` seeds the lists and
    // adopts any value the document already uses, so nothing is lost.
    (doc) => {
      if (!doc.lists) doc.lists = defaultLists();
      doc.schema = 2;
      return doc;
    },

    // v2 → v3: the P6 register. Nothing to convert — an older plan simply has
    // no imported schedule yet.
    (doc) => {
      if (!doc.p6) doc.p6 = emptyRegister();
      doc.schema = 3;
      return doc;
    },

    // v3 → v4: an object may track several P6 activities, not one. A bar that
    // stands for a campaign is routinely a dozen of them.
    (doc) => {
      for (const obj of doc.objects || []) {
        if (!obj.data) continue;
        if (Array.isArray(obj.data.p6Ids)) continue;
        obj.data.p6Ids = obj.data.p6Id ? [obj.data.p6Id] : [];
        delete obj.data.p6Id;
      }
      doc.schema = 4;
      return doc;
    },

    // v4 → v5: the field beside `client` is called the project, not the
    // programme. A word, but a stored one — the old key has to be carried across
    // or every plan written before this loses what was typed into it. Kept rather
    // than dropped where both somehow exist: a value somebody typed is never the
    // thing a rename throws away.
    (doc) => {
      if (doc.project === undefined || doc.project === '') {
        if (typeof doc.programme === 'string') doc.project = doc.programme;
      }
      delete doc.programme;
      doc.schema = 5;
      return doc;
    },

    // v5 → v6: the look-ahead register. Nothing to convert — an older plan has
    // simply never been shown a look-ahead.
    (doc) => {
      if (!doc.lookahead) doc.lookahead = emptyLookahead();
      doc.schema = 6;
      return doc;
    },
  ];

  /**
   * Bring any document — freshly parsed, imported, or restored from a backup —
   * up to the current schema and guarantee every field the renderer touches
   * exists. This is the single gate every document passes through.
   */
  function normalise(input) {
    let doc = input && typeof input === 'object' ? deepClone(input) : makeProject();

    const from = Number.isFinite(doc.schema) ? doc.schema : 0;
    for (let v = from; v < SCHEMA_VERSION; v++) {
      const step = MIGRATIONS[v];
      if (step) doc = step(doc);
    }

    const base = makeProject(doc.name || 'Untitled Project');
    doc.schema = SCHEMA_VERSION;
    doc.id = doc.id || base.id;
    doc.name = doc.name || base.name;
    doc.description = doc.description ?? '';
    doc.client = doc.client ?? '';
    doc.project = doc.project ?? '';
    doc.created = doc.created || Date.now();
    doc.modified = doc.modified || Date.now();
    doc.settings = { ...defaultSettings(), ...(doc.settings || {}) };
    doc.lists = normaliseLists(doc);
    doc.p6 = normaliseRegister(doc);
    doc.lookahead = normaliseLookahead(doc);
    doc.baselines = Array.isArray(doc.baselines) ? doc.baselines : [];
    doc.groups = Array.isArray(doc.groups) ? doc.groups : [];
    doc.attachments = Array.isArray(doc.attachments) ? doc.attachments : [];
    doc.versions = Array.isArray(doc.versions) ? doc.versions : [];
    doc.meta = { editCount: 0, ...(doc.meta || {}) };

    doc.lanes = (Array.isArray(doc.lanes) ? doc.lanes : []).map((l) => makeLane(l));
    const laneIds = new Set(doc.lanes.map((l) => l.id));

    // laneOrder is authoritative for display order; repair it against the lanes.
    const order = Array.isArray(doc.laneOrder) ? doc.laneOrder.filter((id) => laneIds.has(id)) : [];
    for (const l of doc.lanes) if (!order.includes(l.id)) order.push(l.id);
    doc.laneOrder = order;

    const fallbackLane = doc.lanes[0] ? doc.lanes[0].id : null;
    doc.objects = (Array.isArray(doc.objects) ? doc.objects : []).map((o) => {
      const obj = makeObject(o);
      if (!laneIds.has(obj.lane)) obj.lane = fallbackLane;
      return obj;
    });

    const objIds = new Set(doc.objects.map((o) => o.id));
    doc.links = (Array.isArray(doc.links) ? doc.links : [])
      .map((l) => makeLink(l))
      .filter((l) => objIds.has(l.from) && objIds.has(l.to) && l.from !== l.to);

    return doc;
  }

  /**
   * Repair the document's vocabularies.
   *
   * Missing lists are seeded from the defaults, malformed options are dropped,
   * and — importantly — any value the objects actually use but the list does
   * not contain is adopted into it. An imported plan carrying an unfamiliar
   * status therefore keeps working and becomes editable, rather than silently
   * reading as an unknown value forever.
   */
  /**
   * Bring the P6 register to a known shape.
   *
   * Entries are keyed by activity ID, which is the only stable identifier P6
   * gives us — names get edited, dates move, but the ID survives. Anything
   * without one is dropped, because it could never be matched on re-import.
   */
  function normaliseRegister(doc) {
    const raw = doc?.p6;
    const out = emptyRegister();
    if (!raw || typeof raw !== 'object') return out;

    out.baseline = raw.baseline || null;
    out.progress = raw.progress || null;
    out.history = Array.isArray(raw.history) ? raw.history.slice(0, 12) : [];

    const source = raw.activities && typeof raw.activities === 'object' ? raw.activities : {};
    for (const [key, value] of Object.entries(source)) {
      if (!value || typeof value !== 'object') continue;
      const id = String(value.id || key || '').trim();
      if (!id) continue;
      out.activities[id] = makeP6Activity({ ...value, id });
    }
    return out;
  }

  function normaliseLists(doc) {
    const seeds = defaultLists();
    const out = {};

    for (const listId of LIST_IDS) {
      const incoming = Array.isArray(doc.lists?.[listId]) ? doc.lists[listId] : seeds[listId];
      const seen = new Set();
      const options = [];

      for (const raw of incoming || []) {
        if (!raw || typeof raw !== 'object') continue;
        const id = raw.id === '' ? '' : String(raw.id ?? '').trim();
        if (raw.id == null || seen.has(id)) continue;
        seen.add(id);
        options.push({
          id,
          label: String(raw.label ?? id) || '(unnamed)',
          ...(raw.color ? { color: raw.color } : {}),
          ...(raw.tone ? { tone: raw.tone } : {}),
        });
      }

      // Adopt in-use values that are not in the list.
      for (const value of listValuesInUse(doc, listId)) {
        if (!seen.has(value)) {
          seen.add(value);
          options.push({ id: value, label: String(value) });
        }
      }

      out[listId] = options;
    }

    return out;
  }

  /**
   * Structural validation used by the importer. Returns
   * `{ ok, errors: [], warnings: [] }` — errors block, warnings don't.
   */
  function validate(doc) {
    const errors = [];
    const warnings = [];

    if (!doc || typeof doc !== 'object') {
      return { ok: false, errors: ['File does not contain a JSON object.'], warnings };
    }
    if (!Array.isArray(doc.objects)) errors.push('Missing "objects" array.');
    if (!Array.isArray(doc.lanes)) errors.push('Missing "lanes" array.');
    if (Number.isFinite(doc.schema) && doc.schema > SCHEMA_VERSION) {
      errors.push(`File uses schema v${doc.schema}; this build understands up to v${SCHEMA_VERSION}. Update the application.`);
    }

    if (Array.isArray(doc.objects)) {
      const laneIds = new Set((doc.lanes || []).map((l) => l.id));
      let orphans = 0;
      let badDates = 0;
      for (const o of doc.objects) {
        if (o.lane && !laneIds.has(o.lane)) orphans++;
        if (!Number.isFinite(toMs(o.start))) badDates++;
      }
      if (orphans) warnings.push(`${orphans} object(s) reference a missing lane — they will move to the first lane.`);
      if (badDates) warnings.push(`${badDates} object(s) have an unreadable start date — they will default to today.`);
    }

    return { ok: errors.length === 0, errors, warnings };
  }

  /* ══════════════════════════════════════════════════════════════════════════
     Derived helpers
     ═══════════════════════════════════════════════════════════════════════ */

  /** The effective "today" — the system date unless the user has pinned one. */
  function effectiveToday(doc) {
    const override = doc?.settings?.todayOverride;
    if (override) {
      const ms = toMs(override);
      if (Number.isFinite(ms)) return ms;
    }
    return todayMs();
  }

  /** Duration in days (bars are half-open: start inclusive, end exclusive). */
  /* ── How long something takes ──────────────────────────────────────────── */

  /**
   * Whether a duration counts the calendar or the working week.
   *
   * A commissioning plan is read in working days: a task "two weeks long" means
   * ten days on site, and nobody counts the Saturdays. So the default is the
   * five-day week, holidays excluded — `settings.durationUnit` switches a project
   * back to calendar days if it wants them.
   *
   * Only the *counting* changes. Dates are dates: a bar still starts and finishes
   * where it is drawn, still spans the weekend it covers, and every other
   * calculation on this timeline — the ruler, the critical path, slip against a
   * baseline — is untouched.
   *
   * Pushed in from the store on every document change, the way the dropdown
   * vocabularies are: this module cannot read a setting for itself.
   */
  let durationUnit = 'working';
  let workingHolidays = [];

  function syncDurationBasis(settings) {
    durationUnit = settings && settings.durationUnit === 'calendar' ? 'calendar' : 'working';
    workingHolidays = Array.isArray(settings?.holidays) ? settings.holidays : [];
    setWorkWeek(durationUnit === 'working' ? 5 : 7);
  }

  /** True when durations are counted on a five-day week. */
  function countsWorkingDays() {
    return durationUnit === 'working';
  }

  function durationDays(obj) {
    if (!TYPES[obj.type]?.duration) return 0;
    if (durationUnit === 'working') return Math.max(0, workingDaysBetween(obj.start, obj.end, workingHolidays));
    return Math.max(0, Math.round((obj.end - obj.start) / MS_DAY));
  }

  /**
   * Where a bar `days` long starting at `start` finishes — the exact inverse of
   * `durationDays`, so typing 10 into the duration field and reading it back
   * gives 10 whichever way the project counts.
   */
  function endForDuration(start, days) {
    const n = Math.max(1, Math.round(days));
    return durationUnit === 'working' ? addWorkingSpan(start, n, workingHolidays) : start + n * MS_DAY;
  }

  /** Remaining duration in days given percent complete. */
  function remainingDays(obj) {
    const total = durationDays(obj);
    return Math.max(0, Math.round(total * (1 - (obj.progress || 0) / 100)));
  }

  /* ── Notes on the canvas ───────────────────────────────────────────────── */

  /**
   * The note an object shows on the timeline, as plain text — or '' when it has
   * none, or has been told not to show it.
   *
   * Writing a note is itself the request to see it: `data.showNotes` is only
   * ever *false*, set by turning the note off again, so a note added anywhere in
   * the application appears on the plan without a second step. The notes
   * themselves are rich text; what the canvas can lay out is the words.
   */
  function visibleNote(obj) {
    if (!obj || obj.data?.showNotes === false) return '';
    return noteText(obj.notes);
  }

  /** Whether this object would show its note if it had one. */
  function notesShown(obj) {
    return !obj || obj.data?.showNotes !== false;
  }

  /** A note's words, with the markup and the runs of blank space taken out. */
  function noteText(notes) {
    return String(notes || '')
      .replace(/<br\s*\/?>/gi, ' ')
      .replace(/<\/(p|div|li|h[1-6]|tr)>/gi, ' ')
      .replace(/<[^>]*>/g, '')
      .replace(/&nbsp;/gi, ' ')
      .replace(/&amp;/gi, '&')
      .replace(/&lt;/gi, '<')
      .replace(/&gt;/gi, '>')
      .replace(/\s+/g, ' ')
      .trim();
  }

  /** Resolve the accent colour for an object: explicit fill → status → type. */
  function objectColor(obj, lane) {
    if (obj.style?.fill) return obj.style.fill;
    const status = listOption('status', obj.status);
    /* A release and a document are read for their *state* rather than their
       kind — nobody scanning a plan needs reminding that the thing shaped like a
       document is a document, but whether the ITP is approved or still in review
       is the entire question. Both therefore take the status colour, and both
       stay overridable by `style.fill`, which is what "by default" means here.
       Any other type joins this rule by being named in it. */
    if ((obj.type === 'release' || obj.type === 'document') && status?.color) return status.color;
    if (lane?.color && (obj.type === 'activity' || obj.type === 'testwindow')) return lane.color;
    return TYPES[obj.type]?.accent || 'var(--type-activity)';
  }

  /** Object bounds in ms, always with end > start so hit-testing works. */
  function objectRange(obj) {
    const hasDuration = TYPES[obj.type]?.duration;
    return { start: obj.start, end: hasDuration ? Math.max(obj.end, obj.start + MS_DAY) : obj.start };
  }

  /* ══════════════════════════════════════════════════════════════════════════
     What actually happened
     ═══════════════════════════════════════════════════════════════════════ */

  /**
   * The dates somebody recorded against an object, or null.
   *
   * `data.actualStart` and `data.actualEnd` have been on the model and in the
   * CSV for as long as the inspector has had fields for them, and nothing ever
   * drew them or compared against them — so a campaign that started a fortnight
   * late looked exactly like one that started on time, and the two dates a
   * commissioning manager cares about most were the two nothing on the canvas
   * knew.
   *
   * Either may be missing and that is the normal case: work starts before it
   * finishes, so a bar in progress has a start and no finish. The missing end
   * falls back to the scheduled one, which is the honest reading — "it started on
   * the 4th and is still planned to finish on the 20th". A point object has no
   * finish at all, so its actual date is both edges.
   *
   * Null when neither is set, because "no actual dates" and "actual dates that
   * happen to match the plan" are different facts and only the second is worth
   * drawing.
   */
  function actualRange(obj) {
    const hasDuration = !!TYPES[obj.type]?.duration;
    const start = toMs(obj?.data?.actualStart);
    const end = hasDuration ? toMs(obj?.data?.actualEnd) : NaN;
    const hasStart = Number.isFinite(start);
    const hasEnd = Number.isFinite(end);
    if (!hasStart && !hasEnd) return null;

    const from = hasStart ? start : obj.start;
    const to = hasDuration ? (hasEnd ? end : obj.end) : from;
    return {
      start: from,
      // A finish before its start is somebody mid-typing into a date field, not
      // a fact about the work. Clamped rather than refused: refusing would empty
      // the bar while they are still keying the year.
      end: Math.max(to, from),
      hasStart,
      hasEnd,
    };
  }

  /**
   * Where the object *is*, for anything comparing it against a baseline.
   *
   * The actual dates where they have been recorded, the scheduled ones where
   * they have not. That is the whole of "compare against the actual dates, not
   * the scheduled ones, where they are available" — and it is one function
   * because the variance pane, the CSV, the packer, the renderer and the exported
   * drawing all have to measure the same movement or they will disagree by days
   * on the one number a review is about.
   *
   * `actual` says which answer came back, so a caller can label a variance as
   * what happened rather than what is still planned.
   */
  function comparedRange(obj) {
    const hasDuration = !!TYPES[obj.type]?.duration;
    const actual = actualRange(obj);
    if (!actual) {
      return { start: obj.start, end: hasDuration ? obj.end : obj.start, actual: false };
    }
    return { start: actual.start, end: actual.end, actual: true };
  }

  /** Extent of the whole project, padded, for fit-to-window and the minimap. */
  function projectExtent(doc) {
    if (!doc.objects.length) {
      const t = effectiveToday(doc);
      return { start: addDays(t, -30), end: addDays(t, 180) };
    }
    let min = Infinity;
    let max = -Infinity;
    for (const o of doc.objects) {
      const r = objectRange(o);
      if (r.start < min) min = r.start;
      if (r.end > max) max = r.end;
    }
    const pad = Math.max(MS_DAY * 7, (max - min) * 0.04);
    return { start: min - pad, end: max + pad };
  }

  /** Every distinct owner in the document, sorted. */
  function ownersOf(doc) {
    return Array.from(new Set(doc.objects.map((o) => o.owner).filter(Boolean))).sort();
  }

  /** Every distinct area in the document, sorted. */
  function areasOf(doc) {
