        class: 'sidenav-section-label',
        type: 'button',
        'aria-expanded': String(!folded.has(group.section)),
        title: 'Fold or unfold this section',
        onClick: () => {
          const now = box.classList.toggle('folded');
          head.setAttribute('aria-expanded', String(!now));
          const set = foldedGroups();
          if (now) set.add(group.section);
          else set.delete(group.section);
          try {
            localStorage.setItem(FOLDED_KEY, JSON.stringify([...set]));
          } catch {
            /* a remembered fold is a convenience; without storage it simply resets */
          }
        },
      }, [
        el('span', { text: group.section }),
        el('span', { class: 'sidenav-fold', html: icon('chevron-down', { size: 10 }) }),
      ]);
      box.appendChild(head);
      dom.navLinks.appendChild(box);
      for (const item of group.items) {
        const link = el('a', {
          class: 'nav-link',
          href: '#',
          dataset: { pane: item.pane },
          onClick: (e) => {
            e.preventDefault();
            showPane(item.pane);
          },
        }, [
          el('span', { class: 'nav-icon', html: icon(item.icon, { size: 16 }) }),
          el('span', { class: 'nav-label', text: item.label }),
          el('span', { class: 'nav-count', dataset: { countFor: item.pane } }),
        ]);
        box.appendChild(link);
      }
    }
    dom.sidenav.appendChild(dom.navLinks);

    dom.sidenav.appendChild(
      el('div', { class: 'sidenav-footer' }, [
        el('div', { class: 'sidenav-project-tag', dataset: { projectTag: '1' }, text: doc.project || doc.client || fallbackTag() }),
        el('button', {
          class: 'cx-btn mini',
          html: icon('maximize', { size: 12 }) + '<span>Present</span>',
          onClick: () => emit(EV.PRESENT_MODE, { on: !document.body.classList.contains('presenting') }),
        }),
      ].filter(Boolean))
    );

    updateNav();
  }

  /**
   * Timeline or calendar.
   *
   * Only rendered where a folder can be opened, because that is where the
   * calendar is kept.
   */
  function workspaceSwitch() {
    const button = (id, label, iconName) => el('button', {
      class: 'ws-btn',
      type: 'button',
      'aria-pressed': String(workspace.current() === id),
      html: icon(iconName, { size: 13 }) + `<span>${label}</span>`,
      onClick: () => workspace.show(id),
    });

    return el('div', { class: 'ws-switch', role: 'group', 'aria-label': 'Workspace' }, [
      button('timeline', 'Timeline', 'calendar'),
      button('calendar', 'Calendar', 'users'),
    ]);
  }

  /** What to call a project that has not been given a client or project. */
  function fallbackTag() {
    return isFileMode() ? 'Shared folder' : 'Local project';
  }

  function updateNav() {
    const doc = store.getDoc();
    const counts = {
      lanes: doc.lanes.length,
      outline: doc.objects.length,
      releases: doc.objects.filter((o) => o.type === 'release').length,
      campaigns: doc.objects.filter((o) => o.type === 'campaign').length,
      risks: doc.objects.filter((o) => o.type === 'risk' || o.type === 'issue').length,
      links: doc.links.length,
      baselines: doc.baselines.length,
    };

    for (const link of dom.navLinks.querySelectorAll('.nav-link')) {
      link.classList.toggle('active', link.dataset.pane === currentPane());
    }
    for (const node of dom.navLinks.querySelectorAll('[data-count-for]')) {
      const value = counts[node.dataset.countFor];
      node.textContent = value ? String(value) : '';
    }

    const tag = dom.sidenav.querySelector('[data-project-tag]');
    if (tag) tag.textContent = doc.project || doc.client || fallbackTag();
  }

