      ['showConnectors', 'link', 'Dependency arrows'],
      ['showProgress', 'activity', 'Progress fill'],
      ['criticalPath', 'route', 'Critical path'],
      ['showBaseline', 'compare', 'Baseline comparison'],
      ['showMinimap', 'map', 'Minimap'],
      ['showLegend', 'palette', 'Legend'],
    ]) {
