          html: icon('palette', { size: 14 }),
          onClick: (e) => openThemeMenu(e.currentTarget),
        }),
        el('button', {
          // Exports the *plan*, so it goes with the timeline. The calendar has
          // its own export, and two buttons called Export meaning different
