  function toolButton(iconName, title, onClick, key) {
    const button = el('button', {
      class: 'cx-btn icon',
      title: key ? `${title} · ${keyHint(key)}` : title,
      'aria-label': title,
      html: icon(iconName, { size: 14 }),
      onClick,
    });
    return button;
  }

  /** The date window in force, on the toolbar, with its own way out. */
  function refreshWindowChip() {
    if (!dom.windowChip) return;
    const { from, to } = store.getFilters();
    if (!from && !to) {
      dom.windowChip.style.display = 'none';
      return;
    }
    const say = (iso) => fmtDate(Date.parse(`${iso}T00:00:00Z`), 'numeric');
    const span = from && to ? `${say(from)} – ${say(to)}` : from ? `from ${say(from)}` : `to ${say(to)}`;
    dom.windowChip.style.display = '';
    dom.windowChip.innerHTML = `<span>${span}</span>${icon('x', { size: 11 })}`;
    dom.windowChip.setAttribute('aria-label', `Clear the date range ${span}`);
  }

  function refreshToolbar() {
    const doc = store.getDoc();
    const settings = doc.settings;
    const history = store.historyState();
    refreshWindowChip();

    dom.title.querySelector('.tt-name').textContent = doc.name;
    dom.title.querySelector('.tt-meta').textContent =
      [doc.client, doc.project].filter(Boolean).join(' · ') || fallbackTag();

    dom.undoBtn.disabled = !history.canUndo;
    dom.redoBtn.disabled = !history.canRedo;

    const tool = store.getTool();
    dom.selectBtn.classList.toggle('active', tool === 'select');
    dom.panBtn.classList.toggle('active', tool === 'pan');

    dom.snapSelect.value = settings.snap;

    for (const button of dom.toggles.querySelectorAll('[data-toggle]')) {
      button.classList.toggle('active', !!settings[button.dataset.toggle]);
    }

    const scale = viewport.currentScale().id;
    for (const button of dom.scaleSeg.querySelectorAll('button')) {
      const label = button.textContent.trim().toLowerCase();
      const map = { d: 'day', w: 'week', m: 'month', q: 'quarter', y: 'year' };
      button.classList.toggle('active', map[label] === scale);
    }
  }

  /* ── Add-object menu ───────────────────────────────────────────────────── */

  function openAddMenu(anchor) {
    const rect = anchor.getBoundingClientRect();
    const items = [];
    for (const group of typeGroups()) {
      items.push({ heading: group.name });
      for (const type of group.items) {
        items.push({
          label: type.label,
          icon: type.icon,
          onClick: () => {
            store.setTool(type.id);
            toast({ tone: 'info', title: `${type.label} tool`, message: 'Click on the timeline to place it.', timeout: 2600 });
          },
        });
      }
    }
    contextMenu(rect.left, rect.bottom + 4, items);
  }

  function openThemeMenu(anchor) {
    const rect = anchor.getBoundingClientRect();
    contextMenu(
      rect.left,
      rect.bottom + 4,
      [
        { heading: 'Theme' },
        ...THEMES.map((theme) => ({
          label: theme.label + (theme.id === getTheme() ? '  ✓' : ''),
          icon: theme.icon,
          onClick: () => applyTheme(theme.id),
        })),
      ]
    );
  }

  /* ── Actions ───────────────────────────────────────────────────────────── */

  async function renameProject() {
    const doc = store.getDoc();
    const name = await promptDialog({ title: 'Rename project', label: 'Project name', value: doc.name });
    if (name && name.trim()) store.setMeta({ name: name.trim() }, 'Rename project');
  }

  function fitAll() {
    const extent = projectExtent(store.getDoc());
    viewport.fitRange(extent.start, extent.end, 30);
    renderer.requestRender();
  }

  function goToToday() {
    viewport.centerOn(effectiveToday(store.getDoc()), 0.42);
    renderer.requestRender();
  }

  /* ── Page zoom, in the desktop app ─────────────────────────────────────────
     A browser zooms the page with Ctrl + / Ctrl − and Ctrl + wheel; the desktop
     window had no such thing, so the timeline and the calendar were stuck at one
     size. This gives it the same keys and a control in the status bar, through
     the window's own zoom (see `setPageZoom()`), remembered for next time. Ctrl +
     wheel over the timeline still zooms the timeline — that handler claims the
     event first — and zooms the page everywhere else. */

  const PAGE_ZOOMS = [0.5, 0.67, 0.75, 0.8, 0.9, 1, 1.1, 1.25, 1.5, 1.75, 2];
  const PAGE_ZOOM_KEY = 'cx.desktop.pageZoom';
  let pageZoom = 1;
  let pageZoomLabel = null;
  let pageZoomWired = false;

  function storedPageZoom() {
    try {
      const n = Number(localStorage.getItem(PAGE_ZOOM_KEY));
      return PAGE_ZOOMS.includes(n) ? n : 1;
    } catch {
      return 1;
    }
  }

  async function applyPageZoom(scale, holder) {
    try {
      await desktop.setPageZoom(scale);
    } catch {
      // An older shell without the permission: no control rather than a dead one.
      holder?.remove();
      return false;
    }
    pageZoom = scale;
    if (pageZoomLabel) pageZoomLabel.textContent = `${Math.round(scale * 100)}%`;
    try { localStorage.setItem(PAGE_ZOOM_KEY, String(scale)); } catch { /* remembered for this session only */ }
    return true;
  }

  function stepPageZoom(dir, holder) {
    const at = PAGE_ZOOMS.findIndex((z) => z >= pageZoom - 1e-6);
    const next = PAGE_ZOOMS[Math.max(0, Math.min(PAGE_ZOOMS.length - 1, (at < 0 ? 5 : at) + dir))];
    if (next !== pageZoom) applyPageZoom(next, holder);
  }

  function pageZoomControl() {
    const holder = el('span', { class: 'sb-item sb-page-zoom', title: 'Page zoom — Ctrl + and Ctrl −, or Ctrl and the wheel' });
    pageZoomLabel = el('button', {
      class: 'sb-zoom-reset', type: 'button', text: '100%',
      title: 'Back to 100%', 'aria-label': 'Reset page zoom to 100%',
      onClick: () => applyPageZoom(1, holder),
    });
    holder.append(
      el('button', { class: 'sb-zoom-step', type: 'button', text: '−', 'aria-label': 'Zoom out', title: 'Zoom out (Ctrl −)', onClick: () => stepPageZoom(-1, holder) }),
      pageZoomLabel,
      el('button', { class: 'sb-zoom-step', type: 'button', text: '+', 'aria-label': 'Zoom in', title: 'Zoom in (Ctrl +)', onClick: () => stepPageZoom(1, holder) }),
    );
    applyPageZoom(storedPageZoom(), holder);
    if (!pageZoomWired) {
      pageZoomWired = true;
      window.addEventListener('keydown', (e) => {
        if (!(e.ctrlKey || e.metaKey) || e.altKey) return;
        if (e.key === '=' || e.key === '+') { e.preventDefault(); stepPageZoom(1, holder); }
        else if (e.key === '-' || e.key === '_') { e.preventDefault(); stepPageZoom(-1, holder); }
      });
      window.addEventListener('wheel', (e) => {
        if (!e.ctrlKey || e.defaultPrevented) return;
        e.preventDefault();
        stepPageZoom(e.deltaY < 0 ? 1 : -1, holder);
      }, { passive: false });
    }
    return holder;
  }

  /* ── Status bar ────────────────────────────────────────────────────────── */

  function buildStatusbar() {
    clear(dom.statusbar);

    dom.saveDot = el('span', { class: 'sb-dot' });
    dom.saveText = el('span', { text: 'Saved' });
    // Announced when it changes — "Saving", "Saved", "Not saved" — and only this
    // item: the rest of the bar follows the pointer and would never stop talking.
    dom.statusbar.appendChild(el('span', {
      class: 'sb-item', title: 'Autosave status', 'aria-live': 'polite', 'aria-atomic': 'true',
    }, [dom.saveDot, dom.saveText]));

    dom.countText = el('span', { class: 'sb-item' });
    dom.statusbar.appendChild(dom.countText);

    dom.selText = el('span', { class: 'sb-item' });
    dom.statusbar.appendChild(dom.selText);

    dom.hiddenText = el('span', {
      class: 'sb-item clickable',
      title: 'Hidden objects — click to bring them back',
      onClick: () => cmd.openHiddenList(),
    });
    dom.statusbar.appendChild(dom.hiddenText);

    dom.violationText = el('span', {
      class: 'sb-item clickable sb-warn',
      title: 'Show broken dependencies',
      onClick: () => showPane('links'),
    });
    dom.statusbar.appendChild(dom.violationText);

    dom.statusbar.appendChild(el('span', { class: 'sb-spacer' }));

    dom.cursorText = el('span', { class: 'sb-item', title: 'Date under the cursor' });
    dom.statusbar.appendChild(dom.cursorText);

    dom.zoomText = el('span', {
      class: 'sb-item clickable',
      title: 'Fit the whole plan',
      onClick: fitAll,
    });
    dom.statusbar.appendChild(dom.zoomText);

    dom.storageText = el('span', {
      class: 'sb-item clickable',
      title: 'Open storage settings',
      onClick: () => showPane('settings'),
    });
    dom.statusbar.appendChild(dom.storageText);

    if (desktop.isAvailable()) dom.statusbar.appendChild(pageZoomControl());

    // The clickable items are buttons to a keyboard as well as a pointer.
    for (const item of dom.statusbar.querySelectorAll('.sb-item.clickable')) {
      item.setAttribute('role', 'button');
      item.tabIndex = 0;
      item.addEventListener('keydown', (e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          item.click();
        }
      });
    }

    refreshStatus();
  }

  function refreshStatus() {
    const doc = store.getDoc();
    const selection = store.getSelection();
    const zoom = viewport.describeZoom();

    dom.countText.textContent = `${doc.objects.length} objects · ${doc.lanes.length} lanes · ${doc.links.length} links`;
    dom.selText.textContent = selection.length ? `${selection.length} selected` : '';
    const hidden = doc.objects.filter((o) => o.hidden).length;
    dom.hiddenText.textContent = hidden ? `${hidden} hidden` : '';
    dom.hiddenText.style.display = hidden ? '' : 'none';

    const violations = linkViolations(doc);
    dom.violationText.textContent = violations.count
      ? `⚠ ${violations.count} broken ${violations.count === 1 ? 'dependency' : 'dependencies'}`
      : '';
    dom.violationText.style.display = violations.count ? '' : 'none';
    dom.zoomText.textContent = `${zoom.scale} · ${zoom.span}`;
    // Where the work is going. In a shared folder this is the most useful thing
    // on the status bar, so it names the plan and says who holds the pen.
    if (isFileMode()) {
      const st = filestore.state();
      /* Three states, in the order they matter: a newer version waiting is the
         one thing somebody needs to notice, and putting it here is what lets the
         notice about it be said once rather than repeated. */
      dom.storageText.textContent = st.behind
        ? `${st.plan} · newer version in the folder`
        : st.role === 'viewer'
          ? `${st.plan} · ${st.holder} editing`
          : `${st.plan} · folder`;
      dom.storageText.classList.toggle('behind', !!st.behind);
      dom.storageText.title = st.behind
        ? 'A colleague saved after you opened this. Reload from Import / export to take their version.'
        : `${st.folder}/${st.plan}`;
    } else {
      dom.storageText.classList.remove('behind');
      dom.storageText.textContent = isFallback() ? 'localStorage' : 'IndexedDB';
      dom.storageText.title = '';
    }
  }

  const refreshCursor = debounce((ms) => {
    if (dom.cursorText) dom.cursorText.textContent = Number.isFinite(ms) ? fmtDate(ms, 'dayFull') : '';
  }, 30);

  function setSaveState(state, at) {
    if (!dom.saveDot) return;
    dom.saveDot.className = 'sb-dot'
      + (state === 'saving' ? ' saving' : state === 'error' ? ' error' : state === 'held' ? ' held' : '');
    dom.saveText.textContent =
      state === 'saving' ? 'Saving…'
        : state === 'error' ? 'Save failed'
          : state === 'held' ? 'Not saved — read-only'
            : state === 'reading' ? 'Read-only'
              : at ? `Saved ${fmtTimestamp(at)}` : 'Saved';
  }

  /* ── Wiring ────────────────────────────────────────────────────────────── */

  function wireEvents() {
    const refresh = debounce(() => {
      refreshToolbar();
      refreshStatus();
      updateNav();
    }, 40);

    on(EV.DOC_CHANGED, (payload) => {
      if (payload?.transient) return;
      refresh();
    });
    on(EV.DOC_REPLACED, refresh);
    on(EV.HISTORY_CHANGED, refresh);

    on(EV.ACCESS_CHANGED, refresh);
    // The switch is two buttons; repainting the sidebar to move a highlight
    // would throw away the pane list and its scroll position for nothing.
    on(EV.CALENDAR_FAILED, ({ message }) => {
      toast({ tone: 'bad', title: 'The calendar did not open', message, timeout: 10000 });
    });
    on(EV.WORKSPACE_CHANGED, ({ workspace: which }) => {
      for (const btn of dom.sidenav.querySelectorAll('.ws-btn')) {
        const label = btn.querySelector('span')?.textContent.toLowerCase();
        btn.setAttribute('aria-pressed', String(label === which));
      }
    });
    on(EV.FILE_STATE, () => refreshStatus());
    on(EV.SELECTION_CHANGED, () => refreshStatus());
    on(EV.FILTER_CHANGED, () => refreshWindowChip());
    on(EV.TOOL_CHANGED, () => refreshToolbar());
    on(EV.VIEW_CHANGED, debounce(() => {
      refreshToolbar();
      refreshStatus();
    }, 60));
    on(EV.PANEL_CHANGED, () => updateNav());

    on(EV.SAVE_START, () => setSaveState('saving'));
    /* A skipped save is not a save. It happens when a colleague holds the pen,
       and calling it "Saved" is how the status bar came to be reassuring about
       work that had been written nowhere — but only when there was work: opening
       a plan somebody else is editing attempts a save too. */
    on(EV.SAVE_DONE, (p) => {
      if (!p?.skipped) return setSaveState('saved', p?.at);
      return setSaveState(p.unsaved ? 'held' : 'reading');
    });
    on(EV.SAVE_ERROR, () => setSaveState('error'));

    on('canvas:cursor', (p) => refreshCursor(p.ms));

    on(EV.PRESENT_MODE, ({ on: enabled }) => {
      document.body.classList.toggle('presenting', enabled);
      setTimeout(() => {
        renderer.measure();
        renderer.requestRender();
      }, 60);
    });
  }

  /** Public refresh hook for modules that change shell-visible state. */
  function refreshShell() {
    refreshToolbar();
    refreshStatus();
    updateNav();
