              'aria-label': 'Select dependency',
              html: icon('sliders', { size: 11 }),
              onClick: () => {
                renderer.setSelectedLinks([link.id]);
                store.clearSelection();
                render();
              },
            }),
            el('button', {
              class: 'cx-btn icon mini ghost',
              title: 'Delete dependency',
              'aria-label': 'Delete dependency',
              html: icon('unlink', { size: 11 }),
              onClick: () => {
                store.removeLinks([link.id]);
                renderer.requestRender();
                render();
              },
            }),
          ]),
        ])
      );
    }
    return out;
  }

  /* ── Appearance ────────────────────────────────────────────────────────── */

  function appearanceFields(obj) {
    const style = obj.style || {};
    const setStyle = (patch, label) => set(obj.id, { style: patch }, label || 'Change appearance');

    return [
      el('div', { class: 'cx-row' }, [
        field('Fill', colorControl({ value: style.fill || '#5b93f5', allowInherit: true, onChange: (v) => setStyle({ fill: v }, 'Change fill') })),
        field('Border', colorControl({ value: style.stroke || '#000000', allowInherit: true, onChange: (v) => setStyle({ stroke: v }, 'Change border') })),
      ]),
      el('div', { class: 'cx-row' }, [
        field('Border width', numberInput({ value: style.strokeWidth ?? 1, min: 0, max: 8, onChange: (v) => setStyle({ strokeWidth: v }, 'Change border width') })),
        field('Corner radius', numberInput({ value: style.radius ?? 6, min: 0, max: 30, onChange: (v) => setStyle({ radius: v }, 'Change corner radius') })),
      ]),
      field('Opacity', rangeInput({
        value: (style.opacity ?? 1) * 100,
        min: 15,
        max: 100,
        onChange: (v) => setStyle({ opacity: v / 100 }, 'Change opacity'),
      })),
      field('Pattern', segmented({
        value: style.pattern || 'none',
        stretch: true,
        options: [
          { value: 'none', label: 'None' },
          { value: 'stripes', label: 'Stripes' },
          { value: 'hatch', label: 'Hatch' },
          { value: 'dots', label: 'Dots' },
          { value: 'grid', label: 'Grid' },
        ],
        onChange: (v) => setStyle({ pattern: v }, 'Change pattern'),
      })),
      el('div', { class: 'cx-inline wrap' }, [
        checkbox({ label: 'Gradient', checked: !!style.gradient, onChange: (v) => setStyle({ gradient: v }, 'Toggle gradient') }),
        checkbox({ label: 'Shadow', checked: !!style.shadow, onChange: (v) => setStyle({ shadow: v }, 'Toggle shadow') }),
      ]),
      field('Rotation', rangeInput({
        value: style.rotation || 0,
        min: -45,
        max: 45,
        onChange: (v) => setStyle({ rotation: v }, 'Rotate'),
      }), 'Applies to notes, callouts, text boxes and shapes.'),
    ];
  }

  /* ── Baseline comparison ───────────────────────────────────────────────── */

  /**
   * What the comparison on the canvas is saying about this object.
   *
   * Clicking the striped area selects the bar, so this is what the click leads
   * to: where the baseline had it, where it is now, how far that is, and the
   * reason — the same sentence the canvas holds, editable from either place.
   *
   * A derived baseline is named for what it is. Its dates are the roll-up of
   * whatever P6 activities the bar is linked to right now, so the reader is sent
   * to the P6 section rather than being left to assume a frozen snapshot.
   * Null — and therefore no section at all — when the plan is not comparing.
   */
  function baselineFields(obj) {
    const doc = store.getDoc();
    const baseline = store.activeBaseline();
    if (!baseline || !doc.settings.showBaseline) return null;

    const def = TYPES[obj.type] || TYPES.activity;
    const snap = store.snapshotOf(baseline).find((row) => row.id === obj.id) || null;
    const derived = isDerivedBaseline(baseline);
    const out = [
      el('div', { class: 'cx-hint', text: derived
        ? `${baseline.name} — follows the P6 ${baseline.p6Kind === 'progress' ? 'progress' : 'baseline'} dates of whatever this bar is linked to.`
        : `${baseline.name} — frozen ${fmtDate(baseline.created, 'medium')}.` }),
    ];

    if (!snap) {
      out.push(el('div', { class: 'cx-hint', text: derived
        ? 'Nothing linked from the P6 register, so there is nothing to compare against. Link an activity in the P6 section below.'
        : 'Added since this baseline was taken: it has nothing to compare against.' }));
      return out;
    }

    const snapEnd = def.duration ? (snap.end ?? snap.start) : snap.start;
    const startShift = daysBetween(snap.start, obj.start);
    const endShift = def.duration ? daysBetween(snapEnd, obj.end) : startShift;
    const tone = endShift > 0 ? 'bad' : endShift < 0 ? 'good' : 'muted';

    out.push(
      el('div', { class: 'cx-chipstats' }, [
        chipStat('Was', def.duration
          ? `${fmtDate(snap.start, 'numeric')} → ${fmtDate(snapEnd, 'numeric')}`
          : fmtDate(snap.start, 'numeric'), 'muted'),
        chipStat('Now', def.duration
          ? `${fmtDate(obj.start, 'numeric')} → ${fmtDate(obj.end, 'numeric')}`
          : fmtDate(obj.start, 'numeric'), 'muted'),
        chipStat('Start', shift(startShift), startShift ? tone : 'muted'),
        def.duration ? chipStat('Finish', shift(endShift), endShift ? tone : 'muted') : null,
      ].filter(Boolean)),
      field('Reason for the change', textInput({
        value: delayReason(obj, baseline.id),
        placeholder: 'Why did this move?',
        onInput: (v) => {
          store.setDelayReason(obj.id, baseline.id, v);
          renderer.requestRender();
        },
      }), 'Shown in the striped area on the timeline, in the variance export and in the PDF.')
    );

    if (!startShift && !endShift) {
      out.push(el('div', { class: 'cx-hint', text: 'Sitting exactly where the baseline had it.' }));
    }

    return out;
  }

  /* ── Look-ahead ────────────────────────────────────────────────────────── */

  /**
   * The look-ahead runs this bar stands for. Shown only once something is
   * linked: unlike P6 there is no picker here, because a run is found by its
   * dates and its words in the Look-ahead pane, not by an ID somebody knows.
   */
  function lookaheadFields(obj) {
    const linked = laLinkedIds(obj);
    if (!linked.length) return null;
    const doc = store.getDoc();
    const register = lookaheadRegister(doc);
    const rollUp = laRollUp(doc, obj);
    const variance = laVariance(doc, obj);

    const out = [
      el('div', { class: 'p6-links' }, linked.map((id) => {
        const entry = register.activities[id];
        return el('div', { class: 'p6-chip' + (entry ? '' : ' unknown'), dataset: { la: id } }, [
          el('span', { class: 'p6-chip-name', text: entry ? entry.title : 'no longer in the register', title: entry?.label || '' }),
          entry ? el('span', { class: 'p6-dates', text: `${fmtDate(entry.start, 'numeric')} → ${fmtDate(entry.end - MS_DAY, 'numeric')}` }) : null,
          el('button', {
            class: 'cx-btn icon mini ghost',
            title: 'Stop standing for this run',
            'aria-label': `Unlink ${entry?.title || id}`,
            html: icon('x', { size: 10 }),
            onClick: () => {
              store.unlinkLookahead(obj.id, id);
              renderer.requestRender();
              render();
            },
          }),
        ].filter(Boolean));
      })),
    ];

    if (rollUp) {
      out.push(el('div', { class: 'cx-chipstats', style: { marginTop: '4px' } }, [
        chipStat('Sheet span', `${fmtDate(rollUp.start, 'numeric')} → ${fmtDate(rollUp.end - MS_DAY, 'numeric')}`, 'muted'),
        variance ? chipStat('You', shift(variance.finishShift), !variance.differs ? 'muted' : variance.behind ? 'warn' : 'info') : null,
      ].filter(Boolean)));
    }
    if (variance?.differs) {
      out.push(el('button', {
        class: 'cx-btn mini',
        html: icon('target', { size: 12 }) + '<span>Move onto the look-ahead dates</span>',
        onClick: () => {
          store.adoptLookaheadDates(linked);
          renderer.requestRender();
          render();
        },
      }));
    }
    return out;
  }

  /* ── P6 ────────────────────────────────────────────────────────────────── */

  /**
   * The P6 activities this object is tracked against.
   *
   * A bar routinely stands for a whole test package, so this is a set rather
   * than a field, and the dates it is measured against are the roll-up:
   * earliest start to latest finish across everything linked.
   *
   * Two numbers, deliberately separate: how far P6 has moved its own work since
   * the baseline, and how far this plan differs from where P6 has it now.
   */
  function p6Fields(obj) {
    const doc = store.getDoc();
    const register = p6Register(doc);
    if (!Object.keys(register.activities).length) return null;

    const linked = p6LinkedIds(obj);
    const rollUp = p6RollUp(doc, obj);
    const variance = p6Variance(doc, obj);

    const out = [];

    if (!linked.length) {
      out.push(el('div', { class: 'cx-hint', text: 'Not tracked against any P6 activity. Drag one from the P6 Schedule pane onto this bar, or add it below.' }));
    } else {
      out.push(
        el('div', { class: 'p6-links' }, linked.map((id) => {
          const activity = register.activities[id];
          const dates = activity ? p6Dates(activity) : null;
          return el('div', { class: 'p6-chip' + (activity ? '' : ' unknown'), dataset: { p6: id } }, [
            el('span', { class: 'p6-id', text: id }),
            el('span', { class: 'p6-chip-name', text: activity ? activity.name : 'not in the register', title: activity?.name || '' }),
            dates ? el('span', { class: 'p6-dates', text: `${fmtDate(dates.start, 'numeric')} → ${fmtDate(dates.end, 'numeric')}` }) : null,
            el('button', {
              class: 'cx-btn icon mini ghost',
              title: 'Stop tracking this activity',
              'aria-label': `Unlink ${id}`,
              html: icon('x', { size: 10 }),
              onClick: () => {
                store.unlinkP6(obj.id, id);
                renderer.requestRender();
                render();
              },
            }),
          ].filter(Boolean));
        }))
      );

      if (rollUp) {
        out.push(
          el('div', { class: 'cx-hint', text: linked.length === 1
            ? 'Measured against this activity.'
            : `Measured against all ${rollUp.count} — earliest start to latest finish.` }),
          el('div', { class: 'cx-chipstats', style: { marginTop: '4px' } }, [
            chipStat('P6 span', `${fmtDate(rollUp.start, 'numeric')} → ${fmtDate(rollUp.end, 'numeric')}`, 'muted'),
            chipStat('P6 slip', rollUpSlip(doc, obj), 'muted'),
            variance ? chipStat('You', shift(variance.finishShift), !variance.differs ? 'muted' : variance.behind ? 'warn' : 'info') : null,
          ].filter(Boolean))
        );
      }

      if (variance?.differs) {
        out.push(
          el('button', {
            class: 'cx-btn mini',
            html: icon('target', { size: 12 }) + '<span>Move onto the P6 dates</span>',
            onClick: () => {
              store.adoptP6Dates(linked);
              renderer.requestRender();
              render();
            },
          })
        );
      }
    }

    out.push(
      el('button', {
        class: 'cx-btn mini',
        style: { justifyContent: 'flex-start', width: '100%' },
        html: icon('search', { size: 12 }) + '<span>Add a P6 activity…</span>',
        onClick: () => openActivityPicker(obj, register, linked),
      })
    );

    return out;
  }

  /** How far P6 has moved the linked work since its own baseline. */
  function rollUpSlip(doc, obj) {
    const before = p6RollUp(doc, obj, 'baseline');
    const now = p6RollUp(doc, obj, 'progress');
    if (!before || !now) return '—';
    return shift(Math.round((now.end - before.end) / MS_DAY));
  }

  /**
   * Search the register.
   *
   * A dropdown stops being navigable long before fifteen hundred entries, and
   * nobody remembers an activity ID well enough to scroll to it.
   */
  function openActivityPicker(obj, register, alreadyLinked) {
    const taken = new Set(alreadyLinked);
    const items = Object.values(register.activities)
      .filter((a) => !taken.has(a.id))
      .sort((a, b) => a.order - b.order)
      .map((a) => ({
        value: a.id,
        label: a.name,
        meta: [a.id, a.wbs, p6Dates(a) ? `${fmtDate(p6Dates(a).start, 'numeric')} → ${fmtDate(p6Dates(a).end, 'numeric')}` : null]
          .filter(Boolean).join(' · '),
      }));

    if (!items.length) {
      return;
    }

    openPicker({
      title: 'Add a P6 activity',
      subtitle: `${items.length} not yet linked to this object.`,
      placeholder: 'Activity ID, name or WBS…',
      items,
      empty: 'No activity matches.',
      onPick: (activityId) => {
        if (!activityId) return;
        store.linkP6(obj.id, activityId);
        renderer.requestRender();
        render();
      },
    });
  }

  function shift(days) {
    if (days == null) return '—';
    if (days === 0) return 'on plan';
    return `${days > 0 ? '+' : '−'}${Math.abs(days)}d`;
  }

  /* ── Text ──────────────────────────────────────────────────────────────── */

  function textFields(obj) {
    const style = obj.style || {};
    const setStyle = (patch, label) => set(obj.id, { style: patch }, label || 'Change text style');

    return [
      field('Font', managedSelect({
        listId: 'font',
        value: style.font || '',
        placeholder: 'Interface (default)',
        onChange: (v) => setStyle({ font: v }, 'Change font'),
      })),
      el('div', { class: 'cx-row' }, [
        field('Size', numberInput({ value: style.fontSize || 12, min: 7, max: 44, onChange: (v) => setStyle({ fontSize: v }, 'Change font size') })),
        field('Colour', colorControl({ value: style.textColor || '#ffffff', allowInherit: true, onChange: (v) => setStyle({ textColor: v }, 'Change text colour') })),
      ]),
      field('Style', el('div', { class: 'cx-inline' }, [
        styleToggle('B', 'Bold', style.bold, (v) => setStyle({ bold: v }, 'Toggle bold'), { fontWeight: '800' }),
        styleToggle('I', 'Italic', style.italic, (v) => setStyle({ italic: v }, 'Toggle italic'), { fontStyle: 'italic' }),
        styleToggle('U', 'Underline', style.underline, (v) => setStyle({ underline: v }, 'Toggle underline'), { textDecoration: 'underline' }),
      ])),
      field('Alignment', segmented({
        value: style.align || 'left',
        stretch: true,
        options: [
          { value: 'left', label: 'Left' },
          { value: 'center', label: 'Centre' },
          { value: 'right', label: 'Right' },
        ],
        onChange: (v) => setStyle({ align: v }, 'Change alignment'),
      })),
    ];
  }

  function styleToggle(label, title, active, onChange, extraStyle) {
    return el('button', {
      class: 'cx-btn icon mini' + (active ? ' active' : ''),
      title,
      'aria-label': title,
      'aria-pressed': String(!!active),
      style: extraStyle,
      text: label,
      onClick: () => onChange(!active),
    });
  }

  /* ── Arrange ───────────────────────────────────────────────────────────── */

  function arrangeFields(obj) {
    const ids = [obj.id];
    return [
      el('div', { class: 'cx-inline wrap' }, [
        el('button', { class: 'cx-btn mini', html: icon('chevron-up', { size: 12 }) + '<span>Front</span>', onClick: () => { store.bringToFront(ids); renderer.requestRender(); } }),
        el('button', { class: 'cx-btn mini', html: icon('chevron-down', { size: 12 }) + '<span>Back</span>', onClick: () => { store.sendToBack(ids); renderer.requestRender(); } }),
        el('button', { class: 'cx-btn mini', text: 'Raise', onClick: () => { store.raise(ids); renderer.requestRender(); } }),
        el('button', { class: 'cx-btn mini', text: 'Lower', onClick: () => { store.lower(ids); renderer.requestRender(); } }),
      ]),
      el('div', { class: 'cx-inline wrap' }, [
        toggle({ label: 'Locked', checked: obj.locked, onChange: (v) => set(obj.id, { locked: v }, v ? 'Lock' : 'Unlock') }),
        toggle({ label: 'Hidden', checked: obj.hidden, onChange: (v) => set(obj.id, { hidden: v }, v ? 'Hide' : 'Show') }),
      ]),
      field('Stacking row', numberInput({
        value: obj.row || 0,
        min: 0,
        max: 12,
        onChange: (v) => set(obj.id, { row: clamp(v, 0, 12) }, 'Change row'),
      }), 'Row 0 lets the packer place this object automatically.'),
      obj.groupId
        ? el('button', {
            class: 'cx-btn mini',
            html: icon('unlink', { size: 12 }) + '<span>Ungroup</span>',
            onClick: () => { store.ungroupObjects([obj.id]); renderer.requestRender(); },
          })
        : null,
    ];
  }

  /* ══════════════════════════════════════════════════════════════════════════
     Multiple selection
     ═══════════════════════════════════════════════════════════════════════ */

  function renderMulti(objects) {
    const ids = objects.map((o) => o.id);
    headerFor('Selection', `${objects.length} objects`);


    bodyEl.append(
      el('div', { style: { padding: '11px 12px', borderBottom: '1px solid var(--border)', display: 'flex', flexWrap: 'wrap', gap: '6px' } }, [
        chipStat('Objects', objects.length, 'info'),
        chipStat('Lanes', new Set(objects.map((o) => o.lane)).size, 'muted'),
        chipStat('Types', new Set(objects.map((o) => o.type)).size, 'muted'),
      ]),
      section('Bulk edit', [
        field('Lane', selectInput({
          value: '',
          placeholder: 'Move all to…',
          options: store.orderedLanes().map((l) => ({ value: l.id, label: l.name })),
          onChange: (v) => {
            if (v) {
              store.updateObjects(ids, { lane: v, row: 0 }, 'Move to lane');
              renderer.requestRender();
            }
          },
        })),
        field('Status', managedSelect({
          listId: 'status',
          value: '',
          allowEmpty: true,
          placeholder: 'Set status…',
          onChange: (v) => {
            if (v) {
              store.updateObjects(ids, { status: v }, 'Set status');
              renderer.requestRender();
            }
          },
        })),
        field('Owner', textInput({
          value: '',
          placeholder: 'Set owner for all…',
          onChange: (v) => {
            store.updateObjects(ids, { owner: v }, 'Set owner');
            renderer.requestRender();
          },
        })),
        field('Subsystem', managedSelect({
          listId: 'subsystem',
          value: '',
          allowEmpty: true,
          placeholder: 'Set subsystem…',
          onChange: (v) => {
            if (v) {
              store.updateObjects(ids, { subsystem: v }, 'Set subsystem');
              renderer.requestRender();
            }
          },
        })),
        field('Progress', rangeInput({
          value: Math.round(objects.reduce((sum, o) => sum + o.progress, 0) / objects.length),
          min: 0,
          max: 100,
          step: 5,
          onChange: (v) => {
            store.updateObjects(ids, { progress: v }, 'Set progress');
            renderer.requestRender();
          },
        })),
        field('Fill colour', colorControl({
          value: '#5b93f5',
          onChange: (v) => {
            store.updateObjects(ids, { style: { fill: v } }, 'Set fill');
            renderer.requestRender();
          },
        })),
      ]),
      section('Arrange', [
        el('div', { class: 'cx-inline wrap' }, [
          el('button', { class: 'cx-btn mini', text: 'Align starts', onClick: () => alignStarts(objects) }),
          el('button', { class: 'cx-btn mini', text: 'Align finishes', onClick: () => alignFinishes(objects) }),
          el('button', { class: 'cx-btn mini', text: 'Chain (FS)', onClick: () => chainSelection(objects) }),
          el('button', { class: 'cx-btn mini', text: 'Distribute', onClick: () => distribute(objects) }),
        ]),
        el('div', { class: 'cx-inline wrap' }, [
          el('button', { class: 'cx-btn mini', html: icon('layers', { size: 12 }) + '<span>Group</span>', onClick: () => { store.groupObjects(ids); renderer.requestRender(); } }),
          el('button', { class: 'cx-btn mini', html: icon('unlink', { size: 12 }) + '<span>Ungroup</span>', onClick: () => { store.ungroupObjects(ids); renderer.requestRender(); } }),
          el('button', { class: 'cx-btn mini', text: 'Bring to front', onClick: () => { store.bringToFront(ids); renderer.requestRender(); } }),
          el('button', { class: 'cx-btn mini', text: 'Send to back', onClick: () => { store.sendToBack(ids); renderer.requestRender(); } }),
        ]),
        el('button', {
          class: 'cx-btn mini danger',
          html: icon('trash', { size: 12 }) + `<span>Delete ${objects.length} objects</span>`,
          onClick: async () => {
            const ok = await confirmDialog({
              title: `Delete ${objects.length} objects`,
              message: 'This also removes any dependencies attached to them. You can undo this.',
              confirmLabel: 'Delete',
              danger: true,
            });
            if (ok) {
              store.removeObjects(ids);
              renderer.requestRender();
            }
          },
        }),
      ])
    );
  }

  function alignStarts(objects) {
    const target = Math.min(...objects.map((o) => o.start));
    store.updateObjects(objects.map((o) => o.id), (obj) => {
      const shift = target - obj.start;
      return TYPES[obj.type]?.duration ? { start: target, end: obj.end + shift } : { start: target };
    }, 'Align starts');
    renderer.requestRender();
  }

  function alignFinishes(objects) {
    const target = Math.max(...objects.map((o) => (TYPES[o.type]?.duration ? o.end : o.start)));
    store.updateObjects(objects.map((o) => o.id), (obj) => {
      if (!TYPES[obj.type]?.duration) return { start: target };
      const shift = target - obj.end;
      return { start: obj.start + shift, end: target };
    }, 'Align finishes');
    renderer.requestRender();
  }

  /** Lay the selection end-to-end in date order and link them finish-to-start. */
  function chainSelection(objects) {
    const ordered = objects.slice().sort((a, b) => a.start - b.start);
    let cursor = ordered[0].start;
    for (const obj of ordered) {
      const duration = TYPES[obj.type]?.duration ? obj.end - obj.start : 0;
      store.updateObject(obj.id, { start: cursor, end: cursor + duration }, 'Chain objects');
      cursor += duration || MS_DAY;
    }
    for (let i = 1; i < ordered.length; i++) {
      store.addLink({ from: ordered[i - 1].id, to: ordered[i].id, type: 'FS' });
    }
    renderer.requestRender();
  }

  /** Even out the gaps between the selection's start dates. */
  function distribute(objects) {
    const ordered = objects.slice().sort((a, b) => a.start - b.start);
    if (ordered.length < 3) return;
    const first = ordered[0].start;
    const last = ordered[ordered.length - 1].start;
    const step = (last - first) / (ordered.length - 1);
    ordered.forEach((obj, i) => {
      const target = first + step * i;
      const shift = target - obj.start;
      store.updateObject(obj.id, TYPES[obj.type]?.duration ? { start: target, end: obj.end + shift } : { start: target }, 'Distribute');
    });
    renderer.requestRender();
  }

  /* ══════════════════════════════════════════════════════════════════════════
     Dependency
     ═══════════════════════════════════════════════════════════════════════ */

  function renderLink(linkId) {
    const doc = store.getDoc();
    const link = doc.links.find((l) => l.id === linkId);
    if (!link) {
      renderProject();
      return;
    }
    const from = store.getObject(link.from);
    const to = store.getObject(link.to);
    const violated = !!linkViolations(doc).byLink.get(link.id)?.violated;

    headerFor('Dependency', `${from?.title || '?'} → ${to?.title || '?'}`, [
      // A broken dependency cannot be hidden — it would only reappear on its
      // own the moment this render committed, so the button that would do
      // nothing is not offered at all.
      violated
        ? null
        : el('button', {
            class: 'cx-btn icon mini ghost',
            title: link.hidden ? 'Show dependency' : 'Hide dependency',
            'aria-label': link.hidden ? 'Show dependency line' : 'Hide dependency line',
            html: icon(link.hidden ? 'eye' : 'eye-off', { size: 13 }),
            onClick: () => {
              toggleLinkHidden(link.id);
              render();
            },
          }),
      el('button', {
        class: 'cx-btn icon mini ghost',
        title: 'Delete dependency',
        'aria-label': 'Delete dependency',
        html: icon('trash', { size: 13 }),
        onClick: () => {
          store.removeLinks([link.id]);
          renderer.setSelectedLinks([]);
          renderer.requestRender();
          render();
        },
      }),
    ]);

